import { supabase } from '../supabaseClient';

/**
 * A generic data service that mimics the previous LocalStorage behavior
 * but persists data to Supabase tables using a JSONB 'data' column.
 */
class DataService {

    // Generic Fetch
    async getAll<T>(tableName: string, localStorageKey: string): Promise<T[]> {
        // 1. Try Supabase
        try {
            const { data, error } = await supabase
                .from(tableName)
                .select('data');

            if (error) {
                // Determine if it's a connection error or missing table
                // We log as warn to avoid cluttering console with "Errors" during development/offline
                console.warn(`[DataService] Supabase fetch failed for '${tableName}' (using local fallback). Details: ${error.message}`);
                throw error;
            }

            if (data) {
                return data.map(row => row.data);
            }
            return [];
        } catch (error) {
            // 2. Fallback to LocalStorage
            const local = localStorage.getItem(localStorageKey);
            return local ? JSON.parse(local) : [];
        }
    }

    // Generic Save (Upsert)
    async save<T extends { id: string | number }>(tableName: string, localStorageKey: string, item: T) {
        // 1. Always save to LocalStorage first (Optimistic & Offline Safety)
        try {
            const currentLocal = JSON.parse(localStorage.getItem(localStorageKey) || '[]');
            const index = currentLocal.findIndex((i: any) => String(i.id) === String(item.id));
            let newLocal;
            if (index >= 0) {
                newLocal = [...currentLocal];
                newLocal[index] = item;
            } else {
                newLocal = [...currentLocal, item];
            }
            localStorage.setItem(localStorageKey, JSON.stringify(newLocal));
        } catch (e) {
            console.error(`[DataService] Error writing to localStorage for '${localStorageKey}'`, e);
        }

        // 2. Try to sync with Supabase
        try {
            // Cast ID to string to ensure compatibility with text primary keys
            const { error } = await supabase
                .from(tableName)
                .upsert({ id: String(item.id), data: item });

            if (error) {
                console.warn(`[DataService] Supabase save failed for '${tableName}': ${error.message}`);
            }
        } catch (error) {
            console.warn(`[DataService] Supabase connection failed during save for '${tableName}'.`);
        }
    }

    // Generic Delete
    async delete(tableName: string, localStorageKey: string, id: string | number) {
        // 1. Update LocalStorage first
        try {
            const currentLocal = JSON.parse(localStorage.getItem(localStorageKey) || '[]');
            const newLocal = currentLocal.filter((i: any) => String(i.id) !== String(id));
            localStorage.setItem(localStorageKey, JSON.stringify(newLocal));
        } catch (e) {
            console.error(`[DataService] Error deleting from localStorage for '${localStorageKey}'`, e);
        }

        // 2. Try to delete from Supabase
        try {
            const { error } = await supabase
                .from(tableName)
                .delete()
                .eq('id', String(id));

            if (error) {
                console.warn(`[DataService] Supabase delete failed for '${tableName}': ${error.message}`);
            }
        } catch (error) {
            console.warn(`[DataService] Supabase connection failed during delete for '${tableName}'.`);
        }
    }
}

