                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div><label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Data do Orçamento</label><input type="date" name="dataOrcamento" value={formState.dataOrcamento} readOnly className="w-full rounded-lg border-gray-300 dark:border-gray-600 bg-gray-200 dark:bg-gray-700 p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none text-gray-500 dark:text-gray-400 font-bold cursor-not-allowed opacity-80" /></div>
                            <div><label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Nome do Cliente</label><input type="text" name="nomeCliente" value={formState.nomeCliente} onChange={handleInputChange} className="w-full rounded-lg border-gray-300 dark:border-gray-600 bg-yellow-100 dark:bg-yellow-900/30 p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 dark:text-white font-bold" placeholder="Ex: João Silva" /></div>
                            <div><label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Revendedor</label><input type="text" name="revendedor" value={formState.revendedor} onChange={handleInputChange} className="w-full rounded-lg border-gray-300 dark:border-gray-600 bg-yellow-100 dark:bg-yellow-900/30 p-2.5 text-sm focus:ring-2 focus:ring-indigo-500 outline-none text-gray-900 dark:text-white font-bold" /></div>
