                    </div>

                    <div className="bg-white dark:bg-gray-800 rounded-xl shadow-sm border border-gray-200 dark:border-gray-700 p-6">
                        <h3 className="text-sm font-bold text-gray-900 dark:text-white uppercase tracking-wider border-b border-gray-100 dark:border-gray-700 pb-3 mb-4 flex items-center gap-2"><span className="w-1 h-4 bg-orange-500 rounded-full"></span> Custos de Instalação e Terceiros</h3>
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                            {[{ label: "Visita Técnica", name: "visitaTecnicaCusto" }, { label: "Projeto / Homologação", name: "projetoHomologacaoCusto" }, { label: "Custo de Viagem", name: "custoViagem" }, { label: "Adequação Local", name: "adequacaoLocalCusto" }].map(field => (<div key={field.name}><label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">{field.label}</label><div className="relative"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 text-xs font-bold">R$</span><input type="number" name={field.name} value={(formState as any)[field.name]} onChange={handleInputChange} className="w-full pl-8 rounded-lg border-gray-300 dark:border-gray-600 bg-yellow-100 dark:bg-yellow-900/30 font-bold text-gray-900 dark:text-white p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" /></div></div>))}
                            <div>
                                <div className="flex justify-between items-center mb-1"><label className="block text-xs font-medium text-gray-500 dark:text-gray-400">Instalação Terceirizada</label><span className="text-[10px] font-bold text-gray-700 dark:text-gray-300 bg-gray-100 dark:bg-gray-700 px-1.5 py-0.5 rounded">Total: {formatCurrency(formState.terceiroInstalacaoQtd * formState.terceiroInstalacaoCusto)}</span></div>
                                <div className="flex items-center gap-2"><div className="relative w-20"><input type="number" name="terceiroInstalacaoQtd" value={formState.terceiroInstalacaoQtd} onChange={handleInputChange} className="w-full rounded-lg border-gray-300 dark:border-gray-600 bg-yellow-100 dark:bg-yellow-900/30 font-bold text-gray-900 dark:text-white p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none text-center" placeholder="Qtd" /></div><span className="text-gray-400 text-xs">x</span><div className="relative flex-1"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-xs font-bold">R$</span><input type="number" name="terceiroInstalacaoCusto" value={formState.terceiroInstalacaoCusto} onChange={handleInputChange} className="w-full pl-8 rounded-lg border-gray-300 dark:border-gray-600 bg-yellow-100 dark:bg-yellow-900/30 font-bold text-gray-900 dark:text-white p-2 text-sm focus:ring-2 focus:ring-indigo-500 outline-none" placeholder="Unitário" /></div></div>
                            </div>
