                        <div className="overflow-x-auto">
                            <table className="w-full text-sm text-left"><thead className="text-xs text-gray-500 bg-gray-50 dark:bg-gray-700 dark:text-gray-400 uppercase"><tr><th className="px-6 py-3">Item / Descrição</th><th className="px-6 py-3 text-center w-24">Qtd</th><th className="px-6 py-3 text-right w-32">Custo Unit.</th><th className="px-6 py-3 text-right w-32">Total</th><th className="px-2 py-3 w-10"></th></tr></thead><tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                                {estruturaItems.map((item) => { const qtd = (formState as any)[`${item.key}Qtd`] || 0; const custo = (formState as any)[`${item.key}Custo`] || 0; return (<tr key={item.key} className="hover:bg-gray-50 dark:hover:bg-gray-700/50"><td className="px-6 py-2 font-medium text-gray-900 dark:text-white">{item.label}</td><td className="px-6 py-2"><input type="number" name={`${item.key}Qtd`} value={qtd} onChange={handleInputChange} className="w-full text-center bg-transparent border-b border-gray-300 focus:border-indigo-500 outline-none py-1" /></td><td className="px-6 py-2"><input type="number" name={`${item.key}Custo`} value={custo} onChange={handleInputChange} className="w-full text-right bg-transparent border-b border-gray-300 focus:border-indigo-500 outline-none py-1" /></td><td className="px-6 py-2 text-right font-medium text-gray-600 dark:text-gray-300">{formatCurrency(qtd * custo)}</td><td></td></tr>); })}
                                {formState.extraItems && formState.extraItems.map((item) => (<tr key={item.id} className="hover:bg-yellow-50 dark:hover:bg-yellow-900/10"><td className="px-6 py-2"><input type="text" value={item.name} onChange={(e) => updateExtraItem(item.id, 'name', e.target.value)} placeholder="Nome do componente" className="w-full bg-transparent border-b border-gray-300 focus:border-indigo-500 outline-none py-1 text-gray-900 dark:text-white" /></td><td className="px-6 py-2"><input type="number" value={item.quantity} onChange={(e) => updateExtraItem(item.id, 'quantity', parseFloat(e.target.value) || 0)} className="w-full text-center bg-transparent border-b border-gray-300 focus:border-indigo-500 outline-none py-1" /></td><td className="px-6 py-2"><input type="number" value={item.cost} onChange={(e) => updateExtraItem(item.id, 'cost', parseFloat(e.target.value) || 0)} className="w-full text-right bg-transparent border-b border-gray-300 focus:border-indigo-500 outline-none py-1" /></td><td className="px-6 py-2 text-right font-medium text-gray-600 dark:text-gray-300">{formatCurrency(item.quantity * item.cost)}</td><td className="px-2 py-2 text-center"><button onClick={() => removeExtraItem(item.id)} className="text-red-400 hover:text-red-600 p-1" title="Remover Item"><TrashIcon className="w-4 h-4" /></button></td></tr>))}
                            </tbody></table>
                            <div className="p-3 bg-gray-50 dark:bg-gray-700/30 border-t border-gray-200 dark:border-gray-700 flex justify-center"><button onClick={addExtraItem} className="flex items-center gap-2 text-sm font-medium text-indigo-600 dark:text-indigo-400 hover:text-indigo-800 dark:hover:text-indigo-300 transition-colors"><AddIcon className="w-4 h-4" /> Adicionar Componente Extra</button></div>
                        </div>
                    </div>
                </div>

                <div className="lg:col-span-4 space-y-6">
                    <div className="sticky top-6 space-y-6">
                        <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg border border-indigo-100 dark:border-gray-700 overflow-hidden">
                            <div className="bg-indigo-600 p-4 text-white"><h3 className="font-bold flex items-center gap-2"><DollarIcon className="w-5 h-5" /> Fechamento Financeiro</h3></div>
                            <div className="p-6 space-y-4">
                                <div className="flex justify-between items-center text-sm"><span className="text-gray-500 dark:text-gray-400">Custo do Sistema</span><span className="font-medium text-gray-900 dark:text-white">{formatCurrency(calculated.valorVendaSistema)}</span></div>
                                <div className="flex justify-between items-center text-sm"><span className="text-gray-500 dark:text-gray-400">Custo Mão de Obra Total</span><span className="font-medium text-gray-900 dark:text-white">{formatCurrency(calculated.custoMO)}</span></div>
                                <div className="border-t border-gray-100 dark:border-gray-700 pt-3 flex justify-between items-center"><span className="text-lg font-bold text-gray-800 dark:text-white">Preço Venda</span><span className="text-xl font-bold text-indigo-600 dark:text-indigo-400">{formatCurrency(calculated.precoVendaFinal)}</span></div>
                            </div>
                            <div className="bg-gray-50 dark:bg-gray-900/50 p-6 border-t border-gray-200 dark:border-gray-700 space-y-4">
                                <h4 className="text-xs font-bold text-gray-500 uppercase tracking-wide mb-3">Impostos e Comissões</h4>
                                <div className="flex items-center justify-between"><label className="text-sm text-gray-600 dark:text-gray-400">NF Serviço (%)</label><div className="flex items-center gap-2"><input type="number" name="nfServicoPerc" value={formState.nfServicoPerc} onChange={handleInputChange} className="w-16 text-right rounded border-gray-300 p-1 text-sm bg-white" /><span className="text-sm font-medium w-20 text-right">{formatCurrency(calculated.nfServicoValor)}</span></div></div>
                                <div className="flex items-center justify-between"><label className="text-sm text-gray-600 dark:text-gray-400">Comissão Venda</label><div className="flex items-center gap-2"><select name="comissaoVendasOpcao" value={formState.comissaoVendasOpcao} onChange={handleInputChange} className="rounded border-gray-300 p-1 text-xs bg-white"><option value="Não">Não</option><option value="Sim">Sim</option></select>{formState.comissaoVendasOpcao === 'Sim' && <input type="number" name="comissaoVendasPerc" value={formState.comissaoVendasPerc} onChange={handleInputChange} className="w-12 text-right rounded border-gray-300 p-1 text-sm bg-white" />}<span className="text-sm font-medium w-20 text-right">{formatCurrency(calculated.comissaoVendasValor)}</span></div></div>
                                <div className="flex items-center justify-between"><label className="text-sm text-gray-600 dark:text-gray-400">Desconto (%)</label><div className="flex items-center gap-2"><input type="number" name="descontoAplicadoPerc" value={formState.descontoAplicadoPerc} onChange={handleInputChange} className="w-16 text-right rounded border-gray-300 p-1 text-sm bg-white" /><span className="text-sm font-medium w-20 text-right text-red-500">-{formatCurrency(calculated.descontoAplicadoValor)}</span></div></div>
                            </div>
                            <div className="bg-green-50 dark:bg-green-900/20 p-4 border-t border-green-100 dark:border-green-800 text-center"><p className="text-xs text-green-600 dark:text-green-400 uppercase font-bold tracking-wide mb-1">Lucro Líquido Real</p><p className="text-2xl font-bold text-green-700 dark:text-green-300">{formatCurrency(calculated.lucroLiquido)}</p></div>
                        </div>
                    </div>
                </div>
            </div>

            {isModalOpen && (<Modal title="Ajustar Margem de Serviço" onClose={() => setModalOpen(false)}><div className="space-y-4"><label htmlFor="desiredMargin" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Margem Líquida Final Desejada (%)</label><div className="relative"><input type="number" id="desiredMargin" value={desiredMargin} onChange={(e) => setDesiredMargin(e.target.value)} className="w-full text-right rounded-md border-gray-300 dark:border-gray-600 bg-yellow-50 dark:bg-yellow-900/10 font-bold text-gray-900 dark:text-yellow-100 focus:ring-indigo-500 focus:border-indigo-500 pr-8 p-2" placeholder="ex: 60" /><span className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 font-bold">%</span></div><div className="flex justify-end pt-4"><button onClick={handleMarginCalculation} className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500">Calcular</button></div></div></Modal>)}
            {isRenameModalOpen && (<Modal title="Renomear Opção" onClose={() => setRenameModalOpen(false)}><div className="space-y-4"><label htmlFor="variantName" className="block text-sm font-medium text-gray-700 dark:text-gray-300">Nome da Opção</label><input type="text" id="variantName" value={tempVariantName} onChange={(e) => setTempVariantName(e.target.value)} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 p-2" /><div className="flex justify-end pt-4 gap-2"><button type="button" onClick={() => setRenameModalOpen(false)} className="px-4 py-2 bg-gray-200 rounded-md text-gray-700 hover:bg-gray-300">Cancelar</button><button onClick={finishRename} className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700">Salvar</button></div></div></Modal>)}
            {isSaveModalOpen && (<Modal title={orcamentoToEdit ? "Atualizar Projeto" : "Salvar Projeto"} onClose={() => setSaveModalOpen(false)}><div className="space-y-6"><div className="text-center"><div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-green-100 mb-4"><SaveIcon className="w-6 h-6 text-green-600" /></div><h3 className="text-lg font-medium text-gray-900 dark:text-white">{orcamentoToEdit ? "Deseja atualizar o projeto?" : "Deseja salvar o projeto?"}</h3></div><div className="flex justify-center gap-4"><button onClick={() => setSaveModalOpen(false)} className="px-6 py-2 bg-red-100 text-red-700 rounded-md hover:bg-red-200 font-medium transition-colors w-24">Não</button><button onClick={executeSave} className="px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-medium transition-colors w-24">Sim</button></div></div></Modal>)}
        </div>
    );
};

export default NovoOrcamentoPage;

import React, { useState, useMemo, useEffect } from 'react';
import { ChartPieIcon, PrinterIcon, PlusIcon, TrashIcon, CogIcon, SaveIcon, EditIcon, ClipboardListIcon, CheckCircleIcon, DollarIcon, ExclamationTriangleIcon, DocumentReportIcon } from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip as RechartsTooltip, Legend, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';
import type { RelatoriosPageProps, ExpenseReportItem, ExpenseReport, ExpenseReportStatus } from '../types';
import { dataService } from '../services/dataService';

const RelatoriosPage: React.FC<RelatoriosPageProps> = ({ view, reportToEdit, onSave, onEditReport }) => {
  // --- REIMBURSEMENT STATE ---
  const [solicitante, setSolicitante] = useState('');
  const [setor, setSetor] = useState('');
  const [periodStart, setPeriodStart] = useState('');
  const [periodEnd, setPeriodEnd] = useState('');
  const [valorPorKm, setValorPorKm] = useState(1.20);

  // Config View State
  const [configKmValue, setConfigKmValue] = useState(1.20);
  const [isEditingConfig, setIsEditingConfig] = useState(false);
  const [isSuccessModalOpen, setSuccessModalOpen] = useState(false);
  const [modalMessage, setModalMessage] = useState('');

  // Payment Modal State
  const [isPayModalOpen, setPayModalOpen] = useState(false);
  const [reportToPay, setReportToPay] = useState<ExpenseReport | null>(null);

  // Transfer Modal State
  const [isTransferModalOpen, setTransferModalOpen] = useState(false);

  // History State
  const [reports, setReports] = useState<ExpenseReport[]>([]);

  const [items, setItems] = useState<ExpenseReportItem[]>([
    { id: '1', date: '', description: '', origin: '', destination: '', km: 0, toll: 0 },
  ]);

  // Load Reports from DB
  useEffect(() => {
      const loadReports = async () => {
          const data = await dataService.getAll<ExpenseReport>('expense_reports', 'expense_reports');
          setReports(data);
      };
      loadReports();
  }, []);

  // Load Config/Data based on View
  useEffect(() => {
    if (view === 'reembolso') {
        if (reportToEdit) {
            setSolicitante(reportToEdit.requester);
            setSetor(reportToEdit.sector);
            setPeriodStart(reportToEdit.periodStart || '');
            setPeriodEnd(reportToEdit.periodEnd || '');
            setItems(reportToEdit.items);
            setValorPorKm(reportToEdit.kmValueUsed);
        } else {
            setSolicitante('');
            setSetor('');
            setPeriodStart('');
            setPeriodEnd('');
            setItems([{ id: Date.now().toString(), date: '', description: '', origin: '', destination: '', km: 0, toll: 0 }]);

            const savedValue = localStorage.getItem('reembolso_config_km_value');
            if (savedValue) {
                setValorPorKm(parseFloat(savedValue));
            }
        }
    }
  }, [view, reportToEdit]);

  // Load Config View
  useEffect(() => {
    if (view === 'config') {
        const savedValue = localStorage.getItem('reembolso_config_km_value');
        if (savedValue) {
            setConfigKmValue(parseFloat(savedValue));
        }
        setIsEditingConfig(false); 
    }
  }, [view]);

  const isReadOnly = useMemo(() => {
      if (!reportToEdit) return false;
      return reportToEdit.status === 'Transferido' || reportToEdit.status === 'Pago';
  }, [reportToEdit]);

  const handleAddItem = () => setItems([...items, { id: Date.now().toString(), date: '', description: '', origin: '', destination: '', km: 0, toll: 0 }]);
  const handleRemoveItem = (id: string) => { if (items.length > 1) setItems(items.filter(item => item.id !== id)); };
  const handleItemChange = (id: string, field: keyof ExpenseReportItem, value: string | number) => setItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));

  const handleSaveConfig = () => {
      localStorage.setItem('reembolso_config_km_value', configKmValue.toString());
      setIsEditingConfig(false);
      setModalMessage("O novo valor do quilômetro foi atualizado com sucesso.");
      setSuccessModalOpen(true);
  }

  const handleCancelConfig = () => {
      const savedValue = localStorage.getItem('reembolso_config_km_value');
      if (savedValue) setConfigKmValue(parseFloat(savedValue));
      setIsEditingConfig(false);
  }

  const totals = useMemo(() => {
    return items.reduce((acc, item) => {
      const reembolsoKm = Math.ceil((item.km * valorPorKm) * 100) / 100;
      const totalRow = Math.ceil((reembolsoKm + item.toll) * 100) / 100;
      return { km: acc.km + item.km, reembolsoKm: acc.reembolsoKm + reembolsoKm, toll: acc.toll + item.toll, total: acc.total + totalRow };
    }, { km: 0, reembolsoKm: 0, toll: 0, total: 0 });
  }, [items, valorPorKm]);

  const executeSave = async (targetStatus: ExpenseReportStatus) => {
      const formatDate = (dateStr: string) => {
          if(!dateStr) return '';
          const [y, m, d] = dateStr.split('-');
          return `${d}/${m}/${y}`;
      };
      const periodString = `${formatDate(periodStart)} a ${formatDate(periodEnd)}`;

      const reportToSave: ExpenseReport = {
          id: reportToEdit ? reportToEdit.id : Date.now().toString(),
          requester: solicitante,
          sector: setor,
          period: periodString,
          periodStart: periodStart,
          periodEnd: periodEnd,
          items: items,
          kmValueUsed: valorPorKm,
          status: targetStatus,
          createdAt: reportToEdit ? reportToEdit.createdAt : new Date().toISOString(),
          totalValue: totals.total
      };

      try {
          await dataService.save('expense_reports', 'expense_reports', reportToSave);

          setReports(prev => {
              if (reportToEdit) return prev.map(r => r.id === reportToSave.id ? reportToSave : r);
              return [reportToSave, ...prev];
          });

          setModalMessage(targetStatus === 'Transferido' ? "Relatório transferido com sucesso!" : "Rascunho salvo com sucesso!");
          setSuccessModalOpen(true);

          if (onSave) setTimeout(() => { setSuccessModalOpen(false); onSave(); }, 2000);
          else setTimeout(() => setSuccessModalOpen(false), 2000);
      } catch (e) {
          alert('Erro ao salvar relatório.');
      }
  };

  const handleSaveReportAction = (targetStatus: ExpenseReportStatus) => {
      if (!solicitante || !periodStart || !periodEnd) {
          alert("Preencha o Solicitante e as datas do Período.");
          return;
      }
      if (targetStatus === 'Transferido') setTransferModalOpen(true);
      else executeSave('Rascunho');
  };

  const handleDeleteReport = async (id: string) => {
      if (window.confirm("Tem certeza que deseja excluir este relatório?")) {
          await dataService.delete('expense_reports', 'expense_reports', id);
          setReports(prev => prev.filter(r => r.id !== id));
      }
  };

  const handleConfirmPay = async () => {
      if (reportToPay) {
          const updatedReport = { ...reportToPay, status: 'Pago' as ExpenseReportStatus };
          await dataService.save('expense_reports', 'expense_reports', updatedReport);
          setReports(prev => prev.map(r => r.id === reportToPay.id ? updatedReport : r));
          setPayModalOpen(false);
          setReportToPay(null);
      }
  }

  const formatCurrency = (val: number) => {
      if (isNaN(val)) return 'R$ 0,00';
      const rounded = Math.ceil(val * 100) / 100;
      return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(rounded);
  };

  const handlePrint = () => window.print();

  const analysisData = useMemo(() => {
      const paid = reports.filter(r => r.status === 'Pago').reduce((acc, r) => acc + r.totalValue, 0);
      const pending = reports.filter(r => r.status === 'Transferido').reduce((acc, r) => acc + r.totalValue, 0);
      const open = reports.filter(r => ['Rascunho', 'Em Aberto'].includes(r.status)).reduce((acc, r) => acc + r.totalValue, 0);

      const sectorMap: Record<string, number> = {};
      reports.forEach(r => {
          if (r.status === 'Pago' || r.status === 'Transferido') {
              const sec = r.sector ? r.sector.toUpperCase() : 'N/A';
              sectorMap[sec] = (sectorMap[sec] || 0) + r.totalValue;
          }
      });
      const sectorData = Object.entries(sectorMap).map(([name, value]) => ({ name, value }));

      const monthMap: Record<string, number> = {};
      reports.forEach(r => {
          if (r.status === 'Pago' || r.status === 'Transferido') {
              const date = new Date(r.createdAt);
              const key = `${date.getMonth() + 1}/${date.getFullYear()}`;
              monthMap[key] = (monthMap[key] || 0) + r.totalValue;
          }
      });
      const monthlyData = Object.entries(monthMap).map(([name, value]) => ({ name, value }));

      return { paid, pending, open, sectorData, monthlyData };
  }, [reports]);

  const PIE_COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d'];

  if (view === 'status') {
      const pendingReports = reports.filter(r => r.status === 'Transferido' || r.status === 'Em Aberto');
      return (
          <div className="space-y-6">
               <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                   <div className="flex justify-between items-center mb-6">
                       <div><h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3"><CheckCircleIcon className="w-8 h-8 text-indigo-600" /> Relatórios Aguardando Pagamento</h2><p className="text-gray-500 dark:text-gray-400 mt-1">Confirme o pagamento dos relatórios transferidos.</p></div>
                   </div>
                   <div className="overflow-x-auto">
                       <table className="min-w-full text-left text-sm">
                           <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider"><tr><th className="px-6 py-3">Data Criação</th><th className="px-6 py-3">Solicitante</th><th className="px-6 py-3">Período</th><th className="px-6 py-3">Valor Total</th><th className="px-6 py-3 text-center">Status</th><th className="px-6 py-3 text-center">Ações</th></tr></thead>
                           <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                               {pendingReports.map(report => (
                                   <tr key={report.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{new Date(report.createdAt).toLocaleDateString('pt-BR')}</td>
                                       <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{report.requester}</td>
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{report.period}</td>
                                       <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">{formatCurrency(report.totalValue)}</td>
                                       <td className="px-6 py-4 text-center"><span className="px-2 py-1 text-xs font-semibold rounded-full bg-yellow-100 text-yellow-800">Aguardando Pagamento</span></td>
                                       <td className="px-6 py-4 text-center space-x-2"><button onClick={() => {setReportToPay(report); setPayModalOpen(true);}} className="px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 text-xs font-medium transition-colors shadow-sm">Confirmar Pagamento</button></td>
                                   </tr>
                               ))}
                               {pendingReports.length === 0 && <tr><td colSpan={6} className="px-6 py-12 text-center text-gray-500">Não há relatórios aguardando pagamento.</td></tr>}
                           </tbody>
                       </table>
                   </div>
               </div>
               {isPayModalOpen && reportToPay && (<Modal title="Confirmar Pagamento" onClose={() => setPayModalOpen(false)}><div className="space-y-6"><div className="text-center"><div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-yellow-100 mb-4"><span className="text-2xl">?</span></div><h3 className="text-lg font-medium text-gray-900 dark:text-white">Confirmar Pagamento</h3><p className="text-sm text-gray-500 dark:text-gray-400 mt-2">Deseja confirmar o pagamento do relatório de <strong>{reportToPay.requester}</strong> no valor de <strong>{formatCurrency(reportToPay.totalValue)}</strong>?</p></div><div className="flex justify-center gap-4"><button onClick={() => setPayModalOpen(false)} className="px-4 py-2 bg-red-100 text-red-700 rounded-md hover:bg-red-200 font-medium transition-colors w-24">Não</button><button onClick={handleConfirmPay} className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-medium transition-colors w-24">Sim</button></div></div></Modal>)}
          </div>
      );
  }

  if (view === 'historico') {
      return (
          <div className="space-y-6">
               <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                   <div className="flex justify-between items-center mb-6"><div><h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3"><ClipboardListIcon className="w-8 h-8 text-indigo-600" /> Histórico de Relatórios</h2><p className="text-gray-500 dark:text-gray-400 mt-1">Acompanhe todos os relatórios gerados.</p></div></div>
                   <div className="overflow-x-auto">
                       <table className="min-w-full text-left text-sm">
                           <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider"><tr><th className="px-6 py-3">Data Criação</th><th className="px-6 py-3">Solicitante</th><th className="px-6 py-3">Período</th><th className="px-6 py-3">Valor Total</th><th className="px-6 py-3 text-center">Status</th><th className="px-6 py-3 text-center">Ações</th></tr></thead>
                           <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                               {reports.map(report => (
                                   <tr key={report.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{new Date(report.createdAt).toLocaleDateString('pt-BR')}</td>
                                       <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{report.requester}</td>
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{report.period}</td>
                                       <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">{formatCurrency(report.totalValue)}</td>
                                       <td className="px-6 py-4 text-center"><span className={`px-2 py-1 rounded-full text-xs font-semibold ${report.status === 'Pago' ? 'bg-green-100 text-green-800' : report.status === 'Transferido' ? 'bg-yellow-100 text-yellow-800' : 'bg-gray-200 text-gray-800'}`}>{report.status}</span></td>
                                       <td className="px-6 py-4 text-center space-x-2"><button onClick={() => onEditReport && onEditReport(report)} className="p-2 text-gray-500 hover:text-indigo-600 dark:text-gray-400 dark:hover:text-indigo-400" title={report.status === 'Rascunho' || report.status === 'Em Aberto' ? "Editar" : "Visualizar"}><EditIcon className="w-5 h-5" /></button><button onClick={() => handleDeleteReport(report.id)} className="p-2 text-gray-500 hover:text-red-600 dark:text-gray-400 dark:hover:text-red-400" title="Excluir"><TrashIcon className="w-5 h-5" /></button></td>
                                   </tr>
                               ))}
                               {reports.length === 0 && <tr><td colSpan={6} className="px-6 py-12 text-center text-gray-500">Nenhum relatório salvo no histórico.</td></tr>}
                           </tbody>
                       </table>
                   </div>
               </div>
          </div>
      );
  }

  if (view === 'config') {
      return (
          <div className="max-w-xl mx-auto space-y-6">
              <div className="bg-white dark:bg-gray-800 p-8 rounded-xl shadow-lg">
                  <div className="flex items-center gap-4 mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                      <div className="p-3 bg-indigo-100 dark:bg-indigo-900 rounded-full"><CogIcon className="w-8 h-8 text-indigo-600 dark:text-indigo-400" /></div>
                      <div><h2 className="text-2xl font-bold text-gray-900 dark:text-white">Cadastro de KM</h2><p className="text-gray-500 dark:text-gray-400">Defina o valor padrão a ser pago por quilômetro rodado.</p></div>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Valor por Quilômetro (R$)</label>
                          <div className="relative rounded-md shadow-sm"><div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3"><span className="text-gray-500 sm:text-sm">R$</span></div><input type="number" step="0.01" min="0" value={configKmValue} onChange={(e) => setConfigKmValue(parseFloat(e.target.value))} disabled={!isEditingConfig} className={`block w-full rounded-md border-gray-300 dark:border-gray-600 pl-10 focus:ring-indigo-500 focus:border-indigo-500 sm:text-lg py-3 transition-colors ${!isEditingConfig ? 'bg-gray-100 dark:bg-gray-700 text-gray-500 cursor-not-allowed' : 'bg-white dark:bg-gray-600 text-gray-900 dark:text-white'}`} placeholder="0.00" /></div>
                      </div>
                      <div className="pt-4 flex justify-end gap-3">{!isEditingConfig ? (<button onClick={() => setIsEditingConfig(true)} className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-medium shadow-md"><EditIcon className="w-5 h-5" /> Editar Valor</button>) : (<><button onClick={handleCancelConfig} className="px-6 py-3 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors font-medium">Cancelar</button><button onClick={handleSaveConfig} className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors font-medium shadow-md"><SaveIcon className="w-5 h-5" /> Salvar</button></>)}</div>
                  </div>
              </div>
              {isSuccessModalOpen && (<Modal title="Sucesso" onClose={() => setSuccessModalOpen(false)}><div className="text-center space-y-4 py-4"><div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-green-100"><svg className="h-6 w-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg></div><h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white">Alteração Salva</h3><p className="text-sm text-gray-500 dark:text-gray-400">{modalMessage}</p><div className="mt-6"><button type="button" className="inline-flex justify-center w-full rounded-md border border-transparent shadow-sm px-4 py-2 bg-indigo-600 text-base font-medium text-white hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 sm:text-sm" onClick={() => setSuccessModalOpen(false)}>OK</button></div></div></Modal>)}
          </div>
      );
  }

  if (view === 'analise') {
    return (
        <div className="space-y-6">
             <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                <DashboardCard title="Reembolsos Pagos" value={formatCurrency(analysisData.paid)} icon={CheckCircleIcon} color="bg-green-500" />
                <DashboardCard title="Aguardando Pagamento" value={formatCurrency(analysisData.pending)} icon={ExclamationTriangleIcon} color="bg-yellow-500" />
                <DashboardCard title="Em Aberto (Rascunhos)" value={formatCurrency(analysisData.open)} icon={DocumentReportIcon} color="bg-gray-500" />
             </div>
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                 <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg min-h-[400px]"><h3 className="text-xl font-bold text-gray-900 dark:text-white mb-4">Despesas por Setor</h3>{analysisData.sectorData.length > 0 ? (<ResponsiveContainer width="100%" height={300}><PieChart><Pie data={analysisData.sectorData} cx="50%" cy="50%" innerRadius={60} outerRadius={100} fill="#8884d8" paddingAngle={5} dataKey="value" label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}>{analysisData.sectorData.map((entry, index) => (<Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />))}</Pie><RechartsTooltip formatter={(value) => formatCurrency(Number(value))} /><Legend /></PieChart></ResponsiveContainer>) : (<div className="h-full flex flex-col items-center justify-center text-gray-400"><ChartPieIcon className="w-16 h-16 mb-2 opacity-50" /><p>Sem dados de setores registrados.</p></div>)}</div>
                 <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg min-h-[400px]"><h3 className="text-xl font-bold text-gray-900 dark:text-white mb-4">Evolução Mensal (Pagos e Transferidos)</h3>{analysisData.monthlyData.length > 0 ? (<ResponsiveContainer width="100%" height={300}><BarChart data={analysisData.monthlyData}><CartesianGrid strokeDasharray="3 3" vertical={false} opacity={0.3} /><XAxis dataKey="name" tick={{fill: '#9CA3AF'}} /><YAxis tick={{fill: '#9CA3AF'}} /><RechartsTooltip contentStyle={{ backgroundColor: '#1F2937', borderColor: '#374151', color: '#F3F4F6' }} formatter={(value) => [formatCurrency(Number(value)), 'Valor']} /><Bar dataKey="value" fill="#6366F1" radius={[4, 4, 0, 0]} /></BarChart></ResponsiveContainer>) : (<div className="h-full flex flex-col items-center justify-center text-gray-400"><DollarIcon className="w-16 h-16 mb-2 opacity-50" /><p>Sem dados mensais disponíveis.</p></div>)}</div>
             </div>
        </div>
    );
  }

  // REEMBOLSO FORM
  return (
    <div className="space-y-6">
        <div className="bg-white dark:bg-gray-800 p-4 sm:p-8 rounded-xl shadow-lg animate-fade-in print:shadow-none print:p-0">
            <div className="flex justify-between items-center mb-6 print:hidden">
                <div className="flex items-center gap-2">{reportToEdit && (<div className={`px-3 py-1 rounded-full text-xs font-semibold ${reportToEdit.status === 'Pago' ? 'bg-green-100 text-green-800' : reportToEdit.status === 'Transferido' ? 'bg-yellow-100 text-yellow-800' : 'bg-gray-200 text-gray-800'}`}>Status: {reportToEdit.status}</div>)}{isReadOnly && <span className="text-xs text-red-500 font-medium ml-2">(Somente Leitura)</span>}</div>
                <div className="flex gap-3">{!isReadOnly ? (<><button onClick={() => handleSaveReportAction('Rascunho')} className="flex items-center gap-2 px-4 py-2 bg-gray-600 text-white rounded-md hover:bg-gray-700 transition-colors shadow-sm"><SaveIcon className="w-5 h-5" /> Salvar Rascunho</button><button onClick={() => handleSaveReportAction('Transferido')} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors shadow-sm"><CheckCircleIcon className="w-5 h-5" /> Salvar e Transferir</button></>) : (<div className="text-sm text-gray-500 italic mr-2 flex items-center">Este relatório já foi finalizado.</div>)}<button onClick={handlePrint} className="flex items-center gap-2 px-4 py-2 bg-gray-800 text-white rounded-md hover:bg-gray-900 transition-colors shadow-sm"><PrinterIcon className="w-5 h-5" /> Imprimir</button></div>
            </div>
            <div className={`border border-gray-300 bg-white text-gray-900 print:border-none shadow-sm ${isReadOnly ? 'opacity-90' : ''}`}>
                <div className="p-6 border-b border-gray-300 bg-gray-50 flex items-center justify-center"><h1 className="text-2xl font-bold text-gray-800 uppercase tracking-wide">Relatório de Reembolso de Despesas</h1></div>
                <div className="p-6 grid grid-cols-12 gap-6 bg-white">
                    <div className="col-span-12 md:col-span-6 space-y-3">
                         <div className="flex items-center"><label className="w-40 font-semibold bg-gray-100 px-3 py-2 border border-gray-300 text-sm text-gray-700">Nome Solicitante</label><input type="text" value={solicitante} onChange={(e) => setSolicitante(e.target.value)} disabled={isReadOnly} className="flex-1 border border-gray-300 border-l-0 px-3 py-2 outline-none focus:bg-gray-50 text-sm transition-colors disabled:bg-gray-50 disabled:text-gray-500" /></div>
                         <div className="flex items-center"><label className="w-40 font-semibold bg-gray-100 px-3 py-2 border border-gray-300 text-sm text-gray-700">Setor</label><input type="text" value={setor} onChange={(e) => setSetor(e.target.value)} disabled={isReadOnly} className="flex-1 border border-gray-300 border-l-0 px-3 py-2 outline-none focus:bg-gray-50 text-sm transition-colors disabled:bg-gray-50 disabled:text-gray-500" /></div>
                         <div className="flex items-center"><label className="w-40 font-semibold bg-gray-100 px-3 py-2 border border-gray-300 text-sm text-gray-700">Período</label><div className="flex-1 border border-gray-300 border-l-0 px-3 py-2 flex items-center gap-2 bg-white"><span className="text-sm text-gray-500 font-medium">De:</span><input type="date" value={periodStart} onChange={(e) => setPeriodStart(e.target.value)} disabled={isReadOnly} className="outline-none text-sm bg-transparent text-gray-700 font-medium disabled:text-gray-500" /><span className="text-gray-300 mx-2">|</span><span className="text-sm text-gray-500 font-medium">Até:</span><input type="date" value={periodEnd} onChange={(e) => setPeriodEnd(e.target.value)} disabled={isReadOnly} className="outline-none text-sm bg-transparent text-gray-700 font-medium disabled:text-gray-500" /></div></div>
                    </div>
                    <div className="col-span-12 md:col-span-6 flex flex-col items-end"><div className="flex items-center"><label className="font-semibold bg-gray-100 px-3 py-2 border border-gray-300 text-sm text-gray-700">Reembolso por Km</label><div className="flex items-center border border-gray-300 border-l-0 px-3 py-2 bg-gray-50 w-32"><span className="text-sm mr-1 text-gray-500">R$</span><input type="number" step="0.01" value={valorPorKm} readOnly className="w-full outline-none text-right font-medium text-sm bg-transparent text-gray-600 cursor-not-allowed" /></div></div></div>
                </div>
                <div className="overflow-x-auto p-6 pt-0">
                    <table className="w-full border-collapse border border-gray-300 text-sm">
                        <thead><tr className="bg-gray-100 text-gray-700 font-bold text-center"><th className="border border-gray-300 p-2 w-28">Data</th><th className="border border-gray-300 p-2">Descrição da Viagem</th><th className="border border-gray-300 p-2 w-32">Origem</th><th className="border border-gray-300 p-2 w-32">Destino</th><th className="border border-gray-300 p-2 w-24">Km Rodado</th><th className="border border-gray-300 p-2 w-28">Reembolso Km</th><th className="border border-gray-300 p-2 w-24">Pedágio</th><th className="border border-gray-300 p-2 w-28">Total Reembolso</th><th className="border border-gray-300 p-1 w-8 print:hidden"></th></tr></thead>
                        <tbody>
                            {items.map((item) => {
                                const reembolsoItem = Math.ceil((item.km * valorPorKm) * 100) / 100;
                                const totalItem = Math.ceil((reembolsoItem + item.toll) * 100) / 100;
                                return (<tr key={item.id} className="text-center group hover:bg-gray-50"><td className="border border-gray-300 p-0"><input type="date" className="w-full h-full p-2 text-center outline-none bg-transparent disabled:text-gray-500" value={item.date} onChange={(e) => handleItemChange(item.id, 'date', e.target.value)} disabled={isReadOnly} /></td><td className="border border-gray-300 p-0"><input type="text" className="w-full h-full p-2 outline-none bg-transparent disabled:text-gray-500" value={item.description} onChange={(e) => handleItemChange(item.id, 'description', e.target.value)} disabled={isReadOnly} /></td><td className="border border-gray-300 p-0"><input type="text" className="w-full h-full p-2 outline-none bg-transparent disabled:text-gray-500" value={item.origin} onChange={(e) => handleItemChange(item.id, 'origin', e.target.value)} disabled={isReadOnly} /></td><td className="border border-gray-300 p-0"><input type="text" className="w-full h-full p-2 outline-none bg-transparent disabled:text-gray-500" value={item.destination} onChange={(e) => handleItemChange(item.id, 'destination', e.target.value)} disabled={isReadOnly} /></td><td className="border border-gray-300 p-0"><input type="number" className="w-full h-full p-2 text-center outline-none bg-transparent disabled:text-gray-500" value={item.km || ''} onChange={(e) => handleItemChange(item.id, 'km', parseFloat(e.target.value) || 0)} disabled={isReadOnly} /></td><td className="border border-gray-300 p-2 bg-gray-50 text-gray-700 font-medium">{formatCurrency(reembolsoItem)}</td><td className="border border-gray-300 p-0"><div className="flex items-center h-full px-1"><span className="text-xs text-gray-400 mr-1">R$</span><input type="number" className="w-full h-full py-2 text-right outline-none bg-transparent disabled:text-gray-500" value={item.toll || ''} onChange={(e) => handleItemChange(item.id, 'toll', parseFloat(e.target.value) || 0)} disabled={isReadOnly} /></div></td><td className="border border-gray-300 p-2 bg-gray-100 font-bold text-gray-900">{formatCurrency(totalItem)}</td><td className="border border-gray-300 p-0 print:hidden">{!isReadOnly && (<button onClick={() => handleRemoveItem(item.id)} className="w-full h-full flex items-center justify-center text-gray-400 hover:text-red-500 hover:bg-red-50 transition-colors" title="Remover linha"><TrashIcon className="w-4 h-4" /></button>)}</td></tr>);
                            })}
                        </tbody>
                        <tfoot><tr className="bg-gray-200 font-bold text-gray-800"><td colSpan={4} className="border border-gray-300 p-2 text-right pr-4 uppercase text-xs tracking-wider">Total Geral</td><td className="border border-gray-300 p-2 text-center">{totals.km}</td><td className="border border-gray-300 p-2 text-center">{formatCurrency(totals.reembolsoKm)}</td><td className="border border-gray-300 p-2 text-center">{formatCurrency(totals.toll)}</td><td className="border border-gray-300 p-2 text-center text-gray-900 bg-gray-300">{formatCurrency(totals.total)}</td><td className="border border-gray-300 p-1 print:hidden"></td></tr></tfoot>
                    </table>
                </div>
            </div>
            {!isReadOnly && (<div className="mt-4 print:hidden"><button onClick={handleAddItem} className="flex items-center gap-2 px-4 py-2 bg-white text-indigo-600 rounded-md border border-indigo-200 hover:bg-indigo-50 hover:border-indigo-300 transition-colors shadow-sm"><PlusIcon className="w-4 h-4" /> Adicionar Linha</button></div>)}
            <div className="mt-8 text-xs text-gray-400 text-center print:block hidden">Relatório gerado pelo sistema Orner em {new Date().toLocaleDateString('pt-BR')}</div>
        </div>
        {isSuccessModalOpen && (<Modal title="Sucesso" onClose={() => setSuccessModalOpen(false)}><div className="text-center space-y-4 py-4"><div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-green-100"><svg className="h-6 w-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg></div><h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white">Ação Realizada</h3><p className="text-sm text-gray-500 dark:text-gray-400">{modalMessage}</p><div className="mt-6"><button type="button" className="inline-flex justify-center w-full rounded-md border border-transparent shadow-sm px-4 py-2 bg-indigo-600 text-base font-medium text-white hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 sm:text-sm" onClick={() => setSuccessModalOpen(false)}>OK</button></div></div></Modal>)}
        {isTransferModalOpen && (<Modal title="Confirmar Transferência" onClose={() => setTransferModalOpen(false)}><div className="space-y-6"><div className="text-center"><div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-yellow-100 mb-4"><span className="text-2xl font-bold text-yellow-600">?</span></div><h3 className="text-lg font-medium text-gray-900 dark:text-white">Deseja Realmente Transferir?</h3><p className="text-sm text-gray-500 dark:text-gray-400 mt-2">Ao transferir, o relatório será finalizado e você <strong>não poderá mais alterá-lo</strong>.</p></div><div className="flex justify-center gap-4"><button onClick={() => setTransferModalOpen(false)} className="px-6 py-2 bg-red-100 text-red-700 rounded-md hover:bg-red-200 font-medium transition-colors w-24">Não</button><button onClick={() => { setTransferModalOpen(false); executeSave('Transferido'); }} className="px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-medium transition-colors w-24">Sim</button></div></div></Modal>)}
    </div>
  );
};

export default RelatoriosPage;

import React, { useState, useEffect, useMemo } from 'react';
import { CubeIcon, ClipboardListIcon, ArrowUpIcon, ArrowDownIcon, TrashIcon, ExclamationTriangleIcon, PhotographIcon, SaveIcon, ShoppingCartIcon, AddIcon, EditIcon, ChevronDownIcon, PrinterIcon, DocumentReportIcon, UploadIcon, EyeIcon, XCircleIcon, CheckCircleIcon } from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import type { StockItem, StockMovement, StockMovementType, EstoquePageProps, PurchaseRequest } from '../types';
import { dataService } from '../services/dataService';

const EstoquePage: React.FC<EstoquePageProps> = ({ view, setCurrentPage }) => {
    const [items, setItems] = useState<StockItem[]>([]);
    const [movements, setMovements] = useState<StockMovement[]>([]);
    const [purchaseRequests, setPurchaseRequests] = useState<PurchaseRequest[]>([]);

    const [dashboardTab, setDashboardTab] = useState<'lista' | 'movimentacoes'>('lista');
    const [expandedItemId, setExpandedItemId] = useState<string | null>(null);

    const [isMoveModalOpen, setMoveModalOpen] = useState(false);
    const [isRequestModalOpen, setRequestModalOpen] = useState(false);
    const [isEditModalOpen, setEditModalOpen] = useState(false);
    const [editingItem, setEditingItem] = useState<StockItem | null>(null);
    const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);
    const [itemToDeleteId, setItemToDeleteId] = useState<string | null>(null);
    const [previewFile, setPreviewFile] = useState<string | null>(null);

    const [newItem, setNewItem] = useState<Partial<StockItem>>({ name: '', quantity: 0, minQuantity: 5, unit: 'un', description: '', image: '', averagePrice: 0 });

    const [newMovement, setNewMovement] = useState<Partial<StockMovement> & { unitPrice?: number }>({ 
        itemId: '', type: 'entrada', quantity: 1, date: new Date().toISOString().split('T')[0], observation: '', unitPrice: 0, invoiceNumber: '', invoiceSeries: '', invoiceKey: '', invoiceFile: '', invoiceFileName: '', supplier: '', totalValue: 0
    });

    const [newRequest, setNewRequest] = useState<Partial<PurchaseRequest>>({ 
        itemId: '', quantity: 1, priority: 'Média', reason: 'Reposição Estoque', requester: 'Admin', date: new Date().toISOString().split('T')[0]
    });

    useEffect(() => {
        const loadData = async () => {
            const loadedItems = await dataService.getAll<StockItem>('stock_items', 'stock_items');
            setItems(loadedItems);

            const loadedMovements = await dataService.getAll<StockMovement>('stock_movements', 'stock_movements');
            setMovements(loadedMovements);

            const loadedRequests = await dataService.getAll<PurchaseRequest>('purchase_requests', 'purchase_requests');
            setPurchaseRequests(loadedRequests);
        };
        loadData();
    }, []);

    const metrics = useMemo(() => {
        const totalItems = items.length;
        const lowStockItems = items.filter(i => i.quantity <= i.minQuantity).length;
        const totalStockValue = items.reduce((acc, i) => acc + (i.quantity * (i.averagePrice || 0)), 0);
        return { totalItems, lowStockItems, totalStockValue };
    }, [items]);

    const formatCurrency = (val: number) => {
        if (isNaN(val)) return 'R$ 0,00';
        return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(val);
    };

    const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => { setNewItem(prev => ({ ...prev, image: reader.result as string })); };
            reader.readAsDataURL(file);
        }
    };

    const handleEditImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onloadend = () => { setEditingItem(prev => prev ? ({ ...prev, image: reader.result as string }) : null); };
            reader.readAsDataURL(file);
        }
    };

    const handleInvoiceFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            if (file.size > 1024 * 1024) { alert("O arquivo selecionado é muito grande. O limite é 1MB."); e.target.value = ''; return; }
            const fileName = file.name;
            const reader = new FileReader();
            reader.onloadend = () => { setNewMovement(prev => ({ ...prev, invoiceFile: reader.result as string, invoiceFileName: fileName })); };
            reader.readAsDataURL(file);
        }
    };

    const handleRemoveInvoiceFile = (e: React.MouseEvent) => { e.preventDefault(); e.stopPropagation(); setNewMovement(prev => ({ ...prev, invoiceFile: '', invoiceFileName: '' })); };

    const handleSaveItem = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newItem.name) return;

        const item: StockItem = {
            id: Date.now().toString(),
            name: newItem.name || '',
            quantity: Number(newItem.quantity) || 0,
            minQuantity: Number(newItem.minQuantity) || 0,
            unit: newItem.unit || 'un',
            description: newItem.description,
            image: newItem.image,
            averagePrice: Number(newItem.averagePrice) || 0
        };

        await dataService.save('stock_items', 'stock_items', item);
        setItems(prev => [...prev, item]);
        setNewItem({ name: '', quantity: 0, minQuantity: 5, unit: 'un', description: '', image: '', averagePrice: 0 });
        alert("Produto cadastrado com sucesso!");
        setCurrentPage('ESTOQUE_VISAO_GERAL');
    };

    const handleOpenEdit = (item: StockItem) => { setEditingItem({...item}); setEditModalOpen(true); };

    const handleUpdateItem = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!editingItem) return;
        await dataService.save('stock_items', 'stock_items', editingItem);
        setItems(prev => prev.map(i => i.id === editingItem.id ? editingItem : i));
        setEditModalOpen(false);
        setEditingItem(null);
    };

    const handleDeleteItem = (id: string) => { setItemToDeleteId(id); setDeleteModalOpen(true); };

    const confirmDeleteItem = async () => {
        if (itemToDeleteId) {
            await dataService.delete('stock_items', 'stock_items', itemToDeleteId);
            setItems(prev => prev.filter(i => i.id !== itemToDeleteId));
            setDeleteModalOpen(false);
            setItemToDeleteId(null);
        }
    }

    const handleOpenMoveModal = (type: StockMovementType) => {
        setNewMovement({ itemId: '', type: type, quantity: 1, date: new Date().toISOString().split('T')[0], observation: '', unitPrice: 0, invoiceNumber: '', invoiceSeries: '', invoiceKey: '', invoiceFile: '', invoiceFileName: '', supplier: '', totalValue: 0 });
        setMoveModalOpen(true);
    };

    const handleEntryValuesChange = (field: 'quantity' | 'totalValue', value: number) => {
        if (field === 'quantity') {
            const newQty = value;
            const currentTotal = Number(newMovement.totalValue) || 0;
            const newUnitPrice = newQty > 0 ? currentTotal / newQty : 0;
            setNewMovement(prev => ({ ...prev, quantity: newQty, unitPrice: Number(newUnitPrice.toFixed(4)) }));
        } else if (field === 'totalValue') {
            const newTotal = value;
            const currentQty = Number(newMovement.quantity) || 1;
            const newUnitPrice = currentQty > 0 ? newTotal / currentQty : 0;
            setNewMovement(prev => ({ ...prev, totalValue: newTotal, unitPrice: Number(newUnitPrice.toFixed(4)) }));
        }
    };

    const handleSaveMovement = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newMovement.itemId || !newMovement.quantity || !newMovement.type) { alert("Preencha todos os campos obrigatórios."); return; }
        const qty = Number(newMovement.quantity);
        const item = items.find(i => i.id === newMovement.itemId);
        if (!item) return;
        if (newMovement.type === 'saida' && item.quantity < qty) { alert("Estoque insuficiente para realizar esta saída."); return; }

        const movement: StockMovement = {
            id: Date.now().toString(),
            itemId: newMovement.itemId,
            type: newMovement.type as StockMovementType,
            quantity: qty,
            date: newMovement.date || new Date().toISOString().split('T')[0],
            observation: newMovement.observation,
            unitPrice: newMovement.type === 'entrada' ? Number(newMovement.unitPrice) : undefined,
            invoiceNumber: newMovement.invoiceNumber,
            invoiceSeries: newMovement.invoiceSeries,
            invoiceKey: newMovement.invoiceKey,
            invoiceFile: newMovement.invoiceFile,
            invoiceFileName: newMovement.invoiceFileName,
            supplier: newMovement.supplier,
            totalValue: newMovement.type === 'entrada' ? Number(newMovement.totalValue) : undefined
        };

        // Update Item Stock and Average Price Logic
        let updatedItem = { ...item };
        let newQuantity = item.quantity;
        let newAveragePrice = item.averagePrice || 0;

        if (movement.type === 'entrada') {
            const oldTotalValue = item.quantity * (item.averagePrice || 0);
            const entryValue = movement.totalValue || (qty * (Number(movement.unitPrice) || 0));
            newQuantity = item.quantity + qty;
            if (newQuantity > 0) newAveragePrice = (oldTotalValue + entryValue) / newQuantity;
        } else {
            newQuantity = item.quantity - qty;
        }
        updatedItem.quantity = newQuantity;
        updatedItem.averagePrice = newAveragePrice;

        // Persist both movement and updated item
        await dataService.save('stock_items', 'stock_items', updatedItem);
        await dataService.save('stock_movements', 'stock_movements', movement);

        setItems(prev => prev.map(i => i.id === updatedItem.id ? updatedItem : i));
        setMovements(prev => [movement, ...prev]);
        setMoveModalOpen(false);
    };

    const handleSaveRequest = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!newRequest.itemId || !newRequest.quantity) { alert("Preencha o item e a quantidade."); return; }
        const item = items.find(i => i.id === newRequest.itemId);
        if(!item) return;

        const request: PurchaseRequest = {
            id: Date.now().toString(),
            itemId: item.id,
            itemName: item.name,
            quantity: Number(newRequest.quantity),
            unit: item.unit,
            requester: newRequest.requester || 'Admin',
            date: newRequest.date || new Date().toISOString().split('T')[0],
            priority: newRequest.priority as any || 'Média',
            reason: newRequest.reason || 'Reposição Estoque',
            status: 'Pendente',
            observation: newRequest.observation
        };

        await dataService.save('purchase_requests', 'purchase_requests', request);
        setPurchaseRequests(prev => [request, ...prev]);
        setRequestModalOpen(false);
        setNewRequest({ itemId: '', quantity: 1, priority: 'Média', reason: 'Reposição Estoque', requester: 'Admin', date: new Date().toISOString().split('T')[0] });
    };

    const handleUpdateRequestStatus = async (id: string, newStatus: PurchaseRequest['status']) => {
        const request = purchaseRequests.find(r => r.id === id);
        if (request) {
            const updatedRequest = { ...request, status: newStatus };
            await dataService.save('purchase_requests', 'purchase_requests', updatedRequest);
            setPurchaseRequests(prev => prev.map(r => r.id === id ? updatedRequest : r));
        }
    }

    const getItemName = (id: string) => items.find(i => i.id === id)?.name || 'Item desconhecido';
    const toggleRow = (id: string) => { setExpandedItemId(prev => prev === id ? null : id); }
    const handlePrint = () => { window.print(); };

    // ... handleExportExcel logic omitted for brevity, keeping existing functionality

    if (view === 'cadastro') {
        return (
            <div className="p-8 max-w-4xl mx-auto bg-white dark:bg-gray-800 rounded-xl shadow-lg">
                <div className="mb-6 border-b border-gray-200 dark:border-gray-700 pb-4"><h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-2"><CubeIcon className="w-8 h-8 text-indigo-600" /> Cadastro de Novo Material</h2><p className="text-gray-500 dark:text-gray-400 mt-1">Preencha os dados abaixo para registrar um novo item no controle de estoque.</p></div>
                <form onSubmit={handleSaveItem} className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    <div className="col-span-1 flex flex-col items-center"><label className="cursor-pointer group relative w-full aspect-square max-w-[250px] rounded-xl bg-gray-50 dark:bg-gray-700 flex flex-col items-center justify-center overflow-hidden border-2 border-dashed border-gray-300 dark:border-gray-600 hover:border-indigo-500 hover:bg-indigo-50 dark:hover:bg-gray-600 transition-all">{newItem.image ? (<img src={newItem.image} alt="Preview" className="w-full h-full object-cover" />) : (<div className="text-center text-gray-400 group-hover:text-indigo-500 p-4"><PhotographIcon className="w-12 h-12 mx-auto mb-2" /><span className="text-sm font-medium">Adicionar Foto do Produto</span><p className="text-xs mt-1 text-gray-400">Clique para selecionar</p></div>)}<input type="file" accept="image/*" onChange={handleImageChange} className="hidden" /></label>{newItem.image && (<button type="button" onClick={() => setNewItem(prev => ({...prev, image: ''}))} className="mt-2 text-sm text-red-500 hover:text-red-700">Remover foto</button>)}</div>
                    <div className="col-span-1 md:col-span-2 space-y-5">
                        <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Nome do Item *</label><input required type="text" value={newItem.name} onChange={e => setNewItem({...newItem, name: e.target.value})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2.5 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm" placeholder="Ex: Painel Solar 550W" /></div>
                        <div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Qtd. Inicial</label><input type="number" min="0" value={newItem.quantity} onChange={e => setNewItem({...newItem, quantity: Number(e.target.value)})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2.5 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm" /></div><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Valor Unitário Inicial (R$)</label><input type="number" min="0" step="0.01" value={newItem.averagePrice} onChange={e => setNewItem({...newItem, averagePrice: Number(e.target.value)})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2.5 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm" /></div></div>
                        <div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Unidade de Medida</label><select value={newItem.unit} onChange={e => setNewItem({...newItem, unit: e.target.value})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2.5 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm"><option value="un">Unidade (un)</option><option value="kg">Quilo (kg)</option><option value="m">Metro (m)</option><option value="cx">Caixa (cx)</option><option value="pares">Pares</option><option value="lt">Litros (lt)</option><option value="pc">Peça (pc)</option></select></div><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Estoque Mínimo (Alerta)</label><div className="relative"><input type="number" min="0" value={newItem.minQuantity} onChange={e => setNewItem({...newItem, minQuantity: Number(e.target.value)})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2.5 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm" /><div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none"><span className="text-gray-500 text-xs">unidades</span></div></div></div></div>
                        <div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Descrição / Detalhes</label><textarea rows={3} value={newItem.description} onChange={e => setNewItem({...newItem, description: e.target.value})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2.5 focus:ring-indigo-500 focus:border-indigo-500 shadow-sm" placeholder="Marca, Modelo, Cor, Especificações técnicas..." /></div>
                        <div className="flex justify-end pt-4 gap-3"><button type="button" onClick={() => setCurrentPage('ESTOQUE_VISAO_GERAL')} className="px-5 py-2.5 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300 rounded-lg hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors font-medium">Cancelar</button><button type="submit" className="px-5 py-2.5 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-medium flex items-center gap-2"><SaveIcon className="w-5 h-5" /> Salvar Produto</button></div>
                    </div>
                </form>
            </div>
        );
    }

    if (view === 'compras') {
        return (
            <div className="space-y-6">
                <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg"><div><h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3"><ShoppingCartIcon className="w-8 h-8 text-indigo-600" /> Solicitações de Compra</h2><p className="text-gray-500 dark:text-gray-400 mt-1">Acompanhe e registre necessidades de reposição de material.</p></div><button onClick={() => setRequestModalOpen(true)} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors shadow-sm"><AddIcon className="w-5 h-5" /> Nova Solicitação</button></div>
                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden"><div className="overflow-x-auto"><table className="min-w-full text-left text-sm"><thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider"><tr><th className="px-6 py-3">Data</th><th className="px-6 py-3">Item</th><th className="px-6 py-3">Qtd</th><th className="px-6 py-3">Motivo</th><th className="px-6 py-3">Solicitante</th><th className="px-6 py-3">Prioridade</th><th className="px-6 py-3">Status</th><th className="px-6 py-3 text-center">Ações</th></tr></thead><tbody className="divide-y divide-gray-200 dark:divide-gray-700">{purchaseRequests.map(req => (<tr key={req.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"><td className="px-6 py-4 text-gray-500 dark:text-gray-400">{new Date(req.date).toLocaleDateString('pt-BR', { timeZone: 'UTC' })}</td><td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{req.itemName}</td><td className="px-6 py-4 font-bold">{req.quantity} <span className="font-normal text-xs text-gray-500">{req.unit}</span></td><td className="px-6 py-4 text-gray-600 dark:text-gray-300 text-xs">{req.reason || '-'}</td><td className="px-6 py-4 text-gray-500 dark:text-gray-400">{req.requester}</td><td className="px-6 py-4"><span className={`px-2 py-1 text-xs font-semibold rounded ${req.priority === 'Alta' ? 'bg-red-100 text-red-800' : req.priority === 'Média' ? 'bg-yellow-100 text-yellow-800' : 'bg-blue-100 text-blue-800'}`}>{req.priority}</span></td><td className="px-6 py-4"><span className={`px-2 py-1 text-xs font-semibold rounded-full ${req.status === 'Pendente' ? 'bg-gray-200 text-gray-800' : req.status === 'Aprovado' ? 'bg-blue-200 text-blue-800' : req.status === 'Comprado' ? 'bg-green-200 text-green-800' : 'bg-red-200 text-red-800'}`}>{req.status}</span></td><td className="px-6 py-4 text-center space-x-2">{req.status === 'Pendente' && (<><button onClick={() => handleUpdateRequestStatus(req.id, 'Aprovado')} className="text-xs bg-blue-50 text-blue-600 px-2 py-1 rounded hover:bg-blue-100">Aprovar</button><button onClick={() => handleUpdateRequestStatus(req.id, 'Cancelado')} className="text-xs bg-red-50 text-red-600 px-2 py-1 rounded hover:bg-red-100">Recusar</button></>)}{req.status === 'Aprovado' && (<button onClick={() => handleUpdateRequestStatus(req.id, 'Comprado')} className="text-xs bg-green-50 text-green-600 px-2 py-1 rounded hover:bg-green-100">Marcar Comprado</button>)}</td></tr>))}{purchaseRequests.length === 0 && <tr><td colSpan={8} className="px-6 py-12 text-center text-gray-500">Nenhuma solicitação de compra.</td></tr>}</tbody></table></div></div>
                {isRequestModalOpen && (<Modal title="Nova Solicitação de Compra" onClose={() => setRequestModalOpen(false)}><form onSubmit={handleSaveRequest} className="space-y-4"><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Item Necessário</label><select required value={newRequest.itemId} onChange={e => setNewRequest({...newRequest, itemId: e.target.value})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500"><option value="">Selecione o item...</option>{items.map(i => (<option key={i.id} value={i.id}>{i.name}</option>))}</select></div><div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Quantidade</label><input type="number" min="1" required value={newRequest.quantity} onChange={e => setNewRequest({...newRequest, quantity: Number(e.target.value)})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500" /></div><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Prioridade</label><select value={newRequest.priority} onChange={e => setNewRequest({...newRequest, priority: e.target.value as any})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500"><option value="Baixa">Baixa</option><option value="Média">Média</option><option value="Alta">Alta</option></select></div></div><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Motivo</label><select value={newRequest.reason} onChange={e => setNewRequest({...newRequest, reason: e.target.value})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500"><option value="Reposição Estoque">Reposição Estoque</option><option value="Material Obra">Material Obra</option></select></div><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Observação</label><textarea rows={2} value={newRequest.observation || ''} onChange={e => setNewRequest({...newRequest, observation: e.target.value})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500" placeholder="Detalhes adicionais..."></textarea></div><div className="flex justify-end pt-4 gap-2"><button type="button" onClick={() => setRequestModalOpen(false)} className="px-4 py-2 bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 dark:hover:bg-gray-500 transition-colors">Cancelar</button><button type="submit" className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors">Solicitar</button></div></form></Modal>)}
            </div>
        );
    }

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center print:hidden"><h1 className="text-xl font-bold text-gray-800 dark:text-white hidden print:block">Relatório de Estoque</h1><div className="flex gap-2 w-full justify-end"><button onClick={handlePrint} className="flex items-center gap-2 px-4 py-2 bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200 rounded-md hover:bg-gray-200 dark:hover:bg-gray-600 transition-colors shadow-sm" title="Imprimir Relatório"><PrinterIcon className="w-5 h-5" /><span className="hidden sm:inline">Imprimir</span></button></div></div>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-6 print:hidden"><DashboardCard title="Total de Itens Cadastrados" value={metrics.totalItems.toString()} icon={CubeIcon} color="bg-blue-500" /><DashboardCard title="Itens com Estoque Baixo" value={metrics.lowStockItems.toString()} icon={ExclamationTriangleIcon} color={metrics.lowStockItems > 0 ? "bg-red-500" : "bg-green-500"} /><DashboardCard title="Valor Total em Estoque" value={formatCurrency(metrics.totalStockValue)} icon={ClipboardListIcon} color="bg-indigo-500" /></div>
            <div className="flex flex-col sm:flex-row justify-between items-center gap-4 print:hidden"><div className="bg-white dark:bg-gray-800 p-1.5 rounded-lg shadow-sm flex flex-wrap gap-2"><button onClick={() => setDashboardTab('lista')} className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${dashboardTab === 'lista' ? 'bg-indigo-600 text-white shadow' : 'text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'}`}>Lista de Produtos</button><button onClick={() => setDashboardTab('movimentacoes')} className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${dashboardTab === 'movimentacoes' ? 'bg-indigo-600 text-white shadow' : 'text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'}`}>Histórico de Movimentações</button></div><div className="flex gap-2"><button onClick={() => handleOpenMoveModal('entrada')} className="flex items-center gap-2 px-4 py-2 bg-green-50 text-green-700 border border-green-200 rounded-md hover:bg-green-100 transition-colors shadow-sm font-medium"><ArrowUpIcon className="w-4 h-4" /> Registrar Entrada</button><button onClick={() => handleOpenMoveModal('saida')} className="flex items-center gap-2 px-4 py-2 bg-red-50 text-red-700 border border-red-200 rounded-md hover:bg-red-100 transition-colors shadow-sm font-medium"><ArrowDownIcon className="w-4 h-4" /> Registrar Saída</button></div></div>
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden min-h-[400px] print:shadow-none print:border print:border-gray-300 print:min-h-0">
                {dashboardTab === 'lista' && (
                    <div className="overflow-x-auto print:overflow-visible">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider print:bg-gray-100 print:text-black"><tr><th className="px-2 py-3 w-8 print:hidden"></th><th className="px-6 py-3">Foto</th><th className="px-6 py-3">Item</th><th className="px-6 py-3">Descrição</th><th className="px-6 py-3 text-right">Qtd. Mínima</th><th className="px-6 py-3 text-right">Quantidade</th><th className="px-6 py-3 text-right">Valor Médio</th><th className="px-6 py-3 text-center">Status</th><th className="px-6 py-3 text-center print:hidden">Ações</th></tr></thead>
                            <tbody className="divide-y divide-gray-200 dark:divide-gray-700 print:divide-gray-300">
                                {items.map(item => {
                                    const hasReservation = (item.reservedQuantity || 0) > 0;
                                    const futureBalance = item.quantity - (item.reservedQuantity || 0);
                                    return (
                                        <React.Fragment key={item.id}>
                                            <tr className={`transition-colors ${hasReservation ? 'bg-yellow-100 font-bold text-gray-900 print:bg-transparent' : 'hover:bg-gray-50 dark:hover:bg-gray-700/50 text-gray-900 dark:text-white'}`}><td className="px-2 py-4 text-center print:hidden">{hasReservation && (<button onClick={() => toggleRow(item.id)} className="text-indigo-600 hover:bg-indigo-200 rounded-full p-1 transition-colors" title="Ver Reservas"><ChevronDownIcon className={`w-5 h-5 transition-transform ${expandedItemId === item.id ? 'rotate-180' : ''}`} /></button>)}</td><td className="px-6 py-4">{item.image ? (<img src={item.image} alt={item.name} className="w-12 h-12 rounded object-cover shadow-sm border border-gray-200 dark:border-gray-600 print:w-8 print:h-8" />) : (<div className="w-12 h-12 rounded bg-gray-100 dark:bg-gray-700 flex items-center justify-center text-gray-400 border border-gray-200 dark:border-gray-600 print:w-8 print:h-8"><PhotographIcon className="w-6 h-6 print:w-4 print:h-4" /></div>)}</td><td className="px-6 py-4 font-medium">{item.name}</td><td className={`px-6 py-4 ${!hasReservation ? 'text-gray-500 dark:text-gray-400' : ''} max-w-xs truncate`} title={item.description}>{item.description || '-'}</td><td className="px-6 py-4 text-right">{item.minQuantity} {item.unit}</td><td className="px-6 py-4 text-right"><div className="flex flex-col items-end"><span className={`text-lg ${hasReservation ? 'font-bold' : ''}`}>Real: {item.quantity} <span className={`text-sm font-normal ${!hasReservation ? 'text-gray-500 dark:text-gray-300' : ''}`}>{item.unit}</span></span>{hasReservation && (<div className="flex items-center gap-1 mt-1 text-xs text-red-600 font-bold print:text-black"><span>Futuro: {futureBalance}</span></div>)}</div></td><td className="px-6 py-4 text-right">{item.averagePrice ? formatCurrency(item.averagePrice) : '-'}</td><td className="px-6 py-4 text-center">{item.quantity <= item.minQuantity ? (<span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300 print:border print:border-black print:text-black print:bg-transparent">Baixo Estoque</span>) : (<span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300 print:border print:border-black print:text-black print:bg-transparent">Normal</span>)}</td><td className="px-6 py-4 text-center space-x-2 print:hidden"><button onClick={() => handleOpenEdit(item)} className="text-gray-500 hover:text-indigo-600 dark:text-gray-400 dark:hover:text-indigo-400 transition-colors p-1" title="Editar Item"><EditIcon className="w-5 h-5" /></button><button onClick={() => handleDeleteItem(item.id)} className="text-gray-500 hover:text-red-600 dark:text-gray-400 dark:hover:text-red-400 transition-colors p-1" title="Excluir Item"><TrashIcon className="w-5 h-5" /></button></td></tr>
                                            {hasReservation && expandedItemId === item.id && (<tr className="bg-yellow-50 dark:bg-yellow-900/5 animate-fade-in print:bg-transparent"><td colSpan={9} className="px-6 py-3 border-t border-yellow-200 dark:border-yellow-900/50 print:border-gray-200"><div className="flex flex-col gap-2 pl-14"><p className="text-xs font-bold text-gray-600 uppercase tracking-wide">Comprometido em Obras (Reservas)</p><div className="space-y-1">{item.reservations && item.reservations.length > 0 ? (item.reservations.map((res, idx) => (<div key={idx} className="flex justify-between items-center text-sm bg-white dark:bg-gray-800 p-2 rounded shadow-sm max-w-md border border-gray-200 dark:border-gray-600 print:shadow-none print:border-0"><span className="font-medium text-gray-800 dark:text-gray-200">{res.sourceName}</span><span className="text-gray-500 text-xs">{new Date(res.date).toLocaleDateString('pt-BR')}</span><span className="font-bold text-red-600 dark:text-red-400">-{res.quantity} {item.unit}</span></div>))) : (<span className="text-sm italic text-gray-500">Sem detalhes disponíveis.</span>)}</div></div></td></tr>)}
                                        </React.Fragment>
                                    );
                                })}
                                {items.length === 0 && <tr><td colSpan={9} className="px-6 py-12 text-center text-gray-500"><p className="mb-2">Nenhum item cadastrado no estoque.</p><button onClick={() => setCurrentPage('ESTOQUE_NOVO_PRODUTO')} className="text-indigo-600 hover:underline">Cadastrar o primeiro item</button></td></tr>}
                            </tbody>
                        </table>
                    </div>
                )}
                {dashboardTab === 'movimentacoes' && (
                    <div className="overflow-x-auto print:overflow-visible">
                        <table className="min-w-full text-left text-sm">
                            <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider print:bg-gray-100 print:text-black"><tr><th className="px-6 py-3">Data</th><th className="px-6 py-3">Tipo</th><th className="px-6 py-3">Item</th><th className="px-6 py-3 text-right">Quantidade</th><th className="px-6 py-3 text-right">Valor Unit.</th><th className="px-6 py-3">Observação</th><th className="px-6 py-3 text-center">Anexo</th></tr></thead>
                            <tbody className="divide-y divide-gray-200 dark:divide-gray-700 print:divide-gray-300">
                                {movements.map(mov => (
                                    <tr key={mov.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors"><td className="px-6 py-4 text-gray-500 dark:text-gray-400">{new Date(mov.date).toLocaleDateString('pt-BR', { timeZone: 'UTC' })}</td><td className="px-6 py-4"><span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${mov.type === 'entrada' ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300' : 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300'} print:border print:border-black print:text-black print:bg-transparent`}>{mov.type.toUpperCase()}</span></td><td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{getItemName(mov.itemId)}</td><td className="px-6 py-4 text-right font-bold">{mov.quantity}</td><td className="px-6 py-4 text-right">{mov.type === 'entrada' && mov.unitPrice ? formatCurrency(mov.unitPrice) : '-'}</td><td className="px-6 py-4 text-gray-500 dark:text-gray-400">{mov.invoiceNumber && <span className="block text-xs font-bold text-gray-600 dark:text-gray-300">NF: {mov.invoiceNumber}</span>}{mov.observation || '-'}</td><td className="px-6 py-4 text-center">{mov.invoiceFile && (<button onClick={() => setPreviewFile(mov.invoiceFile!)} className="text-indigo-600 hover:text-indigo-800 p-1" title={mov.invoiceFileName ? mov.invoiceFileName : "Ver Anexo da NF"}><DocumentReportIcon className="w-5 h-5" /></button>)}</td></tr>
                                ))}
                                {movements.length === 0 && <tr><td colSpan={7} className="px-6 py-12 text-center text-gray-500">Nenhuma movimentação registrada.</td></tr>}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>
            {isEditModalOpen && editingItem && (<Modal title="Editar Produto" onClose={() => setEditModalOpen(false)}><form onSubmit={handleUpdateItem} className="space-y-4"><div className="flex flex-col items-center mb-4"><label className="cursor-pointer group relative w-32 h-32 rounded-xl bg-gray-50 dark:bg-gray-700 flex flex-col items-center justify-center overflow-hidden border-2 border-dashed border-gray-300 dark:border-gray-600 hover:border-indigo-500 hover:bg-indigo-50 dark:hover:bg-gray-600 transition-all">{editingItem.image ? (<img src={editingItem.image} alt="Preview" className="w-full h-full object-cover" />) : (<div className="text-center text-gray-400 group-hover:text-indigo-500 p-2"><PhotographIcon className="w-8 h-8 mx-auto mb-1" /><span className="text-[10px] font-medium">Foto</span></div>)}<input type="file" accept="image/*" onChange={handleEditImageChange} className="hidden" /></label>{editingItem.image ? (<button type="button" onClick={() => setEditingItem(prev => prev ? ({...prev, image: ''}) : null)} className="mt-1 text-xs text-red-500 hover:text-red-700">Remover</button>) : (<span className="text-xs text-gray-400 mt-1">Clique para adicionar imagem</span>)}</div><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Nome do Item</label><input type="text" required value={editingItem.name} onChange={e => setEditingItem({...editingItem, name: e.target.value})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500" /></div><div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Estoque Mínimo</label><input type="number" min="0" value={editingItem.minQuantity} onChange={e => setEditingItem({...editingItem, minQuantity: Number(e.target.value)})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500" /></div><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Unidade</label><select value={editingItem.unit} onChange={e => setEditingItem({...editingItem, unit: e.target.value})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500"><option value="un">Unidade (un)</option><option value="kg">Quilo (kg)</option><option value="m">Metro (m)</option><option value="cx">Caixa (cx)</option><option value="pares">Pares</option><option value="lt">Litros (lt)</option><option value="pc">Peça (pc)</option></select></div></div><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Descrição</label><textarea rows={2} value={editingItem.description || ''} onChange={e => setEditingItem({...editingItem, description: e.target.value})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500" /></div><div className="flex justify-end pt-4 gap-2"><button type="button" onClick={() => setEditModalOpen(false)} className="px-4 py-2 bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 dark:hover:bg-gray-500 transition-colors">Cancelar</button><button type="submit" className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors">Salvar Alterações</button></div></form></Modal>)}
            {isMoveModalOpen && (<Modal title={newMovement.type === 'entrada' ? 'Registrar Entrada de Material' : 'Registrar Saída de Material'} onClose={() => setMoveModalOpen(false)} maxWidth="max-w-xl"><form onSubmit={handleSaveMovement} className="space-y-5">{newMovement.type === 'entrada' && (<div className="bg-green-50 dark:bg-green-900/10 p-4 rounded-lg border border-green-200 dark:border-green-800 space-y-4"><h4 className="text-sm font-bold text-green-800 dark:text-green-300 uppercase tracking-wide border-b border-green-200 dark:border-green-800 pb-2 mb-2">Dados da Nota Fiscal</h4><div className="grid grid-cols-3 gap-3"><div className="col-span-1"><label className="block text-xs font-medium text-green-800 dark:text-green-300 mb-1">Número</label><input type="text" value={newMovement.invoiceNumber || ''} onChange={e => setNewMovement({...newMovement, invoiceNumber: e.target.value})} className="w-full rounded-md border-green-300 dark:border-green-700 bg-white dark:bg-gray-700 p-2 focus:ring-green-500 focus:border-green-500 text-sm" placeholder="12345" /></div><div className="col-span-1"><label className="block text-xs font-medium text-green-800 dark:text-green-300 mb-1">Série</label><input type="text" value={newMovement.invoiceSeries || ''} onChange={e => setNewMovement({...newMovement, invoiceSeries: e.target.value})} className="w-full rounded-md border-green-300 dark:border-green-700 bg-white dark:bg-gray-700 p-2 focus:ring-green-500 focus:border-green-500 text-sm" placeholder="001" /></div><div className="col-span-1"><label className="block text-xs font-medium text-green-800 dark:text-green-300 mb-1">Fornecedor</label><input type="text" value={newMovement.supplier || ''} onChange={e => setNewMovement({...newMovement, supplier: e.target.value})} className="w-full rounded-md border-green-300 dark:border-green-700 bg-white dark:bg-gray-700 p-2 focus:ring-green-500 focus:border-green-500 text-sm" placeholder="Nome Fornecedor" /></div></div><div><label className="block text-xs font-medium text-green-800 dark:text-green-300 mb-1">Chave de Acesso (44 dígitos)</label><input type="text" value={newMovement.invoiceKey || ''} onChange={e => setNewMovement({...newMovement, invoiceKey: e.target.value})} className="w-full rounded-md border-green-300 dark:border-green-700 bg-white dark:bg-gray-700 p-2 focus:ring-green-500 focus:border-green-500 text-xs font-mono" placeholder="0000 0000 0000 0000 0000 0000 0000 0000 0000 0000 0000" maxLength={44} /></div><div><label className="block text-xs font-medium text-green-800 dark:text-green-300 mb-1">Anexar NF (PDF ou Imagem)</label><label className={`flex items-center gap-2 cursor-pointer w-full p-2 border border-dashed ${newMovement.invoiceFile ? 'border-indigo-400 bg-indigo-50 dark:bg-indigo-900/20' : 'border-green-400 bg-white dark:bg-gray-700'} rounded-md hover:bg-opacity-80 transition-colors relative group`}>{newMovement.invoiceFile ? (<><CheckCircleIcon className="w-4 h-4 text-indigo-600" /><span className="text-xs text-indigo-700 dark:text-indigo-300 font-medium truncate flex-1" title={newMovement.invoiceFileName}>{newMovement.invoiceFileName || 'Arquivo Anexado com Sucesso'}</span><button type="button" onClick={handleRemoveInvoiceFile} className="p-1 bg-white rounded-full text-red-500 hover:text-red-700 shadow-sm z-10" title="Remover anexo"><XCircleIcon className="w-4 h-4" /></button></>) : (<><UploadIcon className="w-4 h-4 text-green-600" /><span className="text-xs text-gray-500 dark:text-gray-300">Clique para selecionar arquivo (Máx 1MB)</span></>)}<input type="file" accept="image/*,application/pdf" className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" onChange={handleInvoiceFileChange} onClick={(e) => (e.target as any).value = null} /></label></div></div>)}<div className="space-y-4"><h4 className={`text-sm font-bold uppercase tracking-wide border-b pb-2 mb-2 ${newMovement.type === 'entrada' ? 'text-gray-700 dark:text-gray-300 border-gray-200' : 'text-red-700 dark:text-red-300 border-red-200'}`}>Dados do Lançamento</h4><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Item do Estoque</label><select required value={newMovement.itemId} onChange={e => setNewMovement({...newMovement, itemId: e.target.value})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm"><option value="">Selecione o item...</option>{items.map(i => (<option key={i.id} value={i.id}>{i.name} (Atual: {i.quantity} {i.unit})</option>))}</select></div><div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Data</label><input type="date" required value={newMovement.date} onChange={e => setNewMovement({...newMovement, date: e.target.value})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm" /></div><div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Quantidade (Compra)</label><input type="number" min="1" required value={newMovement.quantity} onChange={e => handleEntryValuesChange('quantity', Number(e.target.value))} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm font-bold" /></div></div>{newMovement.type === 'entrada' && (<div className="grid grid-cols-2 gap-4 bg-gray-50 dark:bg-gray-700/30 p-3 rounded-md"><div><label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">Valor Total Nota/Item (R$)</label><input type="number" min="0" step="0.01" value={newMovement.totalValue} onChange={e => handleEntryValuesChange('totalValue', Number(e.target.value))} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm" placeholder="0.00" /></div><div><label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Custo Unitário (Calc)</label><div className="relative"><span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 font-bold text-xs">R$</span><input type="number" value={newMovement.unitPrice} readOnly className="w-full pl-8 rounded-md border-gray-200 dark:border-gray-700 bg-gray-100 dark:bg-gray-800 p-2 text-sm text-gray-600 dark:text-gray-300 cursor-not-allowed font-medium" /></div></div></div>)}<div><label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Observação / Motivo</label><input type="text" value={newMovement.observation} onChange={e => setNewMovement({...newMovement, observation: e.target.value})} className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 focus:ring-indigo-500 focus:border-indigo-500 text-sm" placeholder={newMovement.type === 'entrada' ? "Ex: Compra de lote mensal" : "Ex: Uso na Obra X"} /></div></div><div className="flex justify-end pt-2 gap-2 border-t border-gray-100 dark:border-gray-700"><button type="button" onClick={() => setMoveModalOpen(false)} className="px-4 py-2 bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 dark:hover:bg-gray-500 transition-colors text-sm font-medium">Cancelar</button><button type="submit" className={`px-6 py-2 text-white rounded-md transition-colors text-sm font-medium shadow-sm flex items-center gap-2 ${newMovement.type === 'entrada' ? 'bg-green-600 hover:bg-green-700' : 'bg-red-600 hover:bg-red-700'}`}>{newMovement.type === 'entrada' ? <ArrowUpIcon className="w-4 h-4"/> : <ArrowDownIcon className="w-4 h-4"/>} Confirmar {newMovement.type === 'entrada' ? 'Entrada' : 'Saída'}</button></div></form></Modal>)}
            {previewFile && (<div className="fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-90 p-4" onClick={() => setPreviewFile(null)}><div className="relative max-w-4xl w-full h-[90vh] bg-white rounded-lg overflow-hidden flex flex-col" onClick={(e) => e.stopPropagation()}><div className="flex justify-between items-center p-3 border-b border-gray-200 bg-gray-50"><h3 className="font-bold text-gray-700">Visualizar Nota Fiscal</h3><button onClick={() => setPreviewFile(null)} className="text-gray-500 hover:text-red-500 font-bold px-2">X</button></div><div className="flex-1 bg-gray-100 flex items-center justify-center overflow-auto p-4">{previewFile.startsWith('data:image') ? (<img src={previewFile} alt="Nota Fiscal" className="max-w-full max-h-full object-contain shadow-lg" />) : (<iframe src={previewFile} className="w-full h-full border-none shadow-lg" title="Documento PDF"></iframe>)}</div></div></div>)}
            {isDeleteModalOpen && (<Modal title="Confirmar Exclusão" onClose={() => setDeleteModalOpen(false)}><div className="space-y-4"><div className="p-4 bg-red-50 dark:bg-red-900/20 text-red-700 dark:text-red-300 rounded-md flex items-start gap-3"><ExclamationTriangleIcon className="w-6 h-6 flex-shrink-0" /><div><p className="font-medium">Atenção!</p><p className="text-sm mt-1">Tem certeza que deseja excluir este item? Esta ação removerá o item do estoque permanentemente e não poderá ser desfeita.</p></div></div><div className="flex justify-end gap-2 pt-2"><button onClick={() => setDeleteModalOpen(false)} className="px-4 py-2 bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 dark:hover:bg-gray-500 transition-colors">Cancelar</button><button onClick={confirmDeleteItem} className="px-4 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 transition-colors">Confirmar Exclusão</button></div></div></Modal>)}
        </div>
    );
};

export default EstoquePage;

import React, { useMemo, useState, useEffect } from 'react';
import { ChartPieIcon, TableIcon, DollarIcon, TrendUpIcon, PrinterIcon, CalendarIcon, FilterIcon, TrashIcon, UsersIcon } from '../assets/icons';
import DashboardCard from '../components/DashboardCard';
import type { SalesSummaryItem } from '../types';
import { dataService } from '../services/dataService';

const formatCurrency = (value: number) => {
    if (isNaN(value)) return 'R$ 0,00';
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(value);
};

const formatPercent = (value: number) => {
    if (isNaN(value)) return '0,00%';
    return `${value.toFixed(2).replace('.', ',')}%`;
};

const ResumoVendasPage: React.FC = () => {

    const [salesData, setSalesData] = useState<SalesSummaryItem[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Estados para o filtro de data
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    useEffect(() => {
        const loadData = async () => {
            setIsLoading(true);
            const data = await dataService.getAll<SalesSummaryItem>('sales_summary', 'sales_summary');
            setSalesData(data);
            setIsLoading(false);
        };
        loadData();

        // Inicializar com o mês atual por padrão
        const date = new Date();
        const firstDay = new Date(date.getFullYear(), date.getMonth(), 1);
        const lastDay = new Date(date.getFullYear(), date.getMonth() + 1, 0);

        const formatDate = (d: Date) => {
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, '0');
            const day = String(d.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`;
        };

        setStartDate(formatDate(firstDay));
        setEndDate(formatDate(lastDay));
    }, []);

    const handleUpdateValue = async (id: number, field: 'invoicedTax' | 'bankFees', value: string) => {
        const numValue = parseFloat(value);
        // Permite valor vazio durante a digitação, trata como 0 se NaN no cálculo
        const safeValue = isNaN(numValue) ? 0 : numValue;

        // Optimistic UI Update
        const updatedData = salesData.map(item => {
            if (item.id === id) {
                const newItem = { ...item, [field]: safeValue };

                // Recalcular Custo Total
                const totalCost = 
                    (newItem.systemCost || 0) +
                    (newItem.homologation || 0) +
                    (newItem.materialCost || 0) +
                    (newItem.installation || 0) +
                    (newItem.technicalVisit || 0) +
                    (newItem.travelCost || 0) +
                    (newItem.localAdjustment || 0) +
                    (newItem.invoicedTax || 0) +
                    (newItem.commission || 0) +
                    (newItem.bankFees || 0);

                const netProfit = (newItem.closedValue || 0) - totalCost;
                const finalMargin = newItem.closedValue > 0 ? (netProfit / newItem.closedValue) * 100 : 0;

                return { ...newItem, totalCost, netProfit, finalMargin };
            }
            return item;
        });

        setSalesData(updatedData);

        // Save to DB
        const itemToSave = updatedData.find(i => i.id === id);
        if (itemToSave) {
            await dataService.save('sales_summary', 'sales_summary', itemToSave);
        }
    };

    // Filtrar dados com base nas datas
    const filteredSalesData = useMemo(() => {
        return salesData.filter(item => {
            if (startDate && item.date < startDate) return false;
            if (endDate && item.date > endDate) return false;
            return true;
        });
    }, [salesData, startDate, endDate]);

    // Calcular totais dinamicamente (Baseado nos dados FILTRADOS)
    const totals = useMemo(() => {
        return filteredSalesData.reduce((acc, item) => {
            return {
                closedValue: acc.closedValue + item.closedValue,
                systemCost: acc.systemCost + item.systemCost,
                homologation: acc.homologation + item.homologation,
                materialCost: acc.materialCost + item.materialCost,
                installation: acc.installation + item.installation,
                technicalVisit: acc.technicalVisit + (item.technicalVisit || 0),
                travelCost: acc.travelCost + (item.travelCost || 0),
                localAdjustment: acc.localAdjustment + (item.localAdjustment || 0),
                invoicedTax: acc.invoicedTax + item.invoicedTax,
                commission: acc.commission + item.commission,
                bankFees: acc.bankFees + item.bankFees,
                totalCost: acc.totalCost + item.totalCost,
                netProfit: acc.netProfit + item.netProfit,
            };
        }, {
            closedValue: 0, systemCost: 0, homologation: 0, materialCost: 0, installation: 0,
            technicalVisit: 0, travelCost: 0, localAdjustment: 0,
            invoicedTax: 0, commission: 0, bankFees: 0, totalCost: 0, netProfit: 0
        });
    }, [filteredSalesData]);

    const totalValorMO = totals.closedValue - totals.systemCost;
    const avgMargin = totals.closedValue > 0 ? (totals.netProfit / totals.closedValue) * 100 : 0;
    const avgServiceMargin = totalValorMO > 0 ? (totals.netProfit / totalValorMO) * 100 : 0;

    const handlePrint = () => {
        window.print();
    };

    const handleClearFilters = () => {
        setStartDate('');
        setEndDate('');
    };

    if (isLoading) {
        return <div className="flex justify-center p-10"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600"></div></div>;
    }

    return (
        <div className="space-y-6">

            {/* Filtros de Data */}
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4 bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 print:hidden">
                <div className="flex items-center gap-3 w-full sm:w-auto">
                    <div className="p-2 bg-indigo-50 dark:bg-indigo-900/30 rounded-lg text-indigo-600 dark:text-indigo-400">
                        <FilterIcon className="w-5 h-5" />
                    </div>
                    <span className="font-semibold text-gray-700 dark:text-gray-200">Período de Vendas</span>
                </div>

                <div className="flex flex-col sm:flex-row items-center gap-3 w-full sm:w-auto">
                    <div className="flex items-center gap-2 bg-gray-50 dark:bg-gray-700/30 p-1.5 rounded-lg border border-gray-200 dark:border-gray-600 w-full sm:w-auto">
                        <div className="pl-2 text-gray-500">
                            <CalendarIcon className="w-5 h-5" />
                        </div>
                        <input
                            type="date"
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 focus:ring-0 p-1 cursor-pointer w-full sm:w-auto"
                        />
                        <span className="text-gray-400">-</span>
                        <input
                            type="date"
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 focus:ring-0 p-1 cursor-pointer w-full sm:w-auto"
                        />
                    </div>

                    {(startDate || endDate) && (
                        <button
                            onClick={handleClearFilters}
                            className="px-3 py-2 text-sm text-gray-500 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-md transition-colors flex items-center gap-1 whitespace-nowrap"
                        >
                            <TrashIcon className="w-4 h-4" />
                            Limpar
                        </button>
                    )}
                </div>
            </div>

            {/* KPI Cards (Atualizados pelo filtro) */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-6 print:hidden">
                <DashboardCard 
                    title="Total Venda Cons. Final" 
                    value={formatCurrency(totals.closedValue)} 
                    icon={DollarIcon} 
                    color="bg-blue-600" 
                />
                <DashboardCard 
                    title="Total Mão de Obra" 
                    value={formatCurrency(totalValorMO)} 
                    icon={UsersIcon} 
                    color="bg-purple-600" 
                />
                <DashboardCard 
                    title="Lucro Líquido (Período)" 
                    value={formatCurrency(totals.netProfit)} 
                    icon={TrendUpIcon} 
                    color="bg-green-600" 
                />
                <DashboardCard 
                    title="Margem Média Venda" 
                    value={formatPercent(avgMargin)} 
                    icon={ChartPieIcon} 
                    color="bg-indigo-600" 
                />
                <DashboardCard 
                    title="Margem Média Serviço" 
                    value={formatPercent(avgServiceMargin)} 
                    icon={ChartPieIcon} 
                    color="bg-orange-600" 
                />
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border border-gray-100 dark:border-gray-700">
                <div className="p-6 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-700/30">
                    <div>
                        <h2 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                            <TableIcon className="w-6 h-6 text-indigo-600" />
                            Relatório Detalhado de Vendas
                        </h2>
                        <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                            {filteredSalesData.length} registro(s) encontrado(s)
                            {startDate && endDate ? ` entre ${new Date(startDate).toLocaleDateString('pt-BR', {timeZone: 'UTC'})} e ${new Date(endDate).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}` : ''}.
                        </p>
                    </div>
                    <button
                        onClick={handlePrint}
                        className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-600 border border-gray-300 dark:border-gray-500 rounded-md hover:bg-gray-50 dark:hover:bg-gray-500 text-gray-700 dark:text-gray-200 transition-colors shadow-sm print:hidden"
                    >
                        <PrinterIcon className="w-5 h-5" />
                        Imprimir
                    </button>
                </div>

                <div className="overflow-x-auto">
                    <table className="min-w-full text-xs text-left">
                        <thead className="bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-bold uppercase tracking-wider">
                            <tr>
                                <th className="px-4 py-3 sticky left-0 bg-gray-100 dark:bg-gray-700 z-10 border-b border-r border-gray-200 dark:border-gray-600">Cliente</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 whitespace-nowrap">Data</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right bg-blue-50 dark:bg-blue-900/10">Valor Fechado</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Custo Sistema</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Homolog.</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Materiais</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Instalação</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Visita</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Viagem</th>
