import React, { useState, useEffect } from 'react';
import { AddIcon, EditIcon, TrashIcon, UsersIcon, LockClosedIcon, SaveIcon, PhotographIcon } from '../assets/icons';
import type { User, UserProfile, UsuariosPageProps } from '../types';
import { MOCK_USERS, MOCK_PROFILES, MENU_ITEMS } from '../constants';
import Modal from '../components/Modal';
import { dataService } from '../services/dataService';

const UsuariosPage: React.FC<UsuariosPageProps> = ({ view, setCurrentPage }) => {
    // States
    const [users, setUsers] = useState<User[]>([]);
    const [profiles, setProfiles] = useState<UserProfile[]>([]);

    // UI States
    const [isUserModalOpen, setUserModalOpen] = useState(false);
    const [isProfileFormOpen, setProfileFormOpen] = useState(false);

    // Editing States
    const [userToEdit, setUserToEdit] = useState<User | null>(null);
    const [profileToEdit, setProfileToEdit] = useState<UserProfile | null>(null);

    // Form Data States
    const [userData, setUserData] = useState<Partial<User>>({ name: '', email: '', profileId: '', active: true, avatar: '' });
    const [profileData, setProfileData] = useState<Partial<UserProfile>>({ name: '', permissions: [] });

    // Load Data
    useEffect(() => {
        const loadData = async () => {
            // Load Users
            const loadedUsers = await dataService.getAll<User>('system_users', 'system_users');
            setUsers(loadedUsers.length > 0 ? loadedUsers : MOCK_USERS);

            // Load Profiles
            const loadedProfiles = await dataService.getAll<UserProfile>('system_profiles', 'system_profiles');
            setProfiles(loadedProfiles.length > 0 ? loadedProfiles : MOCK_PROFILES);
        };
        loadData();
    }, []);

    // Helper: Resize and Convert Image to Base64
    const resizeImage = (file: File, maxWidth: number = 300, maxHeight: number = 300): Promise<string> => {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.readAsDataURL(file);
            reader.onload = (event) => {
                const img = new Image();
                img.src = event.target?.result as string;
                img.onload = () => {
                    const canvas = document.createElement('canvas');
                    let width = img.width;
                    let height = img.height;

                    if (width > height) {
                        if (width > maxWidth) {
                            height *= maxWidth / width;
                            width = maxWidth;
                        }
                    } else {
                        if (height > maxHeight) {
                            width *= maxHeight / height;
                            height = maxHeight;
                        }
                    }

                    canvas.width = width;
                    canvas.height = height;
                    const ctx = canvas.getContext('2d');
                    if (ctx) {
                        ctx.drawImage(img, 0, 0, width, height);
                        // Compress to JPEG 70% quality to save space
                        resolve(canvas.toDataURL('image/jpeg', 0.7));
                    } else {
                        reject(new Error("Canvas context is null"));
                    }
                };
                img.onerror = (error) => reject(error);
            };
            reader.onerror = (error) => reject(error);
        });
    };

    // --- LOGIC: GESTÃO (USERS) ---

    const handleOpenUserModal = (user?: User) => {
        if (user) {
            setUserToEdit(user);
            setUserData({ ...user });
        } else {
            setUserToEdit(null);
            setUserData({ name: '', email: '', profileId: '', active: true, avatar: '' });
        }
        setUserModalOpen(true);
    };

    const handleUserImageChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            try {
                // Resize image to max 300x300 to ensure it fits in Database JSONB
                const base64 = await resizeImage(file, 300, 300);
                setUserData(prev => ({ ...prev, avatar: base64 }));
            } catch (error) {
                console.error("Error converting file to base64", error);
                alert("Erro ao processar a imagem. Tente uma imagem diferente.");
            }
        }
    };

    const handleSaveUser = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!userData.name || !userData.email || !userData.profileId) {
            alert('Preencha os campos obrigatórios.');
            return;
        }

        const newUser: User = {
            id: userToEdit ? userToEdit.id : Date.now().toString(),
            name: userData.name!,
            email: userData.email!,
            profileId: userData.profileId!,
            active: userData.active ?? true,
            avatar: userData.avatar || `https://ui-avatars.com/api/?name=${encodeURIComponent(userData.name!)}&background=random`
        };

        await dataService.save('system_users', 'system_users', newUser);
        setUsers(prev => userToEdit ? prev.map(u => u.id === newUser.id ? newUser : u) : [...prev, newUser]);
        setUserModalOpen(false);
    };

    const handleDeleteUser = async (id: string) => {
        if (window.confirm('Tem certeza que deseja excluir este usuário?')) {
            await dataService.delete('system_users', 'system_users', id);
            setUsers(prev => prev.filter(u => u.id !== id));
        }
    };

    const getProfileName = (id: string) => {
        return profiles.find(p => p.id === id)?.name || 'Perfil Desconhecido';
    };

    // --- LOGIC: PERFIL (ROLES) ---

    const handleOpenProfileForm = (profile?: UserProfile) => {
        if (profile) {
            setProfileToEdit(profile);
            setProfileData({ ...profile });
        } else {
            setProfileToEdit(null);
            setProfileData({ name: '', permissions: [] });
        }
        setProfileFormOpen(true);
    };

    const handleSaveProfile = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!profileData.name) {
            alert('Nome do Perfil é obrigatório.');
            return;
        }

        const newProfile: UserProfile = {
            id: profileToEdit ? profileToEdit.id : Date.now().toString(),
            name: profileData.name!,
            permissions: profileData.permissions || []
        };

        await dataService.save('system_profiles', 'system_profiles', newProfile);
        setProfiles(prev => profileToEdit ? prev.map(p => p.id === newProfile.id ? newProfile : p) : [...prev, newProfile]);
        setProfileFormOpen(false);
    };

    const handleDeleteProfile = async (id: string) => {
        // Check if used by any user
        if (users.some(u => u.profileId === id)) {
            alert('Não é possível excluir este perfil pois existem usuários vinculados a ele.');
            return;
        }
        if (window.confirm('Tem certeza que deseja excluir este perfil?')) {
            await dataService.delete('system_profiles', 'system_profiles', id);
            setProfiles(prev => prev.filter(p => p.id !== id));
        }
    };

    const togglePermission = (permissionId: string) => {
        const currentPermissions = profileData.permissions || [];
        if (currentPermissions.includes(permissionId)) {
            setProfileData(prev => ({
                ...prev,
                permissions: currentPermissions.filter(p => p !== permissionId)
            }));
        } else {
            setProfileData(prev => ({
                ...prev,
                permissions: [...currentPermissions, permissionId]
            }));
        }
    };

    // --- VIEW RENDERERS ---

    if (view === 'gestao') {
        return (
            <div className="space-y-6">
                <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                    <div>
                        <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                            <UsersIcon className="w-8 h-8 text-indigo-600" />
                            Gestão de Usuários
                        </h2>
                        <p className="text-gray-500 dark:text-gray-400 mt-1">
                            Cadastre usuários e vincule-os a um perfil de acesso existente.
                        </p>
                    </div>
                    <button
                        onClick={() => handleOpenUserModal()}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors shadow-sm"
                    >
                        <AddIcon className="w-5 h-5" />
                        Novo Usuário
                    </button>
                </div>

                <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden">
                    <table className="min-w-full text-left text-sm">
                        <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider">
                            <tr>
                                <th className="px-6 py-3">Usuário</th>
                                <th className="px-6 py-3">Email</th>
                                <th className="px-6 py-3">Perfil de Acesso</th>
                                <th className="px-6 py-3">Status</th>
                                <th className="px-6 py-3 text-center">Ações</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                            {users.map(user => (
                                <tr key={user.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                    <td className="px-6 py-4 flex items-center gap-3">
                                        <img src={user.avatar} alt={user.name} className="w-10 h-10 rounded-full object-cover bg-gray-100" />
                                        <span className="font-semibold text-gray-900 dark:text-white">{user.name}</span>
                                    </td>
                                    <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{user.email}</td>
                                    <td className="px-6 py-4">
                                        <span className="px-2 py-1 bg-indigo-100 text-indigo-800 dark:bg-indigo-900/30 dark:text-indigo-200 rounded text-xs font-semibold">
                                            {getProfileName(user.profileId)}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4">
                                        <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                                            user.active 
                                            ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300' 
                                            : 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300'
                                        }`}>
                                            {user.active ? 'Ativo' : 'Inativo'}
                                        </span>
                                    </td>
                                    <td className="px-6 py-4 text-center space-x-2">
                                        <button onClick={() => handleOpenUserModal(user)} className="p-2 text-gray-500 hover:text-indigo-600 transition-colors">
                                            <EditIcon className="w-5 h-5" />
                                        </button>
                                        <button onClick={() => handleDeleteUser(user.id)} className="p-2 text-gray-500 hover:text-red-600 transition-colors">
                                            <TrashIcon className="w-5 h-5" />
                                        </button>
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>

                {isUserModalOpen && (
                    <Modal title={userToEdit ? 'Editar Usuário' : 'Novo Usuário'} onClose={() => setUserModalOpen(false)}>
                        <form onSubmit={handleSaveUser} className="space-y-4">
                            <div className="flex justify-center mb-6">
                                <div className="relative">
                                    <label className="cursor-pointer group relative w-24 h-24 rounded-full bg-gray-100 dark:bg-gray-700 flex items-center justify-center overflow-hidden border-2 border-dashed border-gray-300 dark:border-gray-600 hover:border-indigo-500 transition-colors">
                                        {userData.avatar ? (
                                            <img src={userData.avatar} alt="Avatar" className="w-full h-full object-cover" />
                                        ) : (
                                            <div className="text-center text-gray-400 group-hover:text-indigo-500">
                                                <PhotographIcon className="w-8 h-8 mx-auto mb-1" />
                                                <span className="text-[10px] font-medium">Foto</span>
                                            </div>
                                        )}
                                        <input type="file" accept="image/*" onChange={handleUserImageChange} className="hidden" />
                                    </label>
                                    {userData.avatar && (
                                        <button
                                            type="button"
                                            onClick={() => setUserData({ ...userData, avatar: '' })}
                                            className="absolute bottom-0 right-0 bg-red-500 text-white p-1 rounded-full hover:bg-red-600 shadow-sm"
                                            title="Remover foto"
                                        >
                                            <TrashIcon className="w-3 h-3" />
                                        </button>
                                    )}
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Nome Completo</label>
                                <input type="text" required value={userData.name} onChange={e => setUserData({...userData, name: e.target.value})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Email</label>
                                <input type="email" required value={userData.email} onChange={e => setUserData({...userData, email: e.target.value})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2" />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Perfil de Acesso</label>
                                <select required value={userData.profileId} onChange={e => setUserData({...userData, profileId: e.target.value})} className="mt-1 block w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2">
                                    <option value="">Selecione um perfil...</option>
                                    {profiles.map(p => (
                                        <option key={p.id} value={p.id}>{p.name}</option>
                                    ))}
                                </select>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-gray-700 dark:text-gray-300">Status</label>
                                <div className="mt-2 flex gap-4">
                                    <label className="inline-flex items-center">
                                        <input type="radio" className="text-indigo-600" checked={userData.active} onChange={() => setUserData({...userData, active: true})} />
                                        <span className="ml-2 text-gray-700 dark:text-gray-300">Ativo</span>
                                    </label>
                                    <label className="inline-flex items-center">
                                        <input type="radio" className="text-red-600" checked={!userData.active} onChange={() => setUserData({...userData, active: false})} />
                                        <span className="ml-2 text-gray-700 dark:text-gray-300">Inativo</span>
                                    </label>
                                </div>
                            </div>
                            <div className="flex justify-end pt-4 gap-2">
                                <button type="button" onClick={() => setUserModalOpen(false)} className="px-4 py-2 bg-gray-200 dark:bg-gray-700 rounded text-gray-800 dark:text-white">Cancelar</button>
                                <button type="submit" className="px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700">Salvar</button>
                            </div>
                        </form>
                    </Modal>
                )}
            </div>
        );
    }

    if (view === 'perfil') {
        if (isProfileFormOpen) {
            // VIEW: FORMULÁRIO DE PERFIL
            return (
                <div className="max-w-4xl mx-auto space-y-6">
                    <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg border-l-4 border-indigo-600">
                        <div>
                            <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                                <LockClosedIcon className="w-8 h-8 text-indigo-600" />
                                {profileToEdit ? `Editando Perfil: ${profileToEdit.name}` : 'Criar Novo Perfil'}
