                    className="absolute -top-10 right-0 text-white hover:text-gray-300 focus:outline-none"
                >
                    <XCircleIcon className="w-8 h-8" />
                </button>
                <img src={imageSrc} alt="Preview" className="max-w-full max-h-[90vh] object-contain rounded-md" />
            </div>
        </div>
    );
};

