// Resumo de Vendas
export interface SalesSummaryItem {
    id: number;
    orcamentoId?: number; // Vínculo com o orçamento original
    clientName: string;
    date: string;
    closedValue: number;
    systemCost: number;
    homologation: number;
    materialCost: number;
    installation: number;
    technicalVisit?: number; // Custo de Visita Técnica
    travelCost: number;
    localAdjustment: number;
    invoicedTax: number;
    commission: number;
    bankFees: number;
    totalCost: number;
    netProfit: number;
    finalMargin: number; // Percentual 0-100
}

import React, { useMemo, useState, useEffect } from 'react';
import { ChartPieIcon, TableIcon, DollarIcon, TrendUpIcon, PrinterIcon, CalendarIcon, FilterIcon, TrashIcon, UsersIcon } from '../assets/icons';
import DashboardCard from '../components/DashboardCard';
import type { SalesSummaryItem } from '../types';
import { dataService } from '../services/dataService';

const formatCurrency = (value: number) => {
    if (isNaN(value)) return 'R$ 0,00';
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(value);
};

const formatPercent = (value: number) => {
    if (isNaN(value)) return '0,00%';
    return `${value.toFixed(2).replace('.', ',')}%`;
};

const ResumoVendasPage: React.FC = () => {

    const [salesData, setSalesData] = useState<SalesSummaryItem[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Estados para o filtro de data
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    useEffect(() => {
        const loadData = async () => {
            setIsLoading(true);
            const data = await dataService.getAll<SalesSummaryItem>('sales_summary', 'sales_summary');
            setSalesData(data);
            setIsLoading(false);
        };
        loadData();

        // Inicializar com o mês atual por padrão
        const date = new Date();
        const firstDay = new Date(date.getFullYear(), date.getMonth(), 1);
        const lastDay = new Date(date.getFullYear(), date.getMonth() + 1, 0);

        const formatDate = (d: Date) => {
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, '0');
            const day = String(d.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`;
        };

        setStartDate(formatDate(firstDay));
        setEndDate(formatDate(lastDay));
    }, []);

    const handleUpdateValue = async (id: number, field: 'invoicedTax' | 'bankFees', value: string) => {
        const numValue = parseFloat(value);
        // Permite valor vazio durante a digitação, trata como 0 se NaN no cálculo
        const safeValue = isNaN(numValue) ? 0 : numValue;

        // Optimistic UI Update
        const updatedData = salesData.map(item => {
            if (item.id === id) {
                const newItem = { ...item, [field]: safeValue };

                // Recalcular Custo Total
                const totalCost = 
                    (newItem.systemCost || 0) +
                    (newItem.homologation || 0) +
                    (newItem.materialCost || 0) +
                    (newItem.installation || 0) +
                    (newItem.technicalVisit || 0) +
                    (newItem.travelCost || 0) +
                    (newItem.localAdjustment || 0) +
                    (newItem.invoicedTax || 0) +
                    (newItem.commission || 0) +
                    (newItem.bankFees || 0);

                const netProfit = (newItem.closedValue || 0) - totalCost;
                const finalMargin = newItem.closedValue > 0 ? (netProfit / newItem.closedValue) * 100 : 0;

                return { ...newItem, totalCost, netProfit, finalMargin };
            }
            return item;
        });

        setSalesData(updatedData);

        // Save to DB
        const itemToSave = updatedData.find(i => i.id === id);
        if (itemToSave) {
            await dataService.save('sales_summary', 'sales_summary', itemToSave);
        }
    };

    // Filtrar dados com base nas datas
    const filteredSalesData = useMemo(() => {
        return salesData.filter(item => {
            if (startDate && item.date < startDate) return false;
            if (endDate && item.date > endDate) return false;
            return true;
        });
    }, [salesData, startDate, endDate]);

    // Calcular totais dinamicamente (Baseado nos dados FILTRADOS)
    const totals = useMemo(() => {
        return filteredSalesData.reduce((acc, item) => {
            return {
                closedValue: acc.closedValue + item.closedValue,
                systemCost: acc.systemCost + item.systemCost,
                homologation: acc.homologation + item.homologation,
                materialCost: acc.materialCost + item.materialCost,
                installation: acc.installation + item.installation,
                technicalVisit: acc.technicalVisit + (item.technicalVisit || 0),
                travelCost: acc.travelCost + (item.travelCost || 0),
                localAdjustment: acc.localAdjustment + (item.localAdjustment || 0),
                invoicedTax: acc.invoicedTax + item.invoicedTax,
                commission: acc.commission + item.commission,
                bankFees: acc.bankFees + item.bankFees,
                totalCost: acc.totalCost + item.totalCost,
                netProfit: acc.netProfit + item.netProfit,
            };
        }, {
            closedValue: 0, systemCost: 0, homologation: 0, materialCost: 0, installation: 0,
            technicalVisit: 0, travelCost: 0, localAdjustment: 0,
            invoicedTax: 0, commission: 0, bankFees: 0, totalCost: 0, netProfit: 0
        });
    }, [filteredSalesData]);

    const totalValorMO = totals.closedValue - totals.systemCost;
    const avgMargin = totals.closedValue > 0 ? (totals.netProfit / totals.closedValue) * 100 : 0;
    const avgServiceMargin = totalValorMO > 0 ? (totals.netProfit / totalValorMO) * 100 : 0;

    const handlePrint = () => {
        window.print();
    };

    const handleClearFilters = () => {
        setStartDate('');
        setEndDate('');
    };

    if (isLoading) {
        return <div className="flex justify-center p-10"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600"></div></div>;
    }

    return (
        <div className="space-y-6">

            {/* Filtros de Data */}
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4 bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 print:hidden">
                <div className="flex items-center gap-3 w-full sm:w-auto">
                    <div className="p-2 bg-indigo-50 dark:bg-indigo-900/30 rounded-lg text-indigo-600 dark:text-indigo-400">
                        <FilterIcon className="w-5 h-5" />
                    </div>
                    <span className="font-semibold text-gray-700 dark:text-gray-200">Período de Vendas</span>
                </div>

                <div className="flex flex-col sm:flex-row items-center gap-3 w-full sm:w-auto">
                    <div className="flex items-center gap-2 bg-gray-50 dark:bg-gray-700/30 p-1.5 rounded-lg border border-gray-200 dark:border-gray-600 w-full sm:w-auto">
                        <div className="pl-2 text-gray-500">
                            <CalendarIcon className="w-5 h-5" />
                        </div>
                        <input
                            type="date"
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 focus:ring-0 p-1 cursor-pointer w-full sm:w-auto"
                        />
                        <span className="text-gray-400">-</span>
                        <input
                            type="date"
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 focus:ring-0 p-1 cursor-pointer w-full sm:w-auto"
                        />
                    </div>

                    {(startDate || endDate) && (
                        <button
                            onClick={handleClearFilters}
                            className="px-3 py-2 text-sm text-gray-500 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 rounded-md transition-colors flex items-center gap-1 whitespace-nowrap"
                        >
                            <TrashIcon className="w-4 h-4" />
                            Limpar
                        </button>
                    )}
                </div>
            </div>

            {/* KPI Cards (Atualizados pelo filtro) */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-6 print:hidden">
                <DashboardCard 
                    title="Total Venda Cons. Final" 
                    value={formatCurrency(totals.closedValue)} 
                    icon={DollarIcon} 
                    color="bg-blue-600" 
                />
                <DashboardCard 
                    title="Total Mão de Obra" 
                    value={formatCurrency(totalValorMO)} 
                    icon={UsersIcon} 
                    color="bg-purple-600" 
                />
                <DashboardCard 
                    title="Lucro Líquido (Período)" 
                    value={formatCurrency(totals.netProfit)} 
                    icon={TrendUpIcon} 
                    color="bg-green-600" 
                />
                <DashboardCard 
                    title="Margem Média Venda" 
                    value={formatPercent(avgMargin)} 
                    icon={ChartPieIcon} 
                    color="bg-indigo-600" 
                />
                <DashboardCard 
                    title="Margem Média Serviço" 
                    value={formatPercent(avgServiceMargin)} 
                    icon={ChartPieIcon} 
                    color="bg-orange-600" 
                />
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden border border-gray-100 dark:border-gray-700">
                <div className="p-6 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center bg-gray-50 dark:bg-gray-700/30">
                    <div>
                        <h2 className="text-xl font-bold text-gray-900 dark:text-white flex items-center gap-2">
                            <TableIcon className="w-6 h-6 text-indigo-600" />
                            Relatório Detalhado de Vendas
                        </h2>
                        <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
                            {filteredSalesData.length} registro(s) encontrado(s)
                            {startDate && endDate ? ` entre ${new Date(startDate).toLocaleDateString('pt-BR', {timeZone: 'UTC'})} e ${new Date(endDate).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}` : ''}.
                        </p>
                    </div>
                    <button
                        onClick={handlePrint}
                        className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-gray-600 border border-gray-300 dark:border-gray-500 rounded-md hover:bg-gray-50 dark:hover:bg-gray-500 text-gray-700 dark:text-gray-200 transition-colors shadow-sm print:hidden"
                    >
                        <PrinterIcon className="w-5 h-5" />
                        Imprimir
                    </button>
                </div>

                <div className="overflow-x-auto">
                    <table className="min-w-full text-xs text-left">
                        <thead className="bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-200 font-bold uppercase tracking-wider">
                            <tr>
                                <th className="px-4 py-3 sticky left-0 bg-gray-100 dark:bg-gray-700 z-10 border-b border-r border-gray-200 dark:border-gray-600">Cliente</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 whitespace-nowrap">Data</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right bg-blue-50 dark:bg-blue-900/10">Valor Fechado</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Custo Sistema</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Homolog.</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Materiais</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Instalação</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Visita</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Viagem</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Adequação</th>
                                <th className="px-2 py-3 border-b border-gray-200 dark:border-gray-600 text-right w-24">Impostos</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right">Comissão</th>
                                <th className="px-2 py-3 border-b border-gray-200 dark:border-gray-600 text-right w-24">Taxas</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right font-bold text-red-600 dark:text-red-400">Custo Total</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-right font-bold text-green-700 dark:text-green-400 bg-green-50 dark:bg-green-900/20">Lucro Líq.</th>
                                <th className="px-4 py-3 border-b border-gray-200 dark:border-gray-600 text-center font-bold">Margem</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-200 dark:divide-gray-700 bg-white dark:bg-gray-800">
                            {filteredSalesData.length > 0 ? (
                                filteredSalesData.map((item, index) => (
                                    <tr key={item.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                        <td className="px-4 py-2 font-medium text-gray-900 dark:text-white sticky left-0 bg-white dark:bg-gray-800 border-r border-gray-100 dark:border-gray-700">
                                            <div className="flex items-center gap-2">
                                                <span className="text-gray-400 text-[10px] w-4">{index + 1}</span>
                                                {item.clientName}
                                            </div>
                                        </td>
                                        <td className="px-4 py-2 text-gray-500 dark:text-gray-400 whitespace-nowrap">
                                            {new Date(item.date).toLocaleDateString('pt-BR', {timeZone: 'UTC'})}
                                        </td>
                                        <td className="px-4 py-2 text-right font-semibold text-blue-700 dark:text-blue-300 bg-blue-50/50 dark:bg-blue-900/5">
                                            {formatCurrency(item.closedValue)}
                                        </td>
                                        <td className="px-4 py-2 text-right text-gray-600 dark:text-gray-400">{formatCurrency(item.systemCost)}</td>
                                        <td className="px-4 py-2 text-right text-gray-600 dark:text-gray-400">{item.homologation > 0 ? formatCurrency(item.homologation) : '-'}</td>
                                        <td className="px-4 py-2 text-right text-gray-600 dark:text-gray-400">{formatCurrency(item.materialCost)}</td>
                                        <td className="px-4 py-2 text-right text-gray-600 dark:text-gray-400">{formatCurrency(item.installation)}</td>
                                        <td className="px-4 py-2 text-right text-gray-600 dark:text-gray-400">{item.technicalVisit > 0 ? formatCurrency(item.technicalVisit) : '-'}</td>
                                        <td className="px-4 py-2 text-right text-gray-600 dark:text-gray-400">{item.travelCost > 0 ? formatCurrency(item.travelCost) : '-'}</td>
                                        <td className="px-4 py-2 text-right text-gray-600 dark:text-gray-400">{item.localAdjustment > 0 ? formatCurrency(item.localAdjustment) : '-'}</td>

                                        <td className="px-2 py-2 text-right">
                                            <div className="relative">
                                                <span className="absolute left-1 top-1/2 -translate-y-1/2 text-gray-400 text-[10px]">R$</span>
                                                <input 
                                                    type="number" 
                                                    value={item.invoicedTax} 
                                                    onChange={(e) => handleUpdateValue(item.id, 'invoicedTax', e.target.value)}
                                                    className="w-full text-right bg-yellow-50 dark:bg-yellow-900/10 border border-transparent hover:border-gray-300 focus:border-indigo-500 rounded px-1 py-0.5 text-xs text-gray-800 dark:text-gray-200 outline-none transition-colors"
                                                />
                                            </div>
                                        </td>

                                        <td className="px-4 py-2 text-right text-gray-600 dark:text-gray-400">{item.commission > 0 ? formatCurrency(item.commission) : '-'}</td>

                                        <td className="px-2 py-2 text-right">
                                            <div className="relative">
                                                <span className="absolute left-1 top-1/2 -translate-y-1/2 text-gray-400 text-[10px]">R$</span>
                                                <input 
                                                    type="number" 
                                                    value={item.bankFees} 
                                                    onChange={(e) => handleUpdateValue(item.id, 'bankFees', e.target.value)}
                                                    className="w-full text-right bg-yellow-50 dark:bg-yellow-900/10 border border-transparent hover:border-gray-300 focus:border-indigo-500 rounded px-1 py-0.5 text-xs text-gray-800 dark:text-gray-200 outline-none transition-colors"
                                                />
                                            </div>
                                        </td>

                                        <td className="px-4 py-2 text-right font-medium text-red-600 dark:text-red-400 bg-red-50/30 dark:bg-red-900/10">
                                            {formatCurrency(item.totalCost)}
                                        </td>
                                        <td className="px-4 py-2 text-right font-bold text-green-700 dark:text-green-400 bg-green-50/50 dark:bg-green-900/10">
                                            {formatCurrency(item.netProfit)}
