                                <td className="px-4 py-3 text-right">{formatCurrency(totals.invoicedTax)}</td>
                                <td className="px-4 py-3 text-right">{formatCurrency(totals.commission)}</td>
                                <td className="px-4 py-3 text-right">{formatCurrency(totals.bankFees)}</td>
                                <td className="px-4 py-3 text-right text-red-600 dark:text-red-400">{formatCurrency(totals.totalCost)}</td>
                                <td className="px-4 py-3 text-right text-green-700 dark:text-green-400 bg-green-100 dark:bg-green-900/30">{formatCurrency(totals.netProfit)}</td>
                                <td className="px-4 py-3 text-center text-indigo-700 dark:text-indigo-400">{formatPercent(avgMargin)}</td>
                            </tr>
                        </tfoot>
                    </table>
                </div>
            </div>
        </div>
    );
};

