                                            <span className="ml-2 text-sm text-gray-600 dark:text-gray-300 font-medium">Habilitar Acesso</span>
                                        </label>
                                    </div>
                                    {menuItem.children && (
                                        <div className="ml-7 mt-2 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2">
                                            {menuItem.children.map(child => (
                                                <label 
                                                    key={child.id} 
                                                    className={`flex items-center p-2 rounded cursor-pointer transition-colors border ${
                                                        profileData.permissions?.includes(child.id)
                                                        ? 'bg-indigo-50 dark:bg-indigo-900/40 border-indigo-200 dark:border-indigo-800'
                                                        : 'bg-white dark:bg-gray-800 border-gray-200 dark:border-gray-600 hover:bg-gray-100'
                                                    }`}
                                                >
