                                                        type="checkbox" 
                                                        checked={profileData.permissions?.includes(child.id)}
                                                        onChange={() => togglePermission(child.id)}
                                                        className="rounded border-gray-300 text-indigo-600 shadow-sm focus:border-indigo-300 focus:ring focus:ring-indigo-200 focus:ring-opacity-50" 
                                                    />
                                                    <span className={`ml-2 text-sm ${profileData.permissions?.includes(child.id) ? 'text-indigo-900 dark:text-indigo-100 font-medium' : 'text-gray-600 dark:text-gray-400'}`}>
                                                        {child.label}
                                                    </span>
                                                </label>
                                            ))}
                                        </div>
                                    )}
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            );
        }

        // VIEW: LISTA DE PERFIS
        return (
            <div className="space-y-6">
                <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                    <div>
                        <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                            <LockClosedIcon className="w-8 h-8 text-indigo-600" />
                            Perfis de Acesso
                        </h2>
                        <p className="text-gray-500 dark:text-gray-400 mt-1">
                            Crie e edite as regras de acesso (permissões) do sistema.
                        </p>
                    </div>
                    <button
                        onClick={() => handleOpenProfileForm()}
