                                    <EditIcon className="w-4 h-4" />
                                </button>
                                <button onClick={() => handleDeleteProfile(profile.id)} className="p-1.5 text-gray-500 hover:text-red-600 bg-gray-100 dark:bg-gray-700 rounded-md">
                                    <TrashIcon className="w-4 h-4" />
                                </button>
                            </div>

                            <div className="flex items-center gap-3 mb-4">
                                <div className="p-3 bg-indigo-100 dark:bg-indigo-900/30 rounded-full text-indigo-600 dark:text-indigo-400">
                                    <LockClosedIcon className="w-6 h-6" />
                                </div>
                                <h3 className="text-lg font-bold text-gray-900 dark:text-white">{profile.name}</h3>
                            </div>

                            <div className="text-sm text-gray-500 dark:text-gray-400">
                                <p className="mb-2 font-medium">Resumo de Acessos:</p>
                                <div className="flex flex-wrap gap-2">
                                    {MENU_ITEMS.filter(m => profile.permissions.includes(m.id)).slice(0, 4).map(m => (
                                        <span key={m.id} className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded text-xs text-gray-700 dark:text-gray-300">
                                            {m.label}
                                        </span>
                                    ))}
                                    {MENU_ITEMS.filter(m => profile.permissions.includes(m.id)).length > 4 && (
                                        <span className="px-2 py-1 bg-gray-100 dark:bg-gray-700 rounded text-xs text-gray-500">
                                            +{MENU_ITEMS.filter(m => profile.permissions.includes(m.id)).length - 4} mais
                                        </span>
                                    )}
                                    {MENU_ITEMS.filter(m => profile.permissions.includes(m.id)).length === 0 && (
                                        <span className="text-xs italic text-red-400">Sem acessos configurados</span>
                                    )}
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    return null;
};

export default UsuariosPage;

