const CheckListPage: React.FC<CheckListPageProps> = ({ view }) => {
    const isCheckIn = view === 'checkin';
    const isMaintenance = view === 'manutencao';
    const isCheckOut = view === 'checkout';

    let title = 'Check-In de Obra';
    let description = 'Formulário técnico inicial para elaboração de projeto fotovoltaico.';
    if (isCheckOut) {
        title = 'Check-Out de Obra';
        description = 'Formulário Pós-Instalação: Validação de entrega técnica e fotos.';
    } else if (isMaintenance) {
        title = 'Relatório de Manutenção';
        description = 'Registro de visitas técnicas, preventivas ou corretivas.';
    }

    const [entries, setEntries] = useState<ChecklistEntry[]>([]);
    const [searchTerm, setSearchTerm] = useState('');

    useEffect(() => {
        const loadEntries = async () => {
            const data = await dataService.getAll<ChecklistEntry>('checklist_entries', 'checklist_entries');
            setEntries(data);
        };
        loadEntries();
    }, []);

    const filteredEntries = entries.filter(e => {
        const matchesType = e.type === view;
        const matchesSearch = e.project.toLowerCase().includes(searchTerm.toLowerCase());
        return matchesType && matchesSearch;
    });

    const [isModalOpen, setModalOpen] = useState(false);
    const [editingEntryId, setEditingEntryId] = useState<string | null>(null);
    const [step, setStep] = useState(1);

    const [checkInFormData, setCheckInFormData] = useState<CheckInFormData>(INITIAL_CHECKIN_DATA);
    const [checkOutFormData, setCheckOutFormData] = useState<CheckOutFormData>(INITIAL_CHECKOUT_DATA);
    const [maintenanceFormData, setMaintenanceFormData] = useState<MaintenanceFormData>(INITIAL_MAINTENANCE_DATA);

    const [isStatusModalOpen, setStatusModalOpen] = useState(false);
    const [statusTargetId, setStatusTargetId] = useState<string | null>(null);
    const [previewImage, setPreviewImage] = useState<string | null>(null);

    const [availableStock, setAvailableStock] = useState<StockItem[]>([]);
    const [selectedMaterialId, setSelectedMaterialId] = useState('');
    const [selectedMaterialQty, setSelectedMaterialQty] = useState(1);

    const [tempLines, setTempLines] = useState('');
    const [tempModules, setTempModules] = useState('');
    const [tempOrientation, setTempOrientation] = useState<'Retrato' | 'Paisagem'>('Retrato');

    const isReadOnly = editingEntryId 
        ? entries.find(e => e.id === editingEntryId)?.status === 'Efetivado'
        : false;

    // Load Stock Items
    useEffect(() => {
        const loadStock = async () => {
            if (isModalOpen) {
                const stock = await dataService.getAll<StockItem>('stock_items', 'stock_items');
                setAvailableStock(stock.length > 0 ? stock : MOCK_STOCK_ITEMS);
            }
        };
        loadStock();
    }, [isModalOpen]);

    // CHECK-IN Handlers
    const handleCheckInInputChange = (field: keyof CheckInFormData, value: any) => {
        if (isReadOnly) return;
        setCheckInFormData(prev => ({ ...prev, [field]: value }));
    };

    const handleCheckInPhotoChange = async (field: keyof CheckInFormData['fotos'], e: React.ChangeEvent<HTMLInputElement>) => {
        if (isReadOnly) return;
        const file = e.target.files?.[0];
        if (file) {
            try {
                const base64 = await fileToBase64(file);
                setCheckInFormData(prev => ({
                    ...prev,
                    fotos: { ...prev.fotos, [field]: base64 }
                }));
            } catch (error) {
                console.error("Error converting file to base64", error);
            }
        }
    };

    const toggleTubulacao = (value: string) => {
        if (isReadOnly) return;
        setCheckInFormData(prev => {
            const current = prev.tipoTubulacao;
            if (current.includes(value)) return { ...prev, tipoTubulacao: current.filter(i => i !== value) };
            return { ...prev, tipoTubulacao: [...current, value] };
        });
    };

    // CHECK-OUT Handlers
    const handleCheckOutInputChange = (field: keyof CheckOutFormData, value: any) => {
        if (isReadOnly) return;
        setCheckOutFormData(prev => ({ ...prev, [field]: value }));
    };

    const handleCheckOutPhotoUpload = (field: keyof CheckOutFormData['fotos'], e: React.ChangeEvent<HTMLInputElement>) => {
        if (isReadOnly) return;
        const file = e.target.files?.[0];
        if (file) {
            fileToBase64(file).then(base64 => {
                setCheckOutFormData(prev => ({
                    ...prev,
                    fotos: { 
                        ...prev.fotos, 
                        [field]: [...(prev.fotos[field] || []), base64]
                    }
                }));
            });
        }
    };

    const handleRemoveCheckOutPhoto = (field: keyof CheckOutFormData['fotos'], index: number) => {
        if (isReadOnly) return;
        setCheckOutFormData(prev => ({
            ...prev,
            fotos: {
                ...prev.fotos,
                [field]: prev.fotos[field].filter((_, i) => i !== index)
            }
        }));
    }

    // MAINTENANCE Handlers
    const handleMaintenanceInputChange = (field: keyof MaintenanceFormData, value: any) => {
        if (isReadOnly) return;
        setMaintenanceFormData(prev => ({ ...prev, [field]: value }));
    };

    const handleMaintenancePhotoUpload = (field: 'fotosAntes' | 'fotosDepois', e: React.ChangeEvent<HTMLInputElement>) => {
        if (isReadOnly) return;
        const file = e.target.files?.[0];
        if (file) {
            fileToBase64(file).then(base64 => {
                setMaintenanceFormData(prev => ({
                    ...prev,
                    [field]: [...(prev[field] || []), base64]
                }));
            });
        }
    };

    const handleRemoveMaintenancePhoto = (field: 'fotosAntes' | 'fotosDepois', index: number) => {
        if (isReadOnly) return;
        setMaintenanceFormData(prev => ({
            ...prev,
            [field]: prev[field].filter((_, i) => i !== index)
        }));
    };

    // Material Selection Handlers
    const handleAddMaterialGeneric = (
        targetList: ChecklistItem[],
        setTargetState: React.Dispatch<React.SetStateAction<any>>,
        fieldKey: string
    ) => {
        if (isReadOnly) return;
        if (!selectedMaterialId) return;

        const stockItem = availableStock.find(i => i.id === selectedMaterialId);
        if (!stockItem) return;

        const newMaterial: ChecklistItem = {
            id: stockItem.id,
            name: stockItem.name,
            quantity: selectedMaterialQty,
            unit: stockItem.unit, // unit from StockItem
        };

        const existingIndex = targetList.findIndex(m => m.id === newMaterial.id);

        let updatedList;
        if (existingIndex >= 0) {
            updatedList = [...targetList];
            updatedList[existingIndex].quantity += newMaterial.quantity;
        } else {
            updatedList = [...targetList, newMaterial];
        }

        setTargetState((prev: any) => ({ ...prev, [fieldKey]: updatedList }));
        setSelectedMaterialId('');
        setSelectedMaterialQty(1);
    };

    const handleRemoveMaterialGeneric = (
        index: number,
        targetList: ChecklistItem[],
        setTargetState: React.Dispatch<React.SetStateAction<any>>,
        fieldKey: string
    ) => {
        if (isReadOnly) return;
        setTargetState((prev: any) => ({
            ...prev,
            [fieldKey]: targetList.filter((_, i) => i !== index)
        }));
    };

    const handleAddMaterial = () => handleAddMaterialGeneric(checkInFormData.materialExtra, setCheckInFormData, 'materialExtra');
    const handleRemoveMaterial = (i: number) => handleRemoveMaterialGeneric(i, checkInFormData.materialExtra, setCheckInFormData, 'materialExtra');

    const handleAddCheckOutMaterial = () => handleAddMaterialGeneric(checkOutFormData.materiaisUsados, setCheckOutFormData, 'materiaisUsados');
    const handleRemoveCheckOutMaterial = (i: number) => handleRemoveMaterialGeneric(i, checkOutFormData.materiaisUsados, setCheckOutFormData, 'materiaisUsados');

    const handleAddMaintenanceMaterial = () => handleAddMaterialGeneric(maintenanceFormData.materiaisUtilizados, setMaintenanceFormData, 'materiaisUtilizados');
    const handleRemoveMaintenanceMaterial = (i: number) => handleRemoveMaterialGeneric(i, maintenanceFormData.materiaisUtilizados, setMaintenanceFormData, 'materiaisUtilizados');

    // Orientação Handlers
    const handleAddOrientation = () => {
        if (isReadOnly) return;
        if (!tempLines || !tempModules) return;

        const newOrientation: OrientationEntry = {
            lines: Number(tempLines),
            modules: Number(tempModules),
            orientation: tempOrientation
        };

        setCheckInFormData(prev => ({
            ...prev,
            qtdLinhasOrientacao: [...prev.qtdLinhasOrientacao, newOrientation]
        }));

        setTempLines('');
        setTempModules('');
        setTempOrientation('Retrato');
    };

    const handleRemoveOrientation = (index: number) => {
        if (isReadOnly) return;
        setCheckInFormData(prev => ({
            ...prev,
            qtdLinhasOrientacao: prev.qtdLinhasOrientacao.filter((_, i) => i !== index)
        }));
    };

    const handleNewEntry = () => {
        setEditingEntryId(null);
        setCheckInFormData(INITIAL_CHECKIN_DATA);
        setCheckOutFormData(INITIAL_CHECKOUT_DATA);
        setMaintenanceFormData(INITIAL_MAINTENANCE_DATA);
        setStep(1);
        setModalOpen(true);
    };

    const handleEditEntry = (entry: ChecklistEntry) => {
        setEditingEntryId(entry.id);
        if (isCheckIn) {
            if (entry.details) {
                const safeDetails = {
                    ...entry.details,
                    materialExtra: Array.isArray(entry.details.materialExtra) ? entry.details.materialExtra : [],
                    qtdLinhasOrientacao: Array.isArray(entry.details.qtdLinhasOrientacao) ? entry.details.qtdLinhasOrientacao : []
                };
                setCheckInFormData(safeDetails as any);
            } else {
                setCheckInFormData(INITIAL_CHECKIN_DATA);
            }
        } else if (isCheckOut) {
            if (entry.checkoutDetails) {
                const safeCheckoutDetails = {
                    ...entry.checkoutDetails,
                    materiaisUsados: Array.isArray(entry.checkoutDetails.materiaisUsados) ? entry.checkoutDetails.materiaisUsados : [],
                    fotos: entry.checkoutDetails.fotos || INITIAL_CHECKOUT_DATA.fotos
                };
                setCheckOutFormData(safeCheckoutDetails as any);
            } else {
                setCheckOutFormData({ ...INITIAL_CHECKOUT_DATA, nomeCliente: entry.project });
            }
        } else {
            if (entry.maintenanceDetails) {
                const safeMaintenanceDetails = {
                    ...entry.maintenanceDetails,
                    materiaisUtilizados: Array.isArray(entry.maintenanceDetails.materiaisUtilizados) ? entry.maintenanceDetails.materiaisUtilizados : [],
                    fotosAntes: entry.maintenanceDetails.fotosAntes || [],
                    fotosDepois: entry.maintenanceDetails.fotosDepois || [],
                };
                setMaintenanceFormData(safeMaintenanceDetails as any);
            } else {
                setMaintenanceFormData({ ...INITIAL_MAINTENANCE_DATA, nomeCliente: entry.project });
            }
        }
        setStep(1);
        setModalOpen(true);
    };

    const handleSave = async () => {
        if (isReadOnly) return; 

        let entryToSave: ChecklistEntry;

        if (editingEntryId) {
            const existingEntry = entries.find(e => e.id === editingEntryId);
            if (!existingEntry) return;

            entryToSave = { ...existingEntry };

            if (isCheckIn) {
                const arranjoSummary = Array.isArray(checkInFormData.qtdLinhasOrientacao) ? `${checkInFormData.qtdLinhasOrientacao.length} arranjos` : '';
                entryToSave.project = checkInFormData.nomeTitular || existingEntry.project;
                entryToSave.notes = `${checkInFormData.cidade} - ${arranjoSummary}`;
                entryToSave.details = checkInFormData as any;
            } else if (isCheckOut) {
                entryToSave.project = checkOutFormData.nomeCliente || existingEntry.project;
                entryToSave.notes = checkOutFormData.observacoesFinais || 'Check-Out Realizado';
                entryToSave.checkoutDetails = checkOutFormData as any;
            } else {
                entryToSave.project = maintenanceFormData.nomeCliente || existingEntry.project;
                entryToSave.notes = `${maintenanceFormData.tipoManutencao} - ${maintenanceFormData.defeitoRelatado.substring(0, 20)}...`;
                entryToSave.maintenanceDetails = maintenanceFormData as any;
            }
        } else {
            // Create New
            let project = '';
            let notes = '';

            if (isCheckIn) {
                project = checkInFormData.nomeTitular;
                notes = checkInFormData.cidade;
            } else if (isCheckOut) {
                project = checkOutFormData.nomeCliente;
                notes = 'Check-Out Iniciado';
            } else {
                project = maintenanceFormData.nomeCliente;
                notes = `${maintenanceFormData.tipoManutencao} - Iniciada`;
            }

            entryToSave = {
                id: Date.now().toString(),
                project,
                responsible: 'Usuário Logado', 
                date: new Date().toISOString().split('T')[0],
                status: 'Pendente',
                notes,
                type: view,
                details: isCheckIn ? (checkInFormData as any) : undefined,
                checkoutDetails: isCheckOut ? (checkOutFormData as any) : undefined,
                maintenanceDetails: isMaintenance ? (maintenanceFormData as any) : undefined
            };
        }

        // Save to DB
        await dataService.save('checklist_entries', 'checklist_entries', entryToSave);

        // Update State
        if (editingEntryId) {
            setEntries(prev => prev.map(e => e.id === entryToSave.id ? entryToSave : e));
        } else {
            setEntries(prev => [entryToSave, ...prev]);
        }

        setModalOpen(false);
        setEditingEntryId(null);
    };

    const handleOpenStatusModal = (id: string, e: React.MouseEvent) => {
        e.stopPropagation();
        setStatusTargetId(id);
        setStatusModalOpen(true);
    }

    const confirmStatusChange = async (newStatus: 'Efetivado' | 'Perdido') => {
        if (statusTargetId) {
            const entry = entries.find(e => e.id === statusTargetId);

            if (newStatus === 'Efetivado') {
                // --- Logic for Stock Reservation on Check-In ---
                if (entry && entry.type === 'checkin') {
                    let hasInsufficientStock = false;
                    const materialsToCheck = entry.details?.materialExtra || [];

                    if (materialsToCheck.length > 0) {
                        // Fetch latest stock from DB to ensure accuracy
                        const currentStock = await dataService.getAll<StockItem>('stock_items', 'stock_items');
                        const currentRequests = await dataService.getAll<PurchaseRequest>('purchase_requests', 'purchase_requests');

                        let stockUpdated = false;
                        let requestsUpdated = false;

                        for (const item of currentStock) {
                            const neededItem = materialsToCheck.find(m => m.id === item.id);

                            if (neededItem) {
                                const qtyNeeded = neededItem.quantity;
                                const currentReserved = item.reservedQuantity || 0;
                                const currentPhysical = item.quantity;

                                // 1. Atualiza Reserva
                                const newReservedTotal = currentReserved + qtyNeeded;
                                item.reservedQuantity = newReservedTotal;

                                if (!item.reservations) {
                                    item.reservations = [];
                                }
                                item.reservations.push({
                                    id: entry.id,
                                    sourceName: entry.details?.nomeTitular || entry.project,
                                    quantity: qtyNeeded,
                                    date: new Date().toISOString()
                                });

                                // Save item immediately
                                await dataService.save('stock_items', 'stock_items', item);
                                stockUpdated = true;

                                // 2. Verifica Disponibilidade (Físico - Total Reservado)
                                const netAvailable = currentPhysical - newReservedTotal;

                                if (netAvailable < 0) {
                                    hasInsufficientStock = true;
                                }

                                // Lógica de Solicitação de Compra Automática
                                let reqQty = 0;
                                let reqReason = '';
                                let reqPriority: 'Baixa' | 'Média' | 'Alta' = 'Média';
                                let shouldRequest = false;

                                if (netAvailable < 0 || netAvailable <= item.minQuantity) {
                                    shouldRequest = true;
                                    reqQty = item.minQuantity * 2;
                                    if (reqQty === 0) reqQty = neededItem.quantity; 
                                    reqPriority = 'Alta';

                                    if (netAvailable < 0) {
                                        reqReason = `Estoque Insuficiente (Saldo Negativo: ${netAvailable})`;
                                    } else {
                                        reqReason = `Atingiu Estoque Mínimo (${item.minQuantity})`;
                                    }
                                }

                                if (shouldRequest) {
                                    const newReq: PurchaseRequest = {
                                        id: Date.now().toString() + Math.random().toString().slice(2,5),
                                        itemId: item.id,
                                        itemName: item.name,
                                        quantity: reqQty,
                                        unit: item.unit,
                                        requester: 'Sistema',
                                        date: new Date().toISOString().split('T')[0],
                                        priority: reqPriority,
                                        status: 'Pendente',
                                        reason: 'Material Obra',
                                        observation: `${reqReason} - Obra: ${entry.details?.nomeTitular}`
                                    };
                                    await dataService.save('purchase_requests', 'purchase_requests', newReq);
                                    requestsUpdated = true;
                                }
                            }
                        }

                        if (hasInsufficientStock) {
                            setTimeout(() => {
                                alert("Atenção!! Saldo de componentes insuficiente para atender essa obra. Compra Necessária.");
                            }, 100);
                        }
                    }

                    // 2. Criar Check-Out Automaticamente
                    const clientName = entry.details?.nomeTitular || entry.project;
                    const todayDate = new Date().toISOString().split('T')[0];
                    const usedMaterials = entry.details?.materialExtra ? [...entry.details.materialExtra] : [];

                    const newCheckoutEntry: ChecklistEntry = {
                        id: Date.now().toString() + '_autocheckout',
                        project: clientName,
                        responsible: entry.responsible, 
                        date: todayDate,
                        status: 'Pendente',
                        type: 'checkout',
                        notes: 'Gerado automaticamente via Check-In',
                        checkoutDetails: {
                            ...INITIAL_CHECKOUT_DATA,
                            nomeCliente: clientName,
                            dataTermino: todayDate,
                            materiaisUsados: usedMaterials
                        }
                    };

                    await dataService.save('checklist_entries', 'checklist_entries', newCheckoutEntry);
                    setEntries(prev => [newCheckoutEntry, ...prev]);

                    if (!hasInsufficientStock) {
                        alert(`Check-In Efetivado! Um novo Check-Out foi criado para "${clientName}".`);
                    }
                }

                // --- Logic for Stock Deduction on Check-Out AND Maintenance ---
                else if ((entry && entry.type === 'checkout') || (entry && entry.type === 'manutencao')) {
                    const materialsToDeduct = entry.type === 'checkout' 
                        ? entry.checkoutDetails?.materiaisUsados 
                        : entry.maintenanceDetails?.materiaisUtilizados;

                    const clientName = entry.type === 'checkout' 
                        ? entry.checkoutDetails?.nomeCliente 
                        : entry.maintenanceDetails?.nomeCliente;

                    if (materialsToDeduct && materialsToDeduct.length > 0) {
                        // Fetch fresh stock
                        const currentStock = await dataService.getAll<StockItem>('stock_items', 'stock_items');
                        let stockUpdated = false;

                        for (const item of currentStock) {
                            const usedItem = materialsToDeduct.find(m => m.id === item.id);
                            if (usedItem) {
                                // 1. Baixa no Estoque Físico
                                item.quantity = Math.max(0, item.quantity - usedItem.quantity);

                                // 2. Remove da Reserva (se estava reservado)
                                if (item.reservations) {
                                    item.reservations = item.reservations.filter(res => res.sourceName !== entry.project && res.sourceName !== clientName);
                                    const newTotalReserved = item.reservations.reduce((acc, r) => acc + r.quantity, 0);
                                    item.reservedQuantity = newTotalReserved;
                                }

                                // 3. Registra Histórico de Saída
                                const typeLabel = entry.type === 'checkout' ? 'Check-Out' : 'Manutenção';
                                const movement: StockMovement = {
                                    id: `mov_${Date.now()}_${item.id}`,
                                    itemId: item.id,
                                    type: 'saida',
                                    quantity: usedItem.quantity,
                                    date: new Date().toISOString().split('T')[0],
                                    observation: `Cliente: ${clientName || entry.project} - Baixa via ${typeLabel}`
                                };
                                await dataService.save('stock_movements', 'stock_movements', movement);

                                // Save item
                                await dataService.save('stock_items', 'stock_items', item);
                                stockUpdated = true;
                            }
                        }

                        if (stockUpdated) {
                            alert("Estoque atualizado: Baixa de materiais realizada com sucesso.");
                        }
                    }
                }
            }

            // Update Status in DB
            const updatedEntry = { ...entry, status: newStatus };
            // @ts-ignore
            await dataService.save('checklist_entries', 'checklist_entries', updatedEntry);

            setEntries(prev => prev.map(item => item.id === statusTargetId ? { ...item, status: newStatus } : item));
            setStatusModalOpen(false);
            setStatusTargetId(null);
        }
    }

    return (
        <div className="space-y-6">
            <ImagePreviewModal isOpen={!!previewImage} imageSrc={previewImage} onClose={() => setPreviewImage(null)} />

            <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                <div>
                    <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                        <ClipboardCheckIcon className="w-8 h-8 text-indigo-600" />
                        {title}
                    </h2>
                    <p className="text-gray-500 dark:text-gray-400 mt-1">
                        {description}
                    </p>
                </div>
                <button
                    onClick={handleNewEntry}
                    className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors shadow-sm"
                >
                    <AddIcon className="w-5 h-5" />
                    Novo Registro
                </button>
            </div>

            {/* Campo de Busca */}
            <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <svg className="h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                    </svg>
                </div>
                <input
                    type="text"
                    placeholder="Buscar por projeto ou cliente..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="block w-full pl-10 pr-3 py-2 border border-gray-300 dark:border-gray-600 rounded-lg leading-5 bg-white dark:bg-gray-800 placeholder-gray-500 dark:placeholder-gray-400 text-gray-900 dark:text-white focus:outline-none focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm shadow-sm"
                />
            </div>

            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg overflow-hidden">
                <table className="min-w-full text-left text-sm">
                    <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider">
                        <tr>
                            <th className="px-6 py-3">Data</th>
                            <th className="px-6 py-3">Projeto / Cliente</th>
                            <th className="px-6 py-3">Responsável</th>
                            <th className="px-6 py-3">Detalhes</th>
                            <th className="px-6 py-3">Status</th>
                            <th className="px-6 py-3 text-center">Ações</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                        {filteredEntries.map(item => (
                            <tr 
                                key={item.id} 
                                onClick={() => handleEditEntry(item)}
                                className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors cursor-pointer group"
                            >
                                <td className="px-6 py-4 text-gray-500 dark:text-gray-400">
                                    {new Date(item.date).toLocaleDateString('pt-BR', { timeZone: 'UTC' })}
                                </td>
                                <td className="px-6 py-4 font-medium text-gray-900 dark:text-white group-hover:text-indigo-600 transition-colors">
                                    {item.project}
                                </td>
                                <td className="px-6 py-4 text-gray-700 dark:text-gray-300">{item.responsible}</td>
                                <td className="px-6 py-4 text-gray-500 dark:text-gray-400 truncate max-w-xs">{item.notes || '-'}</td>
                                <td className="px-6 py-4">
                                    <span className={`px-2 py-1 text-xs font-semibold rounded-full ${
                                        item.status === 'Efetivado' 
                                        ? 'bg-green-100 text-green-800 dark:bg-green-900/30 dark:text-green-300' 
                                        : item.status === 'Perdido'
                                        ? 'bg-red-100 text-red-800 dark:bg-red-900/30 dark:text-red-300'
                                        : 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900/30 dark:text-yellow-300'
                                    }`}>
                                        {item.status}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-center flex items-center justify-center gap-2">
                                    <button
                                        type="button"
                                        title={item.status === 'Efetivado' ? "Visualizar (Apenas Leitura)" : "Editar"}
                                        className="text-gray-400 hover:text-indigo-600 p-1"
                                    >
                                        <EditIcon className="w-5 h-5" />
                                    </button>
                                    {item.status === 'Pendente' && (
                                        <button 
                                            onClick={(e) => handleOpenStatusModal(item.id, e)}
                                            className="text-indigo-600 hover:text-indigo-800 text-xs font-semibold uppercase flex items-center gap-1 justify-center p-1"
                                            title="Definir Status"
                                        >
                                            <CheckCircleIcon className="w-5 h-5" />
                                        </button>
                                    )}
                                </td>
                            </tr>
                        ))}
                        {filteredEntries.length === 0 && (
                            <tr>
                                <td colSpan={6} className="px-6 py-12 text-center text-gray-500">
                                    {searchTerm 
                                        ? `Nenhum projeto encontrado para "${searchTerm}"`
                                        : "Nenhum registro encontrado."
                                    }
                                </td>
                            </tr>
                        )}
                    </tbody>
                </table>
            </div>

            {/* Modal para Seleção de Status */}
            {isStatusModalOpen && (
                <Modal title="Definir Situação do Check-list" onClose={() => setStatusModalOpen(false)}>
                    <div className="space-y-6 py-2">
                        <p className="text-gray-600 dark:text-gray-300 text-center">
                            Como deseja classificar este check-list?
                        </p>
                        <div className="grid grid-cols-2 gap-4">
                            <button
                                onClick={() => confirmStatusChange('Efetivado')}
                                className="flex flex-col items-center justify-center p-4 bg-green-50 dark:bg-green-900/20 border-2 border-green-200 dark:border-green-800 rounded-xl hover:bg-green-100 dark:hover:bg-green-900/40 hover:border-green-400 transition-all group"
                            >
                                <div className="p-3 bg-green-100 dark:bg-green-800 rounded-full mb-2 group-hover:scale-110 transition-transform">
                                    <CheckCircleIcon className="w-8 h-8 text-green-600 dark:text-green-200" />
                                </div>
                                <span className="font-bold text-green-700 dark:text-green-300">Efetivado</span>
                                <span className="text-xs text-green-600/70 dark:text-green-400/70 mt-1">Finalizado com sucesso</span>
                            </button>

                            <button
                                onClick={() => confirmStatusChange('Perdido')}
                                className="flex flex-col items-center justify-center p-4 bg-red-50 dark:bg-red-900/20 border-2 border-red-200 dark:border-red-800 rounded-xl hover:bg-red-100 dark:hover:bg-red-900/40 hover:border-red-400 transition-all group"
                            >
