/**
 * Data Service - LocalStorage Only
 * Sistema 100% offline salvando no navegador.
 */
class DataService {

    // Buscar todos os itens
    async getAll<T>(tableName: string, localStorageKey: string): Promise<T[]> {
        return new Promise((resolve) => {
            setTimeout(() => {
                try {
                    const local = localStorage.getItem(localStorageKey);
                    resolve(local ? JSON.parse(local) : []);
                } catch (e) {
                    console.error(`Erro ao ler ${localStorageKey}`, e);
                    resolve([]);
                }
            }, 100); // Simula um pequeno delay de rede
        });
    }

    // Salvar ou Atualizar item
    async save<T extends { id: string | number }>(tableName: string, localStorageKey: string, item: T) {
        return new Promise(async (resolve, reject) => {
            setTimeout(async () => {
                try {
                    const currentLocal = await this.getAll<T>(tableName, localStorageKey);
                    // @ts-ignore
                    const index = currentLocal.findIndex((i: any) => String(i.id) === String(item.id));

                    let newLocal;
                    if (index >= 0) {
                        newLocal = [...currentLocal];
                        newLocal[index] = item;
                    } else {
                        newLocal = [...currentLocal, item];
                    }

                    localStorage.setItem(localStorageKey, JSON.stringify(newLocal));
                    resolve(item);
                } catch (e) {
                    console.error(`[DataService] Erro ao salvar em localStorage para '${localStorageKey}'`, e);
                    reject(e);
                }
            }, 100);
        });
    }

    // Excluir item
    async delete(tableName: string, localStorageKey: string, id: string | number) {
        return new Promise(async (resolve, reject) => {
            setTimeout(async () => {
                try {
                    const currentLocal = await this.getAll<any>(tableName, localStorageKey);
                    const newLocal = currentLocal.filter((i: any) => String(i.id) !== String(id));
                    localStorage.setItem(localStorageKey, JSON.stringify(newLocal));
                    resolve(true);
                } catch (e) {
                    console.error(`[DataService] Erro ao excluir do localStorage para '${localStorageKey}'`, e);
                    reject(e);
                }
            }, 100);
        });
    }
}

