import { createClient } from '@supabase/supabase-js';

// Tenta pegar as variáveis de ambiente do Vite (import.meta.env) ou globais (process.env)
const supabaseUrl = import.meta.env?.VITE_SUPABASE_URL || '';
const supabaseKey = import.meta.env?.VITE_SUPABASE_ANON_KEY || '';

// Se as chaves não existirem, o cliente será nulo, ativando o modo offline (LocalStorage)
export const supabase = (supabaseUrl && supabaseKey) 
  ? createClient(supabaseUrl, supabaseKey) 
  : null;

import { supabase } from '../supabaseClient';

/**
 * Data Service - Híbrido (Supabase + LocalStorage Fallback)
 * Se as credenciais do Supabase existirem, usa o Banco de Dados.
 * Se não, usa o LocalStorage para demonstração/offline.
 */
class DataService {

    private isSupabaseEnabled(): boolean {
        return !!supabase;
    }

    // Buscar todos os itens
    async getAll<T>(tableName: string, localStorageKey: string): Promise<T[]> {
        if (this.isSupabaseEnabled()) {
            try {
                // @ts-ignore
                const { data, error } = await supabase.from(tableName).select('*');
                if (error) {
                    console.error(`Erro Supabase [${tableName}]:`, error);
                    throw error;
                }
                return data as T[];
            } catch (e) {
                console.warn(`Falha ao conectar Supabase para ${tableName}, tentando local...`);
                // Fallback silencioso para não travar a UI se a tabela não existir ainda
                return []; 
            }
        }

        // Fallback LocalStorage
        return new Promise((resolve) => {
            setTimeout(() => {
                try {
                    const local = localStorage.getItem(localStorageKey);
                    resolve(local ? JSON.parse(local) : []);
                } catch (e) {
                    console.error(`Erro ao ler ${localStorageKey}`, e);
                    resolve([]);
                }
            }, 100);
        });
    }

    // Salvar ou Atualizar item
    async save<T extends { id: string | number }>(tableName: string, localStorageKey: string, item: T) {
        if (this.isSupabaseEnabled()) {
            try {
                // Remove campos que podem dar conflito ou não existem no banco se necessário
                // O upsert funciona como "Insert ou Update" baseado no ID
                // @ts-ignore
                const { data, error } = await supabase.from(tableName).upsert(item).select();
                if (error) throw error;
                return data ? data[0] : item;
            } catch (e) {
                console.error(`Erro Supabase Save [${tableName}]:`, e);
                // Não faz fallback no save para evitar inconsistência de IDs entre local e nuvem
                throw e;
            }
        }

        // Fallback LocalStorage
        return new Promise(async (resolve, reject) => {
            setTimeout(async () => {
                try {
                    const currentLocal = await this.getAll<T>(tableName, localStorageKey);
                    // @ts-ignore
                    const index = currentLocal.findIndex((i: any) => String(i.id) === String(item.id));

                    let newLocal;
                    if (index >= 0) {
                        newLocal = [...currentLocal];
                        newLocal[index] = item;
                    } else {
                        newLocal = [...currentLocal, item];
                    }

                    localStorage.setItem(localStorageKey, JSON.stringify(newLocal));
                    resolve(item);
                } catch (e) {
                    console.error(`[DataService] Erro ao salvar em localStorage para '${localStorageKey}'`, e);
                    reject(e);
                }
            }, 100);
        });
    }

    // Excluir item
    async delete(tableName: string, localStorageKey: string, id: string | number) {
        if (this.isSupabaseEnabled()) {
            try {
                // @ts-ignore
                const { error } = await supabase.from(tableName).delete().eq('id', id);
                if (error) throw error;
                return true;
            } catch (e) {
                console.error(`Erro Supabase Delete [${tableName}]:`, e);
                throw e;
            }
        }

        // Fallback LocalStorage
        return new Promise(async (resolve, reject) => {
            setTimeout(async () => {
                try {
                    const currentLocal = await this.getAll<any>(tableName, localStorageKey);
                    const newLocal = currentLocal.filter((i: any) => String(i.id) !== String(id));
                    localStorage.setItem(localStorageKey, JSON.stringify(newLocal));
                    resolve(true);
                } catch (e) {
                    console.error(`[DataService] Erro ao excluir do localStorage para '${localStorageKey}'`, e);
                    reject(e);
                }
            }, 100);
        });
    }
}

