/**
 * Data Service - LocalStorage Only
 * Sistema funcionando puramente no navegador.
 */
class DataService {

    // Simula um pequeno delay de rede para manter a UX consistente (loading spinners, etc)
    private async wait(ms: number) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    // Buscar todos os itens
    async getAll<T>(localStorageKey: string): Promise<T[]> {
        await this.wait(50); // Delay simulado
        try {
            const local = localStorage.getItem(localStorageKey);
            return local ? JSON.parse(local) : [];
        } catch (e) {
            console.error(`Erro ao ler ${localStorageKey}`, e);
            return [];
        }
    }

    // Salvar ou Atualizar item
    async save<T extends { id: string | number }>(localStorageKey: string, item: T) {
        await this.wait(50); // Delay simulado
        try {
            const currentLocal = await this.getAll<T>(localStorageKey);
            // @ts-ignore
            const index = currentLocal.findIndex((i: any) => String(i.id) === String(item.id));

            let newLocal;
            if (index >= 0) {
                newLocal = [...currentLocal];
                newLocal[index] = item;
            } else {
                newLocal = [...currentLocal, item];
            }

            localStorage.setItem(localStorageKey, JSON.stringify(newLocal));
            return item;
        } catch (e) {
            console.error(`[DataService] Erro ao salvar em localStorage para '${localStorageKey}'`, e);
            throw e;
        }
    }

    // Excluir item
    async delete(localStorageKey: string, id: string | number) {
        await this.wait(50); // Delay simulado
        try {
            const currentLocal = await this.getAll<any>(localStorageKey);
            const newLocal = currentLocal.filter((i: any) => String(i.id) !== String(id));
            localStorage.setItem(localStorageKey, JSON.stringify(newLocal));
            return true;
        } catch (e) {
            console.error(`[DataService] Erro ao excluir do localStorage para '${localStorageKey}'`, e);
            throw e;
        }
    }
}

export const dataService = new DataService();

import React, { useEffect, useState, useMemo } from 'react';
import DashboardCard from '../components/DashboardCard';
import ChartComponent from '../components/ChartComponent';
import RecentTransactions from '../components/RecentTransactions';
import { DollarIcon, UsersIcon, TrendUpIcon, DocumentReportIcon } from '../assets/icons';
import type { FinancialTransaction, SavedOrcamento, ExpenseReport } from '../types';
import { MOCK_FINANCIAL_TRANSACTIONS } from '../constants';
import { dataService } from '../services/dataService';

const DashboardPage: React.FC = () => {
  const [transactions, setTransactions] = useState<FinancialTransaction[]>([]);
  const [orcamentos, setOrcamentos] = useState<SavedOrcamento[]>([]);
  const [expenseReports, setExpenseReports] = useState<ExpenseReport[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // Carregar dados reais (Local Storage)
  useEffect(() => {
      const loadData = async () => {
          setIsLoading(true);

          // 1. Financeiro
          const txs = await dataService.getAll<FinancialTransaction>('financial_transactions');
          if (txs.length > 0) {
              setTransactions(txs);
          } else {
              setTransactions(MOCK_FINANCIAL_TRANSACTIONS); // Fallback para demonstração inicial
          }

          // 2. Orçamentos
          const orcs = await dataService.getAll<SavedOrcamento>('orcamentos');
          setOrcamentos(orcs);

          // 3. Relatórios
          const reps = await dataService.getAll<ExpenseReport>('expense_reports');
          setExpenseReports(reps);

          setIsLoading(false);
      };

      loadData();
  }, []);

  // --- KPI Metrics Calculation ---
  const metrics = useMemo(() => {
      // Receita Total (Soma de tudo que foi 'pago' e é 'receita')
      const receitaTotal = transactions
          .filter(t => t.type === 'receita' && t.status === 'pago')
          .reduce((acc, curr) => acc + curr.amount, 0);

      // Novos Projetos (Contagem de orçamentos criados no mês atual)
      const currentMonth = new Date().getMonth();
      const currentYear = new Date().getFullYear();

      const novosProjetosMes = orcamentos.filter(o => {
          const d = new Date(o.savedAt);
          return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
      }).length;

      // Crescimento (Comparativo simples: Receita deste mês vs mês passado)
      const thisMonthReceita = transactions
          .filter(t => t.type === 'receita' && t.status === 'pago' && t.paymentDate)
          .filter(t => {
              const d = new Date(t.paymentDate!);
              return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
          })
          .reduce((acc, curr) => acc + curr.amount, 0);

      const lastMonthDate = new Date();
      lastMonthDate.setMonth(currentMonth - 1);
      const lastMonth = lastMonthDate.getMonth();
      const lastMonthYear = lastMonthDate.getFullYear();

      const lastMonthReceita = transactions
          .filter(t => t.type === 'receita' && t.status === 'pago' && t.paymentDate)
          .filter(t => {
              const d = new Date(t.paymentDate!);
              return d.getMonth() === lastMonth && d.getFullYear() === lastMonthYear;
          })
          .reduce((acc, curr) => acc + curr.amount, 0);

      let growth = 0;
      if (lastMonthReceita > 0) {
          growth = ((thisMonthReceita - lastMonthReceita) / lastMonthReceita) * 100;
      } else if (thisMonthReceita > 0) {
          growth = 100; // Crescimento infinito tecnicamente, mas 100% para simplificar visual
      }

      // Relatórios Pendentes (Status 'Transferido' ou 'Em Aberto')
      const relatoriosPendentes = expenseReports.filter(r => r.status === 'Transferido' || r.status === 'Em Aberto').length;

      return {
          receitaTotal,
          novosProjetosMes,
          growth,
          relatoriosPendentes
      };
  }, [transactions, orcamentos, expenseReports]);

  // --- Chart Data Preparation (Last 6 Months) ---
  const chartData = useMemo(() => {
      const data = [];
      const today = new Date();

      for (let i = 5; i >= 0; i--) {
          const d = new Date(today.getFullYear(), today.getMonth() - i, 1);
          const month = d.getMonth();
          const year = d.getFullYear();
          const monthName = d.toLocaleString('pt-BR', { month: 'short' });
          const label = `${monthName.charAt(0).toUpperCase() + monthName.slice(1)}/${year.toString().slice(2)}`;

          // Filtrar transações pagas neste mês
          const monthTxs = transactions.filter(t => {
              if (t.status !== 'pago' || !t.paymentDate) return false;
              const tDate = new Date(t.paymentDate);
              return tDate.getMonth() === month && tDate.getFullYear() === year;
          });

          const receita = monthTxs.filter(t => t.type === 'receita').reduce((acc, c) => acc + c.amount, 0);
          const despesa = monthTxs.filter(t => t.type === 'despesa').reduce((acc, c) => acc + c.amount, 0);

          data.push({
              name: label,
              receita,
              despesa
          });
      }
      return data;
  }, [transactions]);

  const formatCurrency = (val: number) => {
      if (isNaN(val)) return 'R$ 0,00';
      const rounded = Math.ceil(val * 100) / 100;
      return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(rounded);
  };

  if (isLoading) {
      return (
          <div className="flex items-center justify-center h-96">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
          </div>
      );
  }

  return (
    <div className="space-y-6">
      {/* Cards Section */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
        <DashboardCard 
            title="Receita Acumulada" 
            value={formatCurrency(metrics.receitaTotal)} 
            icon={DollarIcon} 
            color="bg-green-500" 
        />
        <DashboardCard 
            title="Novos Projetos (Mês)" 
            value={metrics.novosProjetosMes.toString()} 
            icon={UsersIcon} 
            color="bg-blue-500" 
        />
        <DashboardCard 
            title="Crescimento Mensal" 
            value={`${metrics.growth > 0 ? '+' : ''}${metrics.growth.toFixed(1)}%`} 
            icon={TrendUpIcon} 
            color={metrics.growth >= 0 ? "bg-indigo-500" : "bg-red-500"} 
        />
        <DashboardCard 
            title="Relatórios Pendentes" 
            value={metrics.relatoriosPendentes.toString()} 
            icon={DocumentReportIcon} 
            color={metrics.relatoriosPendentes > 0 ? "bg-yellow-500" : "bg-gray-400"} 
        />
      </div>

      {/* Main Content Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-auto lg:h-96">
        <div className="lg:col-span-2 h-full">
            <ChartComponent data={chartData} />
        </div>
        <div className="lg:col-span-1 h-full">
            <RecentTransactions transactions={transactions} />
        </div>
      </div>
    </div>
  );
};

export default DashboardPage;

import React, { useState, useEffect, useMemo } from 'react';
import type { SavedOrcamento, OrcamentoPageProps, OrcamentoStatus, SalesSummaryItem } from '../types';
import { TrashIcon, AddIcon, EditIcon, FilterIcon, CalendarIcon, DollarIcon, TrendUpIcon, ChevronDownIcon } from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import { dataService } from '../services/dataService';

const OrcamentoPage: React.FC<OrcamentoPageProps> = ({ setCurrentPage, onEdit }) => {
  const [orcamentos, setOrcamentos] = useState<SavedOrcamento[]>([]);
  const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);
  const [orcamentoToDeleteId, setOrcamentoToDeleteId] = useState<number | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // Estados para filtros
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState<OrcamentoStatus | 'Todos'>('Todos');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  // Carregar orçamentos e inicializar datas padrão
  useEffect(() => {
    const loadData = async () => {
        setIsLoading(true);
        const data = await dataService.getAll<SavedOrcamento>('orcamentos');
        setOrcamentos(data);
        setIsLoading(false);
    };
    loadData();

    // Configurar datas padrão (Mês Atual)
    const date = new Date();
    const firstDay = new Date(date.getFullYear(), date.getMonth(), 1);
    const lastDay = new Date(date.getFullYear(), date.getMonth() + 1, 0);

    // Format YYYY-MM-DD
    const formatDate = (d: Date) => {
        const year = d.getFullYear();
        const month = String(d.getMonth() + 1).padStart(2, '0');
        const day = String(d.getDate()).padStart(2, '0');
        return `${year}-${month}-${day}`;
    };

    setStartDate(formatDate(firstDay));
    setEndDate(formatDate(lastDay));
  }, []);

  const handleDeleteClick = (id: number) => {
      setOrcamentoToDeleteId(id);
      setDeleteModalOpen(true);
  };

  const confirmDelete = async () => {
    if (orcamentoToDeleteId !== null) {
      // 1. Delete from Storage
      await dataService.delete('orcamentos', orcamentoToDeleteId);

      // 2. Remove from Sales Summary if exists
      removeFromSalesSummary(orcamentoToDeleteId);

      // 3. Update State
      setOrcamentos(prevOrcamentos => prevOrcamentos.filter(o => o.id !== orcamentoToDeleteId));

      setDeleteModalOpen(false);
      setOrcamentoToDeleteId(null);
    }
  };

  // Remove do Resumo de Vendas
  const removeFromSalesSummary = async (orcamentoId: number) => {
      try {
          const currentSales = await dataService.getAll<SalesSummaryItem>('sales_summary');
          const saleToDelete = currentSales.find(s => s.orcamentoId === orcamentoId);

          if (saleToDelete) {
              await dataService.delete('sales_summary', saleToDelete.id);
          }
      } catch (error) {
          console.error("Erro ao remover do resumo de vendas:", error);
      }
  };

  // Logic to transfer Approved Budget to Sales Summary
  const transferToSalesSummary = async (orcamento: SavedOrcamento) => {
      try {
          const currentSales = await dataService.getAll<SalesSummaryItem>('sales_summary');

          // Find relevant variant (Principal or First)
          let variant = null;
          if (orcamento.variants && orcamento.variants.length > 0) {
              variant = orcamento.variants.find(v => v.isPrincipal) || orcamento.variants[0];
          } else {
              // Legacy structure fallback
              variant = {
                  formState: orcamento.formState,
                  calculated: orcamento.calculated
              };
          }

          if (!variant || !variant.formState || !variant.calculated) {
              console.error("Dados do orçamento incompletos para transferência.");
              return;
          }

          const fs = variant.formState;
          const calc = variant.calculated;

          // Cálculo específico da Instalação Terceirizada
          const instalacaoTerceirizada = (fs.terceiroInstalacaoQtd || 0) * (fs.terceiroInstalacaoCusto || 0);

          const saleItem: SalesSummaryItem = {
              id: Date.now(), // Unique ID for the sale entry
              orcamentoId: orcamento.id, // Link back to budget
              clientName: fs.nomeCliente || 'Cliente Sem Nome',
              date: fs.dataOrcamento || orcamento.savedAt.split('T')[0],
              closedValue: calc.precoVendaFinal || 0,
              systemCost: calc.valorVendaSistema || 0,
              homologation: fs.projetoHomologacaoCusto || 0,
              materialCost: calc.totalEstrutura || 0,
              installation: instalacaoTerceirizada, 
              travelCost: fs.custoViagem || 0,
              technicalVisit: fs.visitaTecnicaCusto || 0,
              localAdjustment: fs.adequacaoLocalCusto || 0,
              invoicedTax: calc.nfServicoValor || 0,
              commission: calc.comissaoVendasValor || 0,
              bankFees: 0, 
              totalCost: (calc.precoVendaFinal || 0) - (calc.lucroLiquido || 0),
              netProfit: calc.lucroLiquido || 0,
              finalMargin: calc.margemLiquida || 0
          };

          // Check if already exists (Update) or Create New
          const existing = currentSales.find(s => s.orcamentoId === orcamento.id);

          if (existing) {
              // Preserve ID, update data
              const updatedSale = { ...saleItem, id: existing.id };
              await dataService.save('sales_summary', updatedSale);
          } else {
              await dataService.save('sales_summary', saleItem);
          }

          alert(`Orçamento de ${saleItem.clientName} aprovado! Venda registrada no Resumo de Vendas.`);

      } catch (error) {
          console.error("Erro ao transferir para resumo de vendas:", error);
          alert("Ocorreu um erro ao registrar a venda.");
      }
  };

  const handleStatusChange = async (id: number, newStatus: OrcamentoStatus) => {
      // Optimistic Update
      const updatedOrcamentos = orcamentos.map(orc => 
          orc.id === id ? { ...orc, status: newStatus } : orc
      );
      setOrcamentos(updatedOrcamentos);

      // Persist Change
      const orcamento = orcamentos.find(o => o.id === id);
      if (orcamento) {
          const updatedOrcamento = { ...orcamento, status: newStatus };
          await dataService.save('orcamentos', updatedOrcamento);

          if (newStatus === 'Aprovado') {
              transferToSalesSummary(updatedOrcamento);
          } else {
              removeFromSalesSummary(id);
          }
      }
  };

  const formatCurrency = (value: number) => {
    if (isNaN(value)) return 'R$ 0,00';
    const rounded = Math.ceil(value * 100) / 100;
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(rounded);
  };

  const getDisplayData = (orc: SavedOrcamento) => {
      let clientName = "Orçamento sem nome";
      let displayPrice = 0;
      let lucroLiquido = 0;
      let variantCount = 0;
      let principalVariantName = "";
      let dataOrcamento = "";

      if (orc.variants && orc.variants.length > 0) {
          const principal = orc.variants.find(v => v.isPrincipal) || orc.variants[0];
          clientName = principal.formState.nomeCliente || "Orçamento sem nome";
          displayPrice = principal.calculated.precoVendaFinal || 0;
          lucroLiquido = principal.calculated.lucroLiquido || 0;
          variantCount = orc.variants.length;
          principalVariantName = principal.name;
          dataOrcamento = principal.formState.dataOrcamento || "";
      } else if (orc.formState) {
          clientName = orc.formState.nomeCliente || "Orçamento sem nome";
          displayPrice = orc.calculated.precoVendaFinal || 0;
          lucroLiquido = orc.calculated.lucroLiquido || 0;
          variantCount = 1;
          principalVariantName = "Principal";
          dataOrcamento = orc.formState.dataOrcamento || "";
      }

      if (!dataOrcamento && orc.savedAt) {
          dataOrcamento = orc.savedAt.split('T')[0];
      }

      return { clientName, displayPrice, lucroLiquido, variantCount, principalVariantName, dataOrcamento };
  };

  const { filteredOrcamentos, totalVendaFiltrado, totalLucroFiltrado } = useMemo(() => {
      let totalVenda = 0;
      let totalLucro = 0;

      const filtered = orcamentos.filter(orc => {
          const { clientName, dataOrcamento, displayPrice, lucroLiquido } = getDisplayData(orc);
          const status = orc.status || 'Em Aberto'; 

          if (searchTerm && !clientName.toLowerCase().includes(searchTerm.toLowerCase())) return false;
          if (filterStatus !== 'Todos' && status !== filterStatus) return false;
          if (startDate && dataOrcamento < startDate) return false;
          if (endDate && dataOrcamento > endDate) return false;

          totalVenda += displayPrice;
          totalLucro += lucroLiquido;

          return true;
      });

      return { filteredOrcamentos: filtered, totalVendaFiltrado: totalVenda, totalLucroFiltrado: totalLucro };
  }, [orcamentos, searchTerm, filterStatus, startDate, endDate]);

  const handleClearFilters = () => {
      setStartDate('');
      setEndDate('');
      setFilterStatus('Todos');
      setSearchTerm('');
  };

  const getStatusColor = (status: OrcamentoStatus) => {
      switch (status) {
          case 'Aprovado': return 'bg-green-100 text-green-800 border-green-200';
          case 'Perdido': return 'bg-red-100 text-red-800 border-red-200';
          case 'Parado': return 'bg-gray-100 text-gray-800 border-gray-200';
          default: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
      }
  };

  if (isLoading) {
      return <div className="flex justify-center p-10"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600"></div></div>;
  }

  return (
    <div className="space-y-6">
        {/* KPI Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <DashboardCard title="Volume de Vendas (Filtrado)" value={formatCurrency(totalVendaFiltrado)} icon={DollarIcon} color="bg-blue-600" />
            <DashboardCard title="Lucro Líquido Estimado" value={formatCurrency(totalLucroFiltrado)} icon={TrendUpIcon} color="bg-green-600" />
        </div>

        <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
            <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center mb-6 gap-4">
                <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Projetos / Orçamentos</h2>
                <button onClick={() => setCurrentPage('NOVO_ORCAMENTO')} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors w-full lg:w-auto justify-center shadow-md">
                    <AddIcon className="w-5 h-5" /> Novo Projeto
                </button>
            </div>

            {/* Filtros */}
            <div className="flex flex-col lg:flex-row gap-4 mb-6 bg-gray-50 dark:bg-gray-700/30 p-4 rounded-lg border border-gray-200 dark:border-gray-700">
                <div className="relative flex-1">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <svg className="h-5 w-5 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
                    </div>
                    <input type="text" placeholder="Buscar cliente..." value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} className="block w-full pl-10 pr-3 py-2 border border-gray-300 dark:border-gray-600 rounded-md leading-5 bg-white dark:bg-gray-800 placeholder-gray-500 dark:placeholder-gray-400 text-gray-900 dark:text-white focus:outline-none focus:ring-1 focus:ring-indigo-500 sm:text-sm" />
                </div>
                <div className="w-full lg:w-48">
                    <div className="relative">
                        <select value={filterStatus} onChange={(e) => setFilterStatus(e.target.value as OrcamentoStatus | 'Todos')} className="block w-full pl-3 pr-8 py-2 border border-gray-300 dark:border-gray-600 rounded-md leading-5 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-1 focus:ring-indigo-500 sm:text-sm appearance-none">
                            <option value="Todos">Todos Status</option>
                            <option value="Em Aberto">Em Aberto</option>
                            <option value="Aprovado">Aprovado</option>
                            <option value="Parado">Parado</option>
                            <option value="Perdido">Perdido</option>
                        </select>
                        <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none text-gray-500"><ChevronDownIcon className="w-4 h-4" /></div>
                    </div>
                </div>
                <div className="flex items-center gap-2 bg-white dark:bg-gray-800 p-1 border border-gray-300 dark:border-gray-600 rounded-md shadow-sm">
                    <div className="pl-2 text-gray-500"><CalendarIcon className="w-5 h-5" /></div>
                    <input type="date" value={startDate} onChange={(e) => setStartDate(e.target.value)} className="border-none bg-transparent text-sm text-gray-700 dark:text-gray-200 focus:ring-0 p-1 cursor-pointer w-32" />
                    <span className="text-gray-400">-</span>
                    <input type="date" value={endDate} onChange={(e) => setEndDate(e.target.value)} className="border-none bg-transparent text-sm text-gray-700 dark:text-gray-200 focus:ring-0 p-1 cursor-pointer w-32" />
                </div>
                <button onClick={handleClearFilters} className="px-3 py-2 text-sm text-gray-600 dark:text-gray-400 hover:text-indigo-600 hover:bg-gray-100 rounded-md transition-colors whitespace-nowrap">Limpar Filtros</button>
            </div>

            {/* Lista */}
            {filteredOrcamentos.length > 0 ? (
                <div className="space-y-4">
                {filteredOrcamentos.map((orc) => {
                    const data = getDisplayData(orc);
                    const currentStatus = orc.status || 'Em Aberto';
                    return (
                        <div key={orc.id} className="bg-gray-50 dark:bg-gray-700/50 p-4 rounded-lg flex flex-col md:flex-row justify-between items-start md:items-center shadow-sm hover:shadow-md transition-shadow border border-gray-100 dark:border-gray-700 gap-4" onClick={() => onEdit(orc)}>
                            <div className="flex-1 cursor-pointer w-full">
                                <div className="flex items-center gap-3 mb-1">
                                    <p className="font-bold text-lg text-gray-900 dark:text-white truncate">{data.clientName}</p>
                                    {data.variantCount > 1 && <span className="px-2 py-0.5 rounded-full bg-blue-100 text-blue-800 text-[10px] font-medium">+{data.variantCount} ver.</span>}
                                </div>
                                <div className="flex flex-wrap items-center gap-x-4 gap-y-1 text-sm text-gray-500 dark:text-gray-400">
                                    <span className="flex items-center gap-1"><CalendarIcon className="w-4 h-4" /> {data.dataOrcamento ? new Date(data.dataOrcamento).toLocaleDateString('pt-BR', { timeZone: 'UTC' }) : 'Data N/D'}</span>
                                    <span className="hidden sm:inline">|</span>
                                    <span>Opção Principal: {data.principalVariantName}</span>
                                </div>
                            </div>
                            <div className="flex flex-col sm:flex-row items-end sm:items-center gap-4 w-full md:w-auto justify-between md:justify-end">
                                <div className="relative" onClick={(e) => e.stopPropagation()}>
                                    <select value={currentStatus} onChange={(e) => handleStatusChange(orc.id, e.target.value as OrcamentoStatus)} className={`appearance-none pl-3 pr-8 py-1.5 rounded-full text-xs font-bold uppercase tracking-wide border cursor-pointer focus:outline-none focus:ring-2 focus:ring-offset-1 focus:ring-indigo-500 ${getStatusColor(currentStatus)}`}>
                                        <option value="Em Aberto">Em Aberto</option>
                                        <option value="Aprovado">Aprovado</option>
                                        <option value="Parado">Parado</option>
                                        <option value="Perdido">Perdido</option>
                                    </select>
                                    <div className="absolute inset-y-0 right-0 pr-2 flex items-center pointer-events-none opacity-60"><ChevronDownIcon className="w-3 h-3" /></div>
                                </div>
                                <div className="text-right">
                                    <p className="text-xs text-gray-500 dark:text-gray-400">Valor Final</p>
                                    <p className="font-bold text-lg text-indigo-600 dark:text-indigo-400 whitespace-nowrap">{formatCurrency(data.displayPrice)}</p>
                                </div>
                                <div className="flex items-center gap-2 border-l pl-4 border-gray-200 dark:border-gray-600 ml-2" onClick={(e) => e.stopPropagation()}>
                                    <button onClick={(e) => { e.stopPropagation(); onEdit(orc); }} className="p-2 text-gray-500 hover:text-indigo-600 rounded-full hover:bg-indigo-50 transition-colors"><EditIcon className="w-5 h-5" /></button>
                                    <button onClick={(e) => { e.stopPropagation(); handleDeleteClick(orc.id); }} className="p-2 text-gray-500 hover:text-red-600 rounded-full hover:bg-red-50 transition-colors"><TrashIcon className="w-5 h-5" /></button>
                                </div>
                            </div>
                        </div>
                    );
                })}
                </div>
            ) : (
                <div className="mt-8 p-12 border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-xl text-center bg-gray-50 dark:bg-gray-800/50">
                    <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-gray-100 dark:bg-gray-700 mb-4 text-gray-400"><FilterIcon className="w-6 h-6" /></div>
                    <h3 className="text-xl font-semibold text-gray-700 dark:text-gray-200">Nenhum orçamento encontrado</h3>
                    <button onClick={handleClearFilters} className="mt-4 text-indigo-600 hover:text-indigo-800 font-medium text-sm">Limpar todos os filtros</button>
                </div>
            )}

            {isDeleteModalOpen && (
                <Modal title="Excluir Orçamento" onClose={() => setDeleteModalOpen(false)}>
                    <div className="space-y-6">
                        <div className="text-center">
                            <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-red-100 mb-4"><TrashIcon className="w-6 h-6 text-red-600" /></div>
                            <h3 className="text-lg font-medium text-gray-900 dark:text-white">Deseja realmente excluir o orçamento?</h3>
                            <p className="text-sm text-gray-500 dark:text-gray-400 mt-2">Esta ação não pode ser desfeita.</p>
                        </div>
                        <div className="flex justify-center gap-4">
                            <button onClick={() => setDeleteModalOpen(false)} className="px-6 py-2 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 transition-colors w-24">Não</button>
                            <button onClick={confirmDelete} className="px-6 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 font-medium transition-colors w-24">Sim</button>
                        </div>
                    </div>
                </Modal>
            )}
        </div>
    </div>
  );
};

export default OrcamentoPage;

import React, { useState, useEffect, useMemo } from 'react';
import { AddIcon, FilterIcon, CalendarIcon, TrashIcon, ClipboardListIcon, DocumentReportIcon } from '../assets/icons';
import type { FinancialTransaction, FinancialTransactionStatus, FinancialCategory, FinancialTransactionType, FinanceiroPageProps } from '../types';
import { MOCK_FINANCIAL_TRANSACTIONS, FINANCIAL_CATEGORIES } from '../constants';
import { dataService } from '../services/dataService';

import VisaoGeral from '../components/Financeiro/VisaoGeral';
import ContasTable from '../components/Financeiro/ContasTable';
import TransactionModal from '../components/Financeiro/TransactionModal';
import DREView from '../components/Financeiro/DREView';
import CategoriasView from '../components/Financeiro/CategoriasView';
import OFXImportModal from '../components/Financeiro/OFXImportModal';
import Modal from '../components/Modal';

type FinanceiroTab = 'visaoGeral' | 'aReceber' | 'aPagar';

const FinanceiroPage: React.FC<FinanceiroPageProps> = ({ view }) => {
    const [activeTab, setActiveTab] = useState<FinanceiroTab>('visaoGeral');
    const [transactions, setTransactions] = useState<FinancialTransaction[]>([]);
    const [categories, setCategories] = useState<FinancialCategory[]>([]);
    const [isModalOpen, setModalOpen] = useState(false);
    const [editingTransaction, setEditingTransaction] = useState<FinancialTransaction | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    // Estado para o Modal de Importação
    const [isImportModalOpen, setImportModalOpen] = useState(false);

    // Date Filters
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    // Estado para o modal de exclusão de transação
    const [isDeleteModalOpen, setDeleteModalOpen] = useState(false);
    const [transactionToDeleteId, setTransactionToDeleteId] = useState<string | null>(null);

    // Estado para o modal de exclusão de categoria
    const [isDeleteCategoryModalOpen, setDeleteCategoryModalOpen] = useState(false);
    const [isCategoryInUseModalOpen, setCategoryInUseModalOpen] = useState(false);
    const [categoryToDeleteId, setCategoryToDeleteId] = useState<string | null>(null);

    // Initialize Default Dates (Current Month)
    useEffect(() => {
        const date = new Date();
        const firstDay = new Date(date.getFullYear(), date.getMonth(), 1);
        const lastDay = new Date(date.getFullYear(), date.getMonth() + 1, 0);

        // Format to YYYY-MM-DD using local time to avoid timezone shifts
        const formatDate = (d: Date) => {
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, '0');
            const day = String(d.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`;
        };

        setStartDate(formatDate(firstDay));
        setEndDate(formatDate(lastDay));
    }, []);

    // Load Transactions & Categories (Local Storage)
    useEffect(() => {
        const loadData = async () => {
            setIsLoading(true);
            const txs = await dataService.getAll<FinancialTransaction>('financial_transactions');
            if (txs.length > 0) {
                setTransactions(txs);
            } else {
                setTransactions(MOCK_FINANCIAL_TRANSACTIONS);
            }

            const cats = await dataService.getAll<FinancialCategory>('financial_categories'); // Assuming you might want categories in DB too
            // Fallback for categories if DB empty
            if (cats && cats.length > 0) {
                setCategories(cats);
            } else {
                // Try local storage for categories specifically if not in dataService yet
                const localCats = localStorage.getItem('financial_categories');
                if (localCats && localCats !== '[]') {
                    setCategories(JSON.parse(localCats));
                } else {
                    setCategories(FINANCIAL_CATEGORIES);
                }
            }
            setIsLoading(false);
        };
        loadData();
    }, []);

    // Save Categories to LocalStorage
    useEffect(() => {
        localStorage.setItem('financial_categories', JSON.stringify(categories));
    }, [categories]);

    // Filter Logic
    const filteredTransactions = useMemo(() => {
        return transactions.filter(t => {
            const txDate = t.dueDate ? t.dueDate.split('T')[0] : '';
            if (!txDate) return false;
            if (startDate && txDate < startDate) return false;
            if (endDate && txDate > endDate) return false;
            return true;
        });
    }, [transactions, startDate, endDate]);

    const handleClearFilters = () => {
        setStartDate('');
        setEndDate('');
    };

    const handleOpenModal = (transaction?: FinancialTransaction) => {
        setEditingTransaction(transaction || null);
        setModalOpen(true);
    };

    const handleCloseModal = () => {
        setEditingTransaction(null);
        setModalOpen(false);
    };

    const handleImportTransactions = async (newTransactions: FinancialTransaction[]) => {
        // Save imported transactions to DB
        for (const tx of newTransactions) {
            await dataService.save('financial_transactions', tx);
        }
        setTransactions(prev => [...prev, ...newTransactions]);
        alert(`${newTransactions.length} transações importadas com sucesso!`);
    };

    const handleSaveTransaction = async (transaction: FinancialTransaction, recurrence?: { frequency: 'mensal' | 'trimestral' | 'semestral' | 'anual', occurrences: number }) => {
        // Optimistic UI update
        const transactionsToSave: FinancialTransaction[] = [];

        if (editingTransaction) {
            // Edição
            transactionsToSave.push(transaction);
            setTransactions(prev => prev.map(t => t.id === transaction.id ? transaction : t));
        } else if (recurrence) {
            // Criação com recorrência
            let monthsToAddPerStep = 0;
            switch(recurrence.frequency) {
                case 'mensal': monthsToAddPerStep = 1; break;
                case 'trimestral': monthsToAddPerStep = 3; break;
                case 'semestral': monthsToAddPerStep = 6; break;
                case 'anual': monthsToAddPerStep = 12; break;
            }

            const baseDateParts = transaction.dueDate.split('-').map(Number);
            const baseDate = new Date(baseDateParts[0], baseDateParts[1] - 1, baseDateParts[2], 12, 0, 0);

            for (let i = 0; i < recurrence.occurrences; i++) {
                const nextDate = new Date(baseDate);
                nextDate.setMonth(baseDate.getMonth() + (i * monthsToAddPerStep));

                const y = nextDate.getFullYear();
                const m = String(nextDate.getMonth() + 1).padStart(2, '0');
                const d = String(nextDate.getDate()).padStart(2, '0');
                const formattedDate = `${y}-${m}-${d}`;
                const suffix = i > 0 ? ` (${i + 1}/${recurrence.occurrences})` : ` (1/${recurrence.occurrences})`;

                transactionsToSave.push({
                    ...transaction,
                    id: i === 0 ? transaction.id : `${transaction.id}-${i}`,
                    description: `${transaction.description}${suffix}`,
                    dueDate: formattedDate,
                    status: i === 0 ? transaction.status : 'pendente',
                    paymentDate: (i === 0 && transaction.status === 'pago') ? transaction.paymentDate : undefined
                });
            }
            setTransactions(prev => [...prev, ...transactionsToSave]);
        } else {
            // Criação simples
            transactionsToSave.push(transaction);
            setTransactions(prev => [...prev, transaction]);
        }

        // Persist to DB
        for (const tx of transactionsToSave) {
            await dataService.save('financial_transactions', tx);
        }

        handleCloseModal();
    };

    const handleDeleteTransaction = (id: string) => {
        setTransactionToDeleteId(id);
        setDeleteModalOpen(true);
    }

    const confirmDeleteTransaction = async () => {
        if (transactionToDeleteId) {
            await dataService.delete('financial_transactions', transactionToDeleteId);
            setTransactions(prev => prev.filter(t => t.id !== transactionToDeleteId));
            setTransactionToDeleteId(null);
            setDeleteModalOpen(false);
        }
    }

    const handleStatusChange = async (id: string, status: FinancialTransactionStatus) => {
        const tx = transactions.find(t => t.id === id);
        if (tx) {
            const updatedTx = { 
                ...tx, 
                status, 
                paymentDate: status === 'pago' ? new Date().toISOString().split('T')[0] : undefined 
            };

            setTransactions(prev => prev.map(t => t.id === id ? updatedTx : t));
            await dataService.save('financial_transactions', updatedTx);
        }
    };

    // Category Management
    const handleAddCategory = (name: string, type: FinancialTransactionType) => {
        const newCategory: FinancialCategory = {
            id: name.toLowerCase().replace(/\s+/g, '-') + '-' + Date.now(),
            name,
            type
        };
        setCategories(prev => [...prev, newCategory]);
        // Ideally save categories to DB too, implementing later
    };

    const handleDeleteCategory = (id: string) => {
        const isUsed = transactions.some(t => t.categoryId === id);
        if (isUsed) {
            setCategoryInUseModalOpen(true);
            return;
        }
        setCategoryToDeleteId(id);
        setDeleteCategoryModalOpen(true);
    };

    const confirmDeleteCategory = () => {
        if (categoryToDeleteId) {
            setCategories(prev => prev.filter(c => c.id !== categoryToDeleteId));
            setCategoryToDeleteId(null);
            setDeleteCategoryModalOpen(false);
        }
    }

    const contasAReceber = useMemo(() => filteredTransactions.filter(t => t.type === 'receita'), [filteredTransactions]);
    const contasAPagar = useMemo(() => filteredTransactions.filter(t => t.type === 'despesa'), [filteredTransactions]);

    const renderContent = () => {
        if (isLoading) return <div className="p-10 text-center"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600 mx-auto"></div><p className="mt-4 text-gray-500">Carregando dados...</p></div>;

        switch (activeTab) {
            case 'visaoGeral':
                return <VisaoGeral transactions={filteredTransactions} onOpenImport={() => setImportModalOpen(true)} />;
            case 'aReceber':
                return <ContasTable
                    title="Contas a Receber"
                    transactions={contasAReceber}
                    categories={categories}
                    onEdit={handleOpenModal}
                    onDelete={handleDeleteTransaction}
                    onStatusChange={handleStatusChange}
                />;
            case 'aPagar':
                return <ContasTable
                    title="Contas a Pagar"
                    transactions={contasAPagar}
                    categories={categories}
                    onEdit={handleOpenModal}
                    onDelete={handleDeleteTransaction}
                    onStatusChange={handleStatusChange}
                />;
            default:
                return null;
        }
    };

    const TabButton: React.FC<{tabId: FinanceiroTab, label: string}> = ({ tabId, label }) => (
        <button
            onClick={() => setActiveTab(tabId)}
            className={`px-4 py-2 text-sm font-medium rounded-md transition-colors ${
                activeTab === tabId
                    ? 'bg-indigo-600 text-white shadow'
                    : 'text-gray-600 dark:text-gray-300 hover:bg-gray-200 dark:hover:bg-gray-700'
            }`}
        >
            {label}
        </button>
    );

    // RENDER: CATEGORIAS VIEW
    if (view === 'categorias') {
        return (
            <div className="space-y-6">
                 <div className="flex justify-between items-center bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                     <div>
                        <h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3">
                            <ClipboardListIcon className="w-8 h-8 text-indigo-600" />
                            Gestão de Categorias
                        </h2>
                        <p className="text-gray-500 dark:text-gray-400 mt-1">
                            Adicione ou remova categorias para organizar suas receitas e despesas.
                        </p>
                    </div>
                </div>

                <CategoriasView 
                    categories={categories} 
                    onAddCategory={handleAddCategory} 
                    onDeleteCategory={handleDeleteCategory} 
                />

                 {isDeleteCategoryModalOpen && (
                    <Modal title="Confirmar Exclusão" onClose={() => setDeleteCategoryModalOpen(false)}>
                        <div className="space-y-6">
                            <div className="text-center">
                                <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-red-100 mb-4">
                                    <TrashIcon className="w-6 h-6 text-red-600" />
                                </div>
                                <h3 className="text-lg font-medium text-gray-900 dark:text-white">Tem certeza que deseja excluir este item?</h3>
                                <p className="text-sm text-gray-500 dark:text-gray-400 mt-2">
                                    A exclusão da categoria é permanente.
                                </p>
                            </div>
                            <div className="flex justify-center gap-4">
                                <button
                                    onClick={() => setDeleteCategoryModalOpen(false)}
                                    className="px-6 py-2 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 dark:hover:bg-gray-600 font-medium transition-colors w-24"
                                >
                                    Não
                                </button>
                                <button
                                    onClick={confirmDeleteCategory}
                                    className="px-6 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 font-medium transition-colors w-24"
                                >
                                    Sim
                                </button>
                            </div>
                        </div>
                    </Modal>
                )}

                {isCategoryInUseModalOpen && (
                    <Modal title="Ação Bloqueada" onClose={() => setCategoryInUseModalOpen(false)}>
                        <div className="space-y-4">
                            <div className="p-3 bg-yellow-100 dark:bg-yellow-900/30 text-yellow-800 dark:text-yellow-200 rounded-md flex items-start gap-3">
                                <svg className="w-6 h-6 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"></path></svg>
                                <p className="text-sm font-medium">
                                    Não é possível excluir esta categoria pois existem transações financeiras vinculadas a ela.
                                </p>
                            </div>
                            <p className="text-sm text-gray-600 dark:text-gray-400">
                                Para excluir esta categoria, primeiro remova ou altere a categoria de todas as transações associadas a ela nas abas "A Receber" ou "A Pagar".
                            </p>
                            <div className="flex justify-end pt-2">
                                <button
                                    onClick={() => setCategoryInUseModalOpen(false)}
                                    className="px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors"
                                >
                                    Entendi
                                </button>
                            </div>
                        </div>
                    </Modal>
                )}
            </div>
        );
    }

    // RENDER: DASHBOARD VIEW & DRE VIEW
    return (
        <div className="space-y-6">
            <div className="flex flex-col lg:flex-row justify-between items-start lg:items-center gap-4">
                {view === 'dashboard' ? (
                    <div className="bg-white dark:bg-gray-800 p-1.5 rounded-lg shadow-sm flex flex-wrap items-center gap-1 sm:gap-2">
                        <TabButton tabId="visaoGeral" label="Visão Geral" />
                        <TabButton tabId="aReceber" label="A Receber" />
                        <TabButton tabId="aPagar" label="A Pagar" />
                    </div>
                ) : (
                    <div className="flex items-center gap-2">
                        <div className="p-2 bg-indigo-100 dark:bg-indigo-900 rounded-lg text-indigo-600 dark:text-indigo-400">
                             <DocumentReportIcon className="w-6 h-6" />
                        </div>
                        <div>
                             <h2 className="text-2xl font-bold text-gray-900 dark:text-white">DRE Gerencial</h2>
                             <p className="text-sm text-gray-500 dark:text-gray-400">Demonstrativo de Resultado do Exercício</p>
                        </div>
                    </div>
                )}

                <div className="flex flex-wrap items-center gap-2 w-full lg:w-auto">
                    <div className="flex items-center gap-2 bg-white dark:bg-gray-800 p-1.5 rounded-lg shadow-sm border border-gray-200 dark:border-gray-700">
                        <div className="flex items-center px-2 text-gray-500">
                            <CalendarIcon className="w-5 h-5" />
                        </div>
                        <input 
                            type="date" 
                            value={startDate} 
                            onChange={(e) => setStartDate(e.target.value)}
                            className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 focus:ring-0 p-1 cursor-pointer"
                            title="Data Início"
                        />
                        <span className="text-gray-400">-</span>
                        <input 
                            type="date" 
                            value={endDate} 
                            onChange={(e) => setEndDate(e.target.value)}
                            className="bg-transparent border-none text-sm text-gray-700 dark:text-gray-200 focus:ring-0 p-1 cursor-pointer"
                            title="Data Fim"
                        />
                        {(startDate || endDate) && (
                            <button 
                                onClick={handleClearFilters}
                                className="p-1 hover:bg-red-100 dark:hover:bg-red-900/50 text-red-500 rounded-md transition-colors"
                                title="Limpar Filtro de Datas"
                            >
                                <TrashIcon className="w-4 h-4" />
                            </button>
                        )}
                    </div>

                    <button
                        onClick={() => handleOpenModal()}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition-colors shadow ml-auto lg:ml-0"
                    >
                        <AddIcon className="w-5 h-5" />
                        <span className="hidden sm:inline">Nova Transação</span>
                    </button>
                </div>
            </div>

            <div>
                {view === 'dre' ? (
                     <DREView 
                        transactions={filteredTransactions.filter(t => t.status === 'pago')} 
                        categories={categories}
                    />
                ) : (
                    renderContent()
                )}
            </div>

            {isModalOpen && (
                <TransactionModal
                    isOpen={isModalOpen}
                    onClose={handleCloseModal}
                    onSave={handleSaveTransaction}
                    transaction={editingTransaction}
                    categories={categories}
                />
            )}

            {isImportModalOpen && (
                <OFXImportModal 
                    isOpen={isImportModalOpen} 
                    onClose={() => setImportModalOpen(false)} 
                    onImport={handleImportTransactions}
                    categories={categories} 
                />
            )}

            {isDeleteModalOpen && (
                <Modal title="Confirmar Exclusão" onClose={() => setDeleteModalOpen(false)}>
                    <div className="space-y-6">
                        <div className="text-center">
                            <div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-red-100 mb-4">
                                <TrashIcon className="w-6 h-6 text-red-600" />
                            </div>
                            <h3 className="text-lg font-medium text-gray-900 dark:text-white">Tem certeza que deseja excluir este item?</h3>
                            <p className="text-sm text-gray-500 dark:text-gray-400 mt-2">
                                Esta ação não pode ser desfeita.
                            </p>
                        </div>
                        <div className="flex justify-center gap-4">
                            <button
                                onClick={() => setDeleteModalOpen(false)}
                                className="px-6 py-2 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 dark:hover:bg-gray-600 font-medium transition-colors w-24"
                            >
                                Não
                            </button>
                            <button
                                onClick={confirmDeleteTransaction}
                                className="px-6 py-2 bg-red-600 text-white rounded-md hover:bg-red-700 font-medium transition-colors w-24"
                            >
                                Sim
                            </button>
                        </div>
                    </div>
                </Modal>
            )}
        </div>
    );
};

export default FinanceiroPage;

import React, { useState, useMemo, useEffect } from 'react';
import { ChartPieIcon, PrinterIcon, PlusIcon, TrashIcon, CogIcon, SaveIcon, EditIcon, ClipboardListIcon, CheckCircleIcon, DollarIcon, ExclamationTriangleIcon, DocumentReportIcon } from '../assets/icons';
import Modal from '../components/Modal';
import DashboardCard from '../components/DashboardCard';
import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip as RechartsTooltip, Legend, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';
import type { RelatoriosPageProps, ExpenseReportItem, ExpenseReport, ExpenseReportStatus } from '../types';
import { dataService } from '../services/dataService';

const RelatoriosPage: React.FC<RelatoriosPageProps> = ({ view, reportToEdit, onSave, onEditReport }) => {
  // --- REIMBURSEMENT STATE ---
  const [solicitante, setSolicitante] = useState('');
  const [setor, setSetor] = useState('');
  const [periodStart, setPeriodStart] = useState('');
  const [periodEnd, setPeriodEnd] = useState('');
  const [valorPorKm, setValorPorKm] = useState(1.20);

  // Config View State
  const [configKmValue, setConfigKmValue] = useState(1.20);
  const [isEditingConfig, setIsEditingConfig] = useState(false);
  const [isSuccessModalOpen, setSuccessModalOpen] = useState(false);
  const [modalMessage, setModalMessage] = useState('');

  // Payment Modal State
  const [isPayModalOpen, setPayModalOpen] = useState(false);
  const [reportToPay, setReportToPay] = useState<ExpenseReport | null>(null);

  // Transfer Modal State
  const [isTransferModalOpen, setTransferModalOpen] = useState(false);

  // History State
  const [reports, setReports] = useState<ExpenseReport[]>([]);

  const [items, setItems] = useState<ExpenseReportItem[]>([
    { id: '1', date: '', description: '', origin: '', destination: '', km: 0, toll: 0 },
  ]);

  // Load Reports from DB
  useEffect(() => {
      const loadReports = async () => {
          const data = await dataService.getAll<ExpenseReport>('expense_reports');
          setReports(data);
      };
      loadReports();
  }, []);

  // Load Config/Data based on View
  useEffect(() => {
    if (view === 'reembolso') {
        if (reportToEdit) {
            setSolicitante(reportToEdit.requester);
            setSetor(reportToEdit.sector);
            setPeriodStart(reportToEdit.periodStart || '');
            setPeriodEnd(reportToEdit.periodEnd || '');
            setItems(reportToEdit.items);
            setValorPorKm(reportToEdit.kmValueUsed);
        } else {
            setSolicitante('');
            setSetor('');
            setPeriodStart('');
            setPeriodEnd('');
            setItems([{ id: Date.now().toString(), date: '', description: '', origin: '', destination: '', km: 0, toll: 0 }]);

            const savedValue = localStorage.getItem('reembolso_config_km_value');
            if (savedValue) {
                setValorPorKm(parseFloat(savedValue));
            }
        }
    }
  }, [view, reportToEdit]);

  // Load Config View
  useEffect(() => {
    if (view === 'config') {
        const savedValue = localStorage.getItem('reembolso_config_km_value');
        if (savedValue) {
            setConfigKmValue(parseFloat(savedValue));
        }
        setIsEditingConfig(false); 
    }
  }, [view]);

  const isReadOnly = useMemo(() => {
      if (!reportToEdit) return false;
      return reportToEdit.status === 'Transferido' || reportToEdit.status === 'Pago';
  }, [reportToEdit]);

  const handleAddItem = () => setItems([...items, { id: Date.now().toString(), date: '', description: '', origin: '', destination: '', km: 0, toll: 0 }]);
  const handleRemoveItem = (id: string) => { if (items.length > 1) setItems(items.filter(item => item.id !== id)); };
  const handleItemChange = (id: string, field: keyof ExpenseReportItem, value: string | number) => setItems(prev => prev.map(item => item.id === id ? { ...item, [field]: value } : item));

  const handleSaveConfig = () => {
      localStorage.setItem('reembolso_config_km_value', configKmValue.toString());
      setIsEditingConfig(false);
      setModalMessage("O novo valor do quilômetro foi atualizado com sucesso.");
      setSuccessModalOpen(true);
  }

  const handleCancelConfig = () => {
      const savedValue = localStorage.getItem('reembolso_config_km_value');
      if (savedValue) setConfigKmValue(parseFloat(savedValue));
      setIsEditingConfig(false);
  }

  const totals = useMemo(() => {
    return items.reduce((acc, item) => {
      const reembolsoKm = Math.ceil((item.km * valorPorKm) * 100) / 100;
      const totalRow = Math.ceil((reembolsoKm + item.toll) * 100) / 100;
      return { km: acc.km + item.km, reembolsoKm: acc.reembolsoKm + reembolsoKm, toll: acc.toll + item.toll, total: acc.total + totalRow };
    }, { km: 0, reembolsoKm: 0, toll: 0, total: 0 });
  }, [items, valorPorKm]);

  const executeSave = async (targetStatus: ExpenseReportStatus) => {
      const formatDate = (dateStr: string) => {
          if(!dateStr) return '';
          const [y, m, d] = dateStr.split('-');
          return `${d}/${m}/${y}`;
      };
      const periodString = `${formatDate(periodStart)} a ${formatDate(periodEnd)}`;

      const reportToSave: ExpenseReport = {
          id: reportToEdit ? reportToEdit.id : Date.now().toString(),
          requester: solicitante,
          sector: setor,
          period: periodString,
          periodStart: periodStart,
          periodEnd: periodEnd,
          items: items,
          kmValueUsed: valorPorKm,
          status: targetStatus,
          createdAt: reportToEdit ? reportToEdit.createdAt : new Date().toISOString(),
          totalValue: totals.total
      };

      try {
          await dataService.save('expense_reports', reportToSave);

          setReports(prev => {
              if (reportToEdit) return prev.map(r => r.id === reportToSave.id ? reportToSave : r);
              return [reportToSave, ...prev];
          });

          setModalMessage(targetStatus === 'Transferido' ? "Relatório transferido com sucesso!" : "Rascunho salvo com sucesso!");
          setSuccessModalOpen(true);

          if (onSave) setTimeout(() => { setSuccessModalOpen(false); onSave(); }, 2000);
          else setTimeout(() => setSuccessModalOpen(false), 2000);
      } catch (e) {
          alert('Erro ao salvar relatório.');
      }
  };

  const handleSaveReportAction = (targetStatus: ExpenseReportStatus) => {
      if (!solicitante || !periodStart || !periodEnd) {
          alert("Preencha o Solicitante e as datas do Período.");
          return;
      }
      if (targetStatus === 'Transferido') setTransferModalOpen(true);
      else executeSave('Rascunho');
  };

  const handleDeleteReport = async (id: string) => {
      if (window.confirm("Tem certeza que deseja excluir este relatório?")) {
          await dataService.delete('expense_reports', id);
          setReports(prev => prev.filter(r => r.id !== id));
      }
  };

  const handleConfirmPay = async () => {
      if (reportToPay) {
          const updatedReport = { ...reportToPay, status: 'Pago' as ExpenseReportStatus };
          await dataService.save('expense_reports', updatedReport);
          setReports(prev => prev.map(r => r.id === reportToPay.id ? updatedReport : r));
          setPayModalOpen(false);
          setReportToPay(null);
      }
  }

  const formatCurrency = (val: number) => {
      if (isNaN(val)) return 'R$ 0,00';
      const rounded = Math.ceil(val * 100) / 100;
      return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(rounded);
  };

  const handlePrint = () => window.print();

  const analysisData = useMemo(() => {
      const paid = reports.filter(r => r.status === 'Pago').reduce((acc, r) => acc + r.totalValue, 0);
      const pending = reports.filter(r => r.status === 'Transferido').reduce((acc, r) => acc + r.totalValue, 0);
      const open = reports.filter(r => ['Rascunho', 'Em Aberto'].includes(r.status)).reduce((acc, r) => acc + r.totalValue, 0);

      const sectorMap: Record<string, number> = {};
      reports.forEach(r => {
          if (r.status === 'Pago' || r.status === 'Transferido') {
              const sec = r.sector ? r.sector.toUpperCase() : 'N/A';
              sectorMap[sec] = (sectorMap[sec] || 0) + r.totalValue;
          }
      });
      const sectorData = Object.entries(sectorMap).map(([name, value]) => ({ name, value }));

      const monthMap: Record<string, number> = {};
      reports.forEach(r => {
          if (r.status === 'Pago' || r.status === 'Transferido') {
              const date = new Date(r.createdAt);
              const key = `${date.getMonth() + 1}/${date.getFullYear()}`;
              monthMap[key] = (monthMap[key] || 0) + r.totalValue;
          }
      });
      const monthlyData = Object.entries(monthMap).map(([name, value]) => ({ name, value }));

      return { paid, pending, open, sectorData, monthlyData };
  }, [reports]);

  const PIE_COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d'];

  if (view === 'status') {
      const pendingReports = reports.filter(r => r.status === 'Transferido' || r.status === 'Em Aberto');
      return (
          <div className="space-y-6">
               <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                   <div className="flex justify-between items-center mb-6">
                       <div><h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3"><CheckCircleIcon className="w-8 h-8 text-indigo-600" /> Relatórios Aguardando Pagamento</h2><p className="text-gray-500 dark:text-gray-400 mt-1">Confirme o pagamento dos relatórios transferidos.</p></div>
                   </div>
                   <div className="overflow-x-auto">
                       <table className="min-w-full text-left text-sm">
                           <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider"><tr><th className="px-6 py-3">Data Criação</th><th className="px-6 py-3">Solicitante</th><th className="px-6 py-3">Período</th><th className="px-6 py-3">Valor Total</th><th className="px-6 py-3 text-center">Status</th><th className="px-6 py-3 text-center">Ações</th></tr></thead>
                           <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                               {pendingReports.map(report => (
                                   <tr key={report.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{new Date(report.createdAt).toLocaleDateString('pt-BR')}</td>
                                       <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{report.requester}</td>
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{report.period}</td>
                                       <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">{formatCurrency(report.totalValue)}</td>
                                       <td className="px-6 py-4 text-center"><span className="px-2 py-1 text-xs font-semibold rounded-full bg-yellow-100 text-yellow-800">Aguardando Pagamento</span></td>
                                       <td className="px-6 py-4 text-center space-x-2"><button onClick={() => {setReportToPay(report); setPayModalOpen(true);}} className="px-3 py-1.5 bg-green-600 text-white rounded hover:bg-green-700 text-xs font-medium transition-colors shadow-sm">Confirmar Pagamento</button></td>
                                   </tr>
                               ))}
                               {pendingReports.length === 0 && <tr><td colSpan={6} className="px-6 py-12 text-center text-gray-500">Não há relatórios aguardando pagamento.</td></tr>}
                           </tbody>
                       </table>
                   </div>
               </div>
               {isPayModalOpen && reportToPay && (<Modal title="Confirmar Pagamento" onClose={() => setPayModalOpen(false)}><div className="space-y-6"><div className="text-center"><div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-yellow-100 mb-4"><span className="text-2xl">?</span></div><h3 className="text-lg font-medium text-gray-900 dark:text-white">Confirmar Pagamento</h3><p className="text-sm text-gray-500 dark:text-gray-400 mt-2">Deseja confirmar o pagamento do relatório de <strong>{reportToPay.requester}</strong> no valor de <strong>{formatCurrency(reportToPay.totalValue)}</strong>?</p></div><div className="flex justify-center gap-4"><button onClick={() => setPayModalOpen(false)} className="px-4 py-2 bg-red-100 text-red-700 rounded-md hover:bg-red-200 font-medium transition-colors w-24">Não</button><button onClick={handleConfirmPay} className="px-4 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-medium transition-colors w-24">Sim</button></div></div></Modal>)}
          </div>
      );
  }

  if (view === 'historico') {
      return (
          <div className="space-y-6">
               <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg">
                   <div className="flex justify-between items-center mb-6"><div><h2 className="text-2xl font-bold text-gray-900 dark:text-white flex items-center gap-3"><ClipboardListIcon className="w-8 h-8 text-indigo-600" /> Histórico de Relatórios</h2><p className="text-gray-500 dark:text-gray-400 mt-1">Acompanhe todos os relatórios gerados.</p></div></div>
                   <div className="overflow-x-auto">
                       <table className="min-w-full text-left text-sm">
                           <thead className="bg-gray-50 dark:bg-gray-700/50 text-xs text-gray-700 dark:text-gray-400 uppercase tracking-wider"><tr><th className="px-6 py-3">Data Criação</th><th className="px-6 py-3">Solicitante</th><th className="px-6 py-3">Período</th><th className="px-6 py-3">Valor Total</th><th className="px-6 py-3 text-center">Status</th><th className="px-6 py-3 text-center">Ações</th></tr></thead>
                           <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                               {reports.map(report => (
                                   <tr key={report.id} className="hover:bg-gray-50 dark:hover:bg-gray-700/50 transition-colors">
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{new Date(report.createdAt).toLocaleDateString('pt-BR')}</td>
                                       <td className="px-6 py-4 font-medium text-gray-900 dark:text-white">{report.requester}</td>
                                       <td className="px-6 py-4 text-gray-500 dark:text-gray-400">{report.period}</td>
                                       <td className="px-6 py-4 font-bold text-gray-900 dark:text-white">{formatCurrency(report.totalValue)}</td>
                                       <td className="px-6 py-4 text-center"><span className={`px-2 py-1 rounded-full text-xs font-semibold ${report.status === 'Pago' ? 'bg-green-100 text-green-800' : report.status === 'Transferido' ? 'bg-yellow-100 text-yellow-800' : 'bg-gray-200 text-gray-800'}`}>{report.status}</span></td>
                                       <td className="px-6 py-4 text-center space-x-2"><button onClick={() => onEditReport && onEditReport(report)} className="p-2 text-gray-500 hover:text-indigo-600 dark:text-gray-400 dark:hover:text-indigo-400" title={report.status === 'Rascunho' || report.status === 'Em Aberto' ? "Editar" : "Visualizar"}><EditIcon className="w-5 h-5" /></button><button onClick={() => handleDeleteReport(report.id)} className="p-2 text-gray-500 hover:text-red-600 dark:text-gray-400 dark:hover:text-red-400" title="Excluir"><TrashIcon className="w-5 h-5" /></button></td>
                                   </tr>
                               ))}
                               {reports.length === 0 && <tr><td colSpan={6} className="px-6 py-12 text-center text-gray-500">Nenhum relatório salvo no histórico.</td></tr>}
                           </tbody>
                       </table>
                   </div>
               </div>
          </div>
      );
  }

  if (view === 'config') {
      return (
          <div className="max-w-xl mx-auto space-y-6">
              <div className="bg-white dark:bg-gray-800 p-8 rounded-xl shadow-lg">
                  <div className="flex items-center gap-4 mb-6 border-b border-gray-200 dark:border-gray-700 pb-4">
                      <div className="p-3 bg-indigo-100 dark:bg-indigo-900 rounded-full"><CogIcon className="w-8 h-8 text-indigo-600 dark:text-indigo-400" /></div>
                      <div><h2 className="text-2xl font-bold text-gray-900 dark:text-white">Cadastro de KM</h2><p className="text-gray-500 dark:text-gray-400">Defina o valor padrão a ser pago por quilômetro rodado.</p></div>
                  </div>
                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Valor por Quilômetro (R$)</label>
                          <div className="relative rounded-md shadow-sm"><div className="pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3"><span className="text-gray-500 sm:text-sm">R$</span></div><input type="number" step="0.01" min="0" value={configKmValue} onChange={(e) => setConfigKmValue(parseFloat(e.target.value))} disabled={!isEditingConfig} className={`block w-full rounded-md border-gray-300 dark:border-gray-600 pl-10 focus:ring-indigo-500 focus:border-indigo-500 sm:text-lg py-3 transition-colors ${!isEditingConfig ? 'bg-gray-100 dark:bg-gray-700 text-gray-500 cursor-not-allowed' : 'bg-white dark:bg-gray-600 text-gray-900 dark:text-white'}`} placeholder="0.00" /></div>
                      </div>
                      <div className="pt-4 flex justify-end gap-3">{!isEditingConfig ? (<button onClick={() => setIsEditingConfig(true)} className="flex items-center gap-2 px-6 py-3 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors font-medium shadow-md"><EditIcon className="w-5 h-5" /> Editar Valor</button>) : (<><button onClick={handleCancelConfig} className="px-6 py-3 bg-gray-200 dark:bg-gray-700 text-gray-800 dark:text-gray-200 rounded-lg hover:bg-gray-300 dark:hover:bg-gray-600 transition-colors font-medium">Cancelar</button><button onClick={handleSaveConfig} className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors font-medium shadow-md"><SaveIcon className="w-5 h-5" /> Salvar</button></>)}</div>
                  </div>
              </div>
              {isSuccessModalOpen && (<Modal title="Sucesso" onClose={() => setSuccessModalOpen(false)}><div className="text-center space-y-4 py-4"><div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-green-100"><svg className="h-6 w-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg></div><h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white">Alteração Salva</h3><p className="text-sm text-gray-500 dark:text-gray-400">{modalMessage}</p><div className="mt-6"><button type="button" className="inline-flex justify-center w-full rounded-md border border-transparent shadow-sm px-4 py-2 bg-indigo-600 text-base font-medium text-white hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 sm:text-sm" onClick={() => setSuccessModalOpen(false)}>OK</button></div></div></Modal>)}
          </div>
      );
  }

  if (view === 'analise') {
    return (
        <div className="space-y-6">
             <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                <DashboardCard title="Reembolsos Pagos" value={formatCurrency(analysisData.paid)} icon={CheckCircleIcon} color="bg-green-500" />
                <DashboardCard title="Aguardando Pagamento" value={formatCurrency(analysisData.pending)} icon={ExclamationTriangleIcon} color="bg-yellow-500" />
                <DashboardCard title="Em Aberto (Rascunhos)" value={formatCurrency(analysisData.open)} icon={DocumentReportIcon} color="bg-gray-500" />
             </div>
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                 <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg min-h-[400px]"><h3 className="text-xl font-bold text-gray-900 dark:text-white mb-4">Despesas por Setor</h3>{analysisData.sectorData.length > 0 ? (<ResponsiveContainer width="100%" height={300}><PieChart><Pie data={analysisData.sectorData} cx="50%" cy="50%" innerRadius={60} outerRadius={100} fill="#8884d8" paddingAngle={5} dataKey="value" label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}>{analysisData.sectorData.map((entry, index) => (<Cell key={`cell-${index}`} fill={PIE_COLORS[index % PIE_COLORS.length]} />))}</Pie><RechartsTooltip formatter={(value) => formatCurrency(Number(value))} /><Legend /></PieChart></ResponsiveContainer>) : (<div className="h-full flex flex-col items-center justify-center text-gray-400"><ChartPieIcon className="w-16 h-16 mb-2 opacity-50" /><p>Sem dados de setores registrados.</p></div>)}</div>
                 <div className="bg-white dark:bg-gray-800 p-6 rounded-xl shadow-lg min-h-[400px]"><h3 className="text-xl font-bold text-gray-900 dark:text-white mb-4">Evolução Mensal (Pagos e Transferidos)</h3>{analysisData.monthlyData.length > 0 ? (<ResponsiveContainer width="100%" height={300}><BarChart data={analysisData.monthlyData}><CartesianGrid strokeDasharray="3 3" vertical={false} opacity={0.3} /><XAxis dataKey="name" tick={{fill: '#9CA3AF'}} /><YAxis tick={{fill: '#9CA3AF'}} /><RechartsTooltip contentStyle={{ backgroundColor: '#1F2937', borderColor: '#374151', color: '#F3F4F6' }} formatter={(value) => [formatCurrency(Number(value)), 'Valor']} /><Bar dataKey="value" fill="#6366F1" radius={[4, 4, 0, 0]} /></BarChart></ResponsiveContainer>) : (<div className="h-full flex flex-col items-center justify-center text-gray-400"><DollarIcon className="w-16 h-16 mb-2 opacity-50" /><p>Sem dados mensais disponíveis.</p></div>)}</div>
             </div>
        </div>
    );
  }

  // REEMBOLSO FORM
  return (
    <div className="space-y-6">
        <div className="bg-white dark:bg-gray-800 p-4 sm:p-8 rounded-xl shadow-lg animate-fade-in print:shadow-none print:p-0">
            <div className="flex justify-between items-center mb-6 print:hidden">
                <div className="flex items-center gap-2">{reportToEdit && (<div className={`px-3 py-1 rounded-full text-xs font-semibold ${reportToEdit.status === 'Pago' ? 'bg-green-100 text-green-800' : reportToEdit.status === 'Transferido' ? 'bg-yellow-100 text-yellow-800' : 'bg-gray-200 text-gray-800'}`}>Status: {reportToEdit.status}</div>)}{isReadOnly && <span className="text-xs text-red-500 font-medium ml-2">(Somente Leitura)</span>}</div>
                <div className="flex gap-3">{!isReadOnly ? (<><button onClick={() => handleSaveReportAction('Rascunho')} className="flex items-center gap-2 px-4 py-2 bg-gray-600 text-white rounded-md hover:bg-gray-700 transition-colors shadow-sm"><SaveIcon className="w-5 h-5" /> Salvar Rascunho</button><button onClick={() => handleSaveReportAction('Transferido')} className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors shadow-sm"><CheckCircleIcon className="w-5 h-5" /> Salvar e Transferir</button></>) : (<div className="text-sm text-gray-500 italic mr-2 flex items-center">Este relatório já foi finalizado.</div>)}<button onClick={handlePrint} className="flex items-center gap-2 px-4 py-2 bg-gray-800 text-white rounded-md hover:bg-gray-900 transition-colors shadow-sm"><PrinterIcon className="w-5 h-5" /> Imprimir</button></div>
            </div>
            <div className={`border border-gray-300 bg-white text-gray-900 print:border-none shadow-sm ${isReadOnly ? 'opacity-90' : ''}`}>
                <div className="p-6 border-b border-gray-300 bg-gray-50 flex items-center justify-center"><h1 className="text-2xl font-bold text-gray-800 uppercase tracking-wide">Relatório de Reembolso de Despesas</h1></div>
                <div className="p-6 grid grid-cols-12 gap-6 bg-white">
                    <div className="col-span-12 md:col-span-6 space-y-3">
                         <div className="flex items-center"><label className="w-40 font-semibold bg-gray-100 px-3 py-2 border border-gray-300 text-sm text-gray-700">Nome Solicitante</label><input type="text" value={solicitante} onChange={(e) => setSolicitante(e.target.value)} disabled={isReadOnly} className="flex-1 border border-gray-300 border-l-0 px-3 py-2 outline-none focus:bg-gray-50 text-sm transition-colors disabled:bg-gray-50 disabled:text-gray-500" /></div>
                         <div className="flex items-center"><label className="w-40 font-semibold bg-gray-100 px-3 py-2 border border-gray-300 text-sm text-gray-700">Setor</label><input type="text" value={setor} onChange={(e) => setSetor(e.target.value)} disabled={isReadOnly} className="flex-1 border border-gray-300 border-l-0 px-3 py-2 outline-none focus:bg-gray-50 text-sm transition-colors disabled:bg-gray-50 disabled:text-gray-500" /></div>
                         <div className="flex items-center"><label className="w-40 font-semibold bg-gray-100 px-3 py-2 border border-gray-300 text-sm text-gray-700">Período</label><div className="flex-1 border border-gray-300 border-l-0 px-3 py-2 flex items-center gap-2 bg-white"><span className="text-sm text-gray-500 font-medium">De:</span><input type="date" value={periodStart} onChange={(e) => setPeriodStart(e.target.value)} disabled={isReadOnly} className="outline-none text-sm bg-transparent text-gray-700 font-medium disabled:text-gray-500" /><span className="text-gray-300 mx-2">|</span><span className="text-sm text-gray-500 font-medium">Até:</span><input type="date" value={periodEnd} onChange={(e) => setPeriodEnd(e.target.value)} disabled={isReadOnly} className="outline-none text-sm bg-transparent text-gray-700 font-medium disabled:text-gray-500" /></div></div>
                    </div>
                    <div className="col-span-12 md:col-span-6 flex flex-col items-end"><div className="flex items-center"><label className="font-semibold bg-gray-100 px-3 py-2 border border-gray-300 text-sm text-gray-700">Reembolso por Km</label><div className="flex items-center border border-gray-300 border-l-0 px-3 py-2 bg-gray-50 w-32"><span className="text-sm mr-1 text-gray-500">R$</span><input type="number" step="0.01" value={valorPorKm} readOnly className="w-full outline-none text-right font-medium text-sm bg-transparent text-gray-600 cursor-not-allowed" /></div></div></div>
                </div>
                <div className="overflow-x-auto p-6 pt-0">
                    <table className="w-full border-collapse border border-gray-300 text-sm">
                        <thead><tr className="bg-gray-100 text-gray-700 font-bold text-center"><th className="border border-gray-300 p-2 w-28">Data</th><th className="border border-gray-300 p-2">Descrição da Viagem</th><th className="border border-gray-300 p-2 w-32">Origem</th><th className="border border-gray-300 p-2 w-32">Destino</th><th className="border border-gray-300 p-2 w-24">Km Rodado</th><th className="border border-gray-300 p-2 w-28">Reembolso Km</th><th className="border border-gray-300 p-2 w-24">Pedágio</th><th className="border border-gray-300 p-2 w-28">Total Reembolso</th><th className="border border-gray-300 p-1 w-8 print:hidden"></th></tr></thead>
                        <tbody>
                            {items.map((item) => {
                                const reembolsoItem = Math.ceil((item.km * valorPorKm) * 100) / 100;
                                const totalItem = Math.ceil((reembolsoItem + item.toll) * 100) / 100;
                                return (<tr key={item.id} className="text-center group hover:bg-gray-50"><td className="border border-gray-300 p-0"><input type="date" className="w-full h-full p-2 text-center outline-none bg-transparent disabled:text-gray-500" value={item.date} onChange={(e) => handleItemChange(item.id, 'date', e.target.value)} disabled={isReadOnly} /></td><td className="border border-gray-300 p-0"><input type="text" className="w-full h-full p-2 outline-none bg-transparent disabled:text-gray-500" value={item.description} onChange={(e) => handleItemChange(item.id, 'description', e.target.value)} disabled={isReadOnly} /></td><td className="border border-gray-300 p-0"><input type="text" className="w-full h-full p-2 outline-none bg-transparent disabled:text-gray-500" value={item.origin} onChange={(e) => handleItemChange(item.id, 'origin', e.target.value)} disabled={isReadOnly} /></td><td className="border border-gray-300 p-0"><input type="text" className="w-full h-full p-2 outline-none bg-transparent disabled:text-gray-500" value={item.destination} onChange={(e) => handleItemChange(item.id, 'destination', e.target.value)} disabled={isReadOnly} /></td><td className="border border-gray-300 p-0"><input type="number" className="w-full h-full p-2 text-center outline-none bg-transparent disabled:text-gray-500" value={item.km || ''} onChange={(e) => handleItemChange(item.id, 'km', parseFloat(e.target.value) || 0)} disabled={isReadOnly} /></td><td className="border border-gray-300 p-2 bg-gray-50 text-gray-700 font-medium">{formatCurrency(reembolsoItem)}</td><td className="border border-gray-300 p-0"><div className="flex items-center h-full px-1"><span className="text-xs text-gray-400 mr-1">R$</span><input type="number" className="w-full h-full py-2 text-right outline-none bg-transparent disabled:text-gray-500" value={item.toll || ''} onChange={(e) => handleItemChange(item.id, 'toll', parseFloat(e.target.value) || 0)} disabled={isReadOnly} /></div></td><td className="border border-gray-300 p-2 bg-gray-100 font-bold text-gray-900">{formatCurrency(totalItem)}</td><td className="border border-gray-300 p-0 print:hidden">{!isReadOnly && (<button onClick={() => handleRemoveItem(item.id)} className="w-full h-full flex items-center justify-center text-gray-400 hover:text-red-500 hover:bg-red-50 transition-colors" title="Remover linha"><TrashIcon className="w-4 h-4" /></button>)}</td></tr>);
                            })}
                        </tbody>
                        <tfoot><tr className="bg-gray-200 font-bold text-gray-800"><td colSpan={4} className="border border-gray-300 p-2 text-right pr-4 uppercase text-xs tracking-wider">Total Geral</td><td className="border border-gray-300 p-2 text-center">{totals.km}</td><td className="border border-gray-300 p-2 text-center">{formatCurrency(totals.reembolsoKm)}</td><td className="border border-gray-300 p-2 text-center">{formatCurrency(totals.toll)}</td><td className="border border-gray-300 p-2 text-center text-gray-900 bg-gray-300">{formatCurrency(totals.total)}</td><td className="border border-gray-300 p-1 print:hidden"></td></tr></tfoot>
                    </table>
                </div>
            </div>
            {!isReadOnly && (<div className="mt-4 print:hidden"><button onClick={handleAddItem} className="flex items-center gap-2 px-4 py-2 bg-white text-indigo-600 rounded-md border border-indigo-200 hover:bg-indigo-50 hover:border-indigo-300 transition-colors shadow-sm"><PlusIcon className="w-4 h-4" /> Adicionar Linha</button></div>)}
            <div className="mt-8 text-xs text-gray-400 text-center print:block hidden">Relatório gerado pelo sistema Orner em {new Date().toLocaleDateString('pt-BR')}</div>
        </div>
        {isSuccessModalOpen && (<Modal title="Sucesso" onClose={() => setSuccessModalOpen(false)}><div className="text-center space-y-4 py-4"><div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-green-100"><svg className="h-6 w-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M5 13l4 4L19 7"></path></svg></div><h3 className="text-lg leading-6 font-medium text-gray-900 dark:text-white">Ação Realizada</h3><p className="text-sm text-gray-500 dark:text-gray-400">{modalMessage}</p><div className="mt-6"><button type="button" className="inline-flex justify-center w-full rounded-md border border-transparent shadow-sm px-4 py-2 bg-indigo-600 text-base font-medium text-white hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 sm:text-sm" onClick={() => setSuccessModalOpen(false)}>OK</button></div></div></Modal>)}
        {isTransferModalOpen && (<Modal title="Confirmar Transferência" onClose={() => setTransferModalOpen(false)}><div className="space-y-6"><div className="text-center"><div className="mx-auto flex items-center justify-center h-12 w-12 rounded-full bg-yellow-100 mb-4"><span className="text-2xl font-bold text-yellow-600">?</span></div><h3 className="text-lg font-medium text-gray-900 dark:text-white">Deseja Realmente Transferir?</h3><p className="text-sm text-gray-500 dark:text-gray-400 mt-2">Ao transferir, o relatório será finalizado e você <strong>não poderá mais alterá-lo</strong>.</p></div><div className="flex justify-center gap-4"><button onClick={() => setTransferModalOpen(false)} className="px-6 py-2 bg-red-100 text-red-700 rounded-md hover:bg-red-200 font-medium transition-colors w-24">Não</button><button onClick={() => { setTransferModalOpen(false); executeSave('Transferido'); }} className="px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 font-medium transition-colors w-24">Sim</button></div></div></Modal>)}
    </div>
  );
};

export default RelatoriosPage;

import React, { useState, useEffect } from 'react';
import Modal from '../components/Modal';
import { CalculatorIcon, SaveIcon, AddIcon, TrashIcon, EditIcon, CheckCircleIcon, DollarIcon, CubeIcon } from '../assets/icons';
import type { NovoOrcamentoPageProps, OrcamentoVariant, SavedOrcamento } from '../types';
import { dataService } from '../services/dataService';

// Helper to format numbers as BRL currency with rounding up
const formatCurrency = (value: number) => {
    if (isNaN(value)) return 'R$ 0,00';
    const rounded = Math.ceil(value * 100) / 100;
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(rounded);
};

const roundUp = (value: number) => Math.ceil(value * 100) / 100;

const NovoOrcamentoPage = ({ setCurrentPage, orcamentoToEdit, clearEditingOrcamento }: NovoOrcamentoPageProps): React.ReactElement => {
    const [isModalOpen, setModalOpen] = useState(false);
    const [desiredMargin, setDesiredMargin] = useState('');
    const [isRenameModalOpen, setRenameModalOpen] = useState(false);
    const [tempVariantName, setTempVariantName] = useState('');
    const [isSaveModalOpen, setSaveModalOpen] = useState(false);

    const initialFormState = {
        dataOrcamento: new Date().toISOString().split('T')[0],
        nomeCliente: '',
        revendedor: '',
        custoSistema: 14687.02,
        maoDeObraGeral: 6490.68,
        visitaTecnicaCusto: 400,
        projetoHomologacaoCusto: 600,
        terceiroInstalacaoQtd: 12,
        terceiroInstalacaoCusto: 120,
        custoViagem: 0,
        adequacaoLocalCusto: 0,
        disjuntoresQtd: 1,
        disjuntoresCusto: 80,
        dpsQtd: 2,
        dpsCusto: 60,
        cabosFaseQtd: 30,
        cabosFaseCusto: 7,
        cabosNeutroQtd: 30,
        cabosNeutroCusto: 7,
        cabosTerraQtd: 30,
        cabosTerraCusto: 7,
        conectoresWagoQtd: 4,
        conectoresWagoCusto: 7,
        placaIdQtd: 2,
        placaIdCusto: 25,
        extraItems: [] as { id: string; name: string; quantity: number; cost: number }[],
        nfServicoPerc: 6,
        comissaoVendasOpcao: 'Não',
        comissaoVendasPerc: 3,
        descontoAplicadoPerc: 0,
    };

    const [variants, setVariants] = useState<OrcamentoVariant[]>([
        { id: '1', name: 'Opção 1', isPrincipal: true, formState: initialFormState, calculated: {} }
    ]);
    const [activeVariantId, setActiveVariantId] = useState<string>('1');
    const [formState, setFormState] = useState(initialFormState);
    const [calculated, setCalculated] = useState<any>({});

    useEffect(() => {
        const today = new Date().toISOString().split('T')[0];

        if (orcamentoToEdit) {
            let loadedVariants: OrcamentoVariant[] = [];

            if (orcamentoToEdit.variants && orcamentoToEdit.variants.length > 0) {
                loadedVariants = orcamentoToEdit.variants.map(v => ({
                    ...v,
                    formState: {
                        ...v.formState,
                        dataOrcamento: today
                    }
                }));
            } else if (orcamentoToEdit.formState) {
                loadedVariants = [{
                    id: '1',
                    name: 'Opção 1',
                    isPrincipal: true,
                    formState: { 
                        ...initialFormState, 
                        ...orcamentoToEdit.formState, 
                        dataOrcamento: today,
                        extraItems: orcamentoToEdit.formState.extraItems || [] 
                    }, 
                    calculated: orcamentoToEdit.calculated || {}
                }];
            }

            if (loadedVariants.length > 0) {
                setVariants(loadedVariants);
                const firstVariant = loadedVariants[0];
                setActiveVariantId(firstVariant.id);
                setFormState(firstVariant.formState);
                setCalculated(firstVariant.calculated || {});
            }
        } else {
            const defaultVariant = { id: '1', name: 'Opção 1', isPrincipal: true, formState: initialFormState, calculated: {} };
            setVariants([defaultVariant]);
            setActiveVariantId('1');
            setFormState(initialFormState);
            setCalculated({});
        }
    }, [orcamentoToEdit]);

    useEffect(() => {
        const activeVariant = variants.find(v => v.id === activeVariantId);
        if (activeVariant && JSON.stringify(activeVariant.formState) !== JSON.stringify(formState)) {
             setFormState(activeVariant.formState);
             if (activeVariant.calculated) {
                 setCalculated(activeVariant.calculated);
             }
        }
    }, [activeVariantId, variants]);

    const updateVariantsWithFormState = (newState: any) => {
        setFormState(newState);
        setVariants(prev => prev.map(v => 
            v.id === activeVariantId 
            ? { ...v, formState: newState } 
            : { ...v, 
                formState: { 
                    ...v.formState, 
                    dataOrcamento: newState.dataOrcamento !== formState.dataOrcamento ? newState.dataOrcamento : v.formState.dataOrcamento,
                    nomeCliente: newState.nomeCliente !== formState.nomeCliente ? newState.nomeCliente : v.formState.nomeCliente,
                    revendedor: newState.revendedor !== formState.revendedor ? newState.revendedor : v.formState.revendedor,
                } 
            }
        ));
    }

    const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        const { name, value } = e.target;
        const isNumberInput = e.target.tagName === 'INPUT' && (e.target as HTMLInputElement).type === 'number';
        const newVal = isNumberInput ? parseFloat(value) || 0 : value;
        const updatedFormState = { ...formState, [name]: newVal };
        updateVariantsWithFormState(updatedFormState);
    };

    const addExtraItem = () => {
        const newItem = { id: Date.now().toString(), name: '', quantity: 1, cost: 0 };
        const updatedFormState = { ...formState, extraItems: [...(formState.extraItems || []), newItem] };
        updateVariantsWithFormState(updatedFormState);
    };

    const removeExtraItem = (id: string) => {
        const updatedFormState = { ...formState, extraItems: formState.extraItems.filter(item => item.id !== id) };
        updateVariantsWithFormState(updatedFormState);
    };

    const updateExtraItem = (id: string, field: string, value: any) => {
        const updatedFormState = {
            ...formState,
            extraItems: formState.extraItems.map(item => item.id === id ? { ...item, [field]: value } : item)
        };
        updateVariantsWithFormState(updatedFormState);
    };

    useEffect(() => {
        const instalacaoCusto = formState.terceiroInstalacaoQtd * formState.terceiroInstalacaoCusto;
        const valorVendaSistema = formState.custoSistema;
        const valorVendaMaoDeObra = formState.maoDeObraGeral;
        const totalInstalacao = formState.visitaTecnicaCusto + formState.projetoHomologacaoCusto + instalacaoCusto + formState.custoViagem + formState.adequacaoLocalCusto;

        const totalDisjuntores = formState.disjuntoresQtd * formState.disjuntoresCusto;
        const totalDps = formState.dpsQtd * formState.dpsCusto;
        const totalCabosFase = formState.cabosFaseQtd * formState.cabosFaseCusto;
        const totalCabosNeutro = formState.cabosNeutroQtd * formState.cabosNeutroCusto;
        const totalCabosTerra = formState.cabosTerraQtd * formState.cabosTerraCusto;
        const totalConectores = formState.conectoresWagoQtd * formState.conectoresWagoCusto;
        const totalPlaca = formState.placaIdQtd * formState.placaIdCusto;
        const totalExtras = (formState.extraItems || []).reduce((acc, item) => acc + (item.quantity * item.cost), 0);

        const totalEstrutura = totalDisjuntores + totalDps + totalCabosFase + totalCabosNeutro + totalCabosTerra + totalConectores + totalPlaca + totalExtras;
        const custoMO = formState.maoDeObraGeral + totalInstalacao + totalEstrutura;
        const precoVendaFinal = valorVendaSistema + custoMO;
        const despesasNotaCF = custoMO; 
        const nfServicoValor = roundUp(despesasNotaCF * (formState.nfServicoPerc / 100));
        const comissaoVendasValor = formState.comissaoVendasOpcao === 'Sim' ? roundUp(precoVendaFinal * (formState.comissaoVendasPerc / 100)) : 0;
        const totalCustoTerceiro = formState.visitaTecnicaCusto + formState.projetoHomologacaoCusto + totalEstrutura + instalacaoCusto + formState.custoViagem + formState.adequacaoLocalCusto;

        const valorFinalServico = custoMO;
        const impostos = nfServicoValor;
        const custosTotaisServico = totalCustoTerceiro; 
        const comissoes = comissaoVendasValor;
        const lucroLiquidoServicoSDesc = valorFinalServico - impostos - custosTotaisServico - comissoes;
        const descontoAplicadoValor = roundUp(precoVendaFinal * (formState.descontoAplicadoPerc / 100));
        const lucroLiquidoServicoCDesc = lucroLiquidoServicoSDesc - descontoAplicadoValor;
        const lucroLiquido = lucroLiquidoServicoCDesc;
        const margemLiquida = precoVendaFinal > 0 ? (lucroLiquido / precoVendaFinal) * 100 : 0;
        const valorFinalSistema = precoVendaFinal - descontoAplicadoValor;
        const lucroLiquidoVenda = lucroLiquido;
        const margemFinal = margemLiquida;
        const totalDivisaoLucro = lucroLiquidoVenda;
        const margemLiquidaServico = valorFinalServico > 0 ? (lucroLiquidoServicoCDesc / valorFinalServico) * 100 : 0;

        const newCalculated = {
            valorVendaSistema: roundUp(valorVendaSistema),
            valorVendaMaoDeObra: roundUp(valorVendaMaoDeObra),
            totalInstalacao: roundUp(totalInstalacao),
            totalEstrutura: roundUp(totalEstrutura),
            custoMO: roundUp(custoMO),
            precoVendaFinal: roundUp(precoVendaFinal),
            despesasNotaCF: roundUp(despesasNotaCF),
            nfServicoValor: nfServicoValor,
            comissaoVendasValor: comissaoVendasValor,
            totalCustoTerceiro: roundUp(totalCustoTerceiro),
            lucroLiquido: roundUp(lucroLiquido),
            margemLiquida,
            valorFinalSistema: roundUp(valorFinalSistema),
            lucroLiquidoVenda: roundUp(lucroLiquidoVenda),
            margemFinal,
            totalDivisaoLucro: roundUp(totalDivisaoLucro),
            valorFinalServico: roundUp(valorFinalServico),
            impostos: impostos,
            custosTotaisServico: roundUp(custosTotaisServico),
            lucroLiquidoServicoSDesc: roundUp(lucroLiquidoServicoSDesc),
            descontoAplicadoValor: descontoAplicadoValor,
            lucroLiquidoServicoCDesc: roundUp(lucroLiquidoServicoCDesc),
            margemLiquidaServico,
        };

        setCalculated(newCalculated);
        setVariants(prev => prev.map(v => v.id === activeVariantId ? { ...v, calculated: newCalculated } : v));
    }, [formState, activeVariantId]);

    const handleMarginCalculation = () => {
        const targetMargin = parseFloat(desiredMargin) / 100;
        if (isNaN(targetMargin)) return;

        const instalacaoCusto = formState.terceiroInstalacaoQtd * formState.terceiroInstalacaoCusto;
        const totalInstalacaoParcial = formState.visitaTecnicaCusto + formState.projetoHomologacaoCusto + instalacaoCusto + formState.custoViagem + formState.adequacaoLocalCusto;
        const totalExtras = (formState.extraItems || []).reduce((acc, item) => acc + (item.quantity * item.cost), 0);
        const totalEstrutura = (formState.disjuntoresQtd * formState.disjuntoresCusto) + (formState.dpsQtd * formState.dpsCusto) + (formState.cabosFaseQtd * formState.cabosFaseCusto) + (formState.cabosNeutroQtd * formState.cabosNeutroCusto) + (formState.cabosTerraQtd * formState.cabosTerraCusto) + (formState.conectoresWagoQtd * formState.conectoresWagoCusto) + (formState.placaIdQtd * formState.placaIdCusto) + totalExtras;

        const C1 = totalInstalacaoParcial + totalEstrutura;
        const C2 = formState.visitaTecnicaCusto + formState.projetoHomologacaoCusto + totalEstrutura + instalacaoCusto + formState.custoViagem + formState.adequacaoLocalCusto;
        const VVS = formState.custoSistema;
        const nfPerc = formState.nfServicoPerc / 100;
        const comPerc = formState.comissaoVendasOpcao === 'Sim' ? formState.comissaoVendasPerc / 100 : 0;
        const descPerc = formState.descontoAplicadoPerc / 100;
        const M_desejada = targetMargin;

        const numerador = C1 * (1 - M_desejada - nfPerc - comPerc - descPerc) - C2 - VVS * (comPerc + descPerc);
        const denominador = M_desejada - 1 + nfPerc + comPerc + descPerc;

        if (denominador === 0) {
            alert("Não é possível calcular a margem com os valores atuais.");
            return;
        }

        let newMOG = Math.ceil((numerador / denominador) * 100) / 100;
        updateVariantsWithFormState({ ...formState, maoDeObraGeral: newMOG });
        setModalOpen(false);
        setDesiredMargin('');
    };

    const handleSaveTrigger = () => {
        if (!formState.nomeCliente.trim()) {
            alert('Por favor, preencha o Nome do Cliente antes de salvar.');
            return;
        }
        setSaveModalOpen(true);
    };

    const executeSave = async () => {
        const budgetToSave: SavedOrcamento = {
            id: orcamentoToEdit ? orcamentoToEdit.id : Date.now(),
            savedAt: new Date().toISOString(),
            status: orcamentoToEdit?.status || 'Em Aberto',
            variants,
        };

        try {
            await dataService.save('orcamentos', budgetToSave);
            setSaveModalOpen(false);
            alert('Projeto salvo com sucesso!');
            clearEditingOrcamento();
            setCurrentPage('ORCAMENTO');
        } catch (e) {
            alert('Erro ao salvar projeto. Tente novamente.');
            console.error(e);
        }
    };

    const addNewVariant = () => {
        const newId = Date.now().toString();
        const activeVariant = variants.find(v => v.id === activeVariantId) || variants[0];
        const newVariant: OrcamentoVariant = {
            id: newId,
            name: `Opção ${variants.length + 1}`,
            isPrincipal: false,
            formState: { ...activeVariant.formState },
            calculated: { ...activeVariant.calculated }
        };
        setVariants([...variants, newVariant]);
        setActiveVariantId(newId);
    };

    const removeVariant = (id: string, e: React.MouseEvent) => {
        e.stopPropagation(); e.preventDefault(); 
        if (variants.length <= 1) { alert("Você precisa ter pelo menos uma opção."); return; }
        if (window.confirm("Tem certeza que deseja excluir esta opção?")) {
            const newVariants = variants.filter(v => v.id !== id);
            setVariants(newVariants);
            if (activeVariantId === id) setActiveVariantId(newVariants[0].id);
        }
    };

    const setPrincipal = (id: string, e: React.MouseEvent) => {
        e.stopPropagation(); e.preventDefault();
        setVariants(prev => prev.map(v => ({ ...v, isPrincipal: v.id === id })));
    };

    const startRename = () => {
        const current = variants.find(v => v.id === activeVariantId);
        if(current) { setTempVariantName(current.name); setRenameModalOpen(true); }
    }

    const finishRename = () => {
