import React, { useMemo, useState, useEffect } from 'react';
import { ChartPieIcon, TableIcon, DollarIcon, TrendUpIcon, PrinterIcon, CalendarIcon, FilterIcon, TrashIcon, UsersIcon } from '../assets/icons';
import DashboardCard from '../components/DashboardCard';
import type { SalesSummaryItem } from '../types';
import { dataService } from '../services/dataService';

const formatCurrency = (value: number) => {
    if (isNaN(value)) return 'R$ 0,00';
    return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2 }).format(value);
};

const formatPercent = (value: number) => {
    if (isNaN(value)) return '0,00%';
    return `${value.toFixed(2).replace('.', ',')}%`;
};

const ResumoVendasPage: React.FC = () => {

    const [salesData, setSalesData] = useState<SalesSummaryItem[]>([]);
    const [isLoading, setIsLoading] = useState(true);

    // Estados para o filtro de data
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');

    useEffect(() => {
        const loadData = async () => {
            setIsLoading(true);
            const data = await dataService.getAll<SalesSummaryItem>('sales_summary');
            setSalesData(data);
            setIsLoading(false);
        };
        loadData();

        // Inicializar com o mês atual por padrão
        const date = new Date();
        const firstDay = new Date(date.getFullYear(), date.getMonth(), 1);
        const lastDay = new Date(date.getFullYear(), date.getMonth() + 1, 0);

        const formatDate = (d: Date) => {
            const year = d.getFullYear();
            const month = String(d.getMonth() + 1).padStart(2, '0');
            const day = String(d.getDate()).padStart(2, '0');
            return `${year}-${month}-${day}`;
        };

        setStartDate(formatDate(firstDay));
        setEndDate(formatDate(lastDay));
    }, []);

    const handleUpdateValue = async (id: number, field: 'invoicedTax' | 'bankFees', value: string) => {
        const numValue = parseFloat(value);
        // Permite valor vazio durante a digitação, trata como 0 se NaN no cálculo
        const safeValue = isNaN(numValue) ? 0 : numValue;

        // Optimistic UI Update
        const updatedData = salesData.map(item => {
            if (item.id === id) {
                const newItem = { ...item, [field]: safeValue };

                // Recalcular Custo Total
                const totalCost = 
                    (newItem.systemCost || 0) +
                    (newItem.homologation || 0) +
                    (newItem.materialCost || 0) +
                    (newItem.installation || 0) +
                    (newItem.technicalVisit || 0) +
                    (newItem.travelCost || 0) +
                    (newItem.localAdjustment || 0) +
                    (newItem.invoicedTax || 0) +
                    (newItem.commission || 0) +
                    (newItem.bankFees || 0);

                const netProfit = (newItem.closedValue || 0) - totalCost;
                const finalMargin = newItem.closedValue > 0 ? (netProfit / newItem.closedValue) * 100 : 0;

                return { ...newItem, totalCost, netProfit, finalMargin };
            }
            return item;
        });

        setSalesData(updatedData);

        // Save to DB
        const itemToSave = updatedData.find(i => i.id === id);
        if (itemToSave) {
            await dataService.save('sales_summary', itemToSave);
        }
    };

    // Filtrar dados com base nas datas
    const filteredSalesData = useMemo(() => {
        return salesData.filter(item => {
            if (startDate && item.date < startDate) return false;
            if (endDate && item.date > endDate) return false;
            return true;
        });
    }, [salesData, startDate, endDate]);

    // Calcular totais dinamicamente (Baseado nos dados FILTRADOS)
    const totals = useMemo(() => {
        return filteredSalesData.reduce((acc, item) => {
            return {
                closedValue: acc.closedValue + item.closedValue,
                systemCost: acc.systemCost + item.systemCost,
                homologation: acc.homologation + item.homologation,
                materialCost: acc.materialCost + item.materialCost,
                installation: acc.installation + item.installation,
                technicalVisit: acc.technicalVisit + (item.technicalVisit || 0),
                travelCost: acc.travelCost + (item.travelCost || 0),
                localAdjustment: acc.localAdjustment + (item.localAdjustment || 0),
                invoicedTax: acc.invoicedTax + item.invoicedTax,
                commission: acc.commission + item.commission,
                bankFees: acc.bankFees + item.bankFees,
                totalCost: acc.totalCost + item.totalCost,
                netProfit: acc.netProfit + item.netProfit,
            };
        }, {
            closedValue: 0, systemCost: 0, homologation: 0, materialCost: 0, installation: 0,
            technicalVisit: 0, travelCost: 0, localAdjustment: 0,
            invoicedTax: 0, commission: 0, bankFees: 0, totalCost: 0, netProfit: 0
        });
    }, [filteredSalesData]);

    const totalValorMO = totals.closedValue - totals.systemCost;
    const avgMargin = totals.closedValue > 0 ? (totals.netProfit / totals.closedValue) * 100 : 0;
    const avgServiceMargin = totalValorMO > 0 ? (totals.netProfit / totalValorMO) * 100 : 0;

    const handlePrint = () => {
        window.print();
    };

    const handleClearFilters = () => {
        setStartDate('');
        setEndDate('');
    };

    if (isLoading) {
        return <div className="flex justify-center p-10"><div className="animate-spin rounded-full h-10 w-10 border-b-2 border-indigo-600"></div></div>;
    }

    return (
        <div className="space-y-6">

            {/* Filtros de Data */}
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4 bg-white dark:bg-gray-800 p-4 rounded-xl shadow-sm border border-gray-100 dark:border-gray-700 print:hidden">
