                        <tfoot className="bg-gray-100 dark:bg-gray-900 font-bold text-gray-900 dark:text-white border-t-2 border-gray-300 dark:border-gray-600">
                            <tr>
                                <td colSpan={2} className="px-4 py-3 text-right sticky left-0 bg-gray-100 dark:bg-gray-900 border-r border-gray-300 dark:border-gray-600">TOTAIS</td>
