                                                                        className="text-red-500 hover:text-red-700 p-1"
                                                                    >
                                                                        <TrashIcon className="w-4 h-4" />
                                                                    </button>
                                                                )}
                                                            </td>
                                                        </tr>
                                                    ))}
                                                </tbody>
                                            </table>
                                        </div>
                                    ) : (
                                        <p className="text-center text-sm text-gray-500 dark:text-gray-400 py-2 bg-gray-50 dark:bg-gray-800 rounded border border-dashed border-gray-300 dark:border-gray-600">
                                            Nenhum material registrado para esta finalização.
                                        </p>
                                    )}
                                </div>

                                <div>
                                    <h4 className="font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2 border-b border-gray-200 dark:border-gray-700 pb-2">
                                        <PhotographIcon className="w-5 h-5 text-indigo-500" />
                                        Registro Fotográfico
                                    </h4>
                                    <div className="grid grid-cols-1 gap-6">
                                        {[
                                            { key: 'placas', label: 'Placas Instaladas', max: 10 },
                                            { key: 'inversores', label: 'Micro Inversores / Inversor', max: 10 },
                                            { key: 'aterramento', label: 'Aterramento Placas', max: 10 },
                                            { key: 'quadroEnergia', label: 'Quadro de Energia Interno', max: 5 },
                                            { key: 'medidor', label: 'Medidor', max: 5 },
                                            { key: 'disjuntorDPS', label: 'Disjuntor e DPS do Medidor', max: 5 },
                                            { key: 'padraoPoste', label: 'Padrão (Poste) c/ Placas', max: 1 }
                                        ].map((item) => (
                                            <div key={item.key} className="p-4 border border-gray-200 dark:border-gray-700 rounded-lg bg-gray-50 dark:bg-gray-800 shadow-sm">
                                                <div className="flex justify-between items-center mb-3">
                                                    <div>
                                                        <span className="text-sm font-bold text-gray-700 dark:text-gray-300 block">{item.label}</span>
                                                        <span className="text-xs text-gray-500">Máx: {item.max} fotos</span>
                                                    </div>
                                                    {!isReadOnly && (
                                                        <label className="text-xs bg-indigo-50 dark:bg-indigo-900/30 text-indigo-600 dark:text-indigo-400 px-3 py-1.5 rounded cursor-pointer border border-indigo-200 dark:border-indigo-800 hover:bg-indigo-100 transition-colors">
                                                            + Adicionar Foto
                                                            <input 
                                                                type="file" 
                                                                className="hidden" 
                                                                accept="image/*"
                                                                onChange={(e) => handleCheckOutPhotoUpload(item.key as any, e)}
                                                                disabled={(checkOutFormData.fotos as any)[item.key]?.length >= item.max}
                                                            />
                                                        </label>
                                                    )}
                                                </div>

                                                <div className="flex flex-wrap gap-2">
                                                    {(checkOutFormData.fotos as any)[item.key] && (checkOutFormData.fotos as any)[item.key].length > 0 ? (
                                                        (checkOutFormData.fotos as any)[item.key].map((imgSrc: string, idx: number) => (
                                                            <div key={idx} className="relative group w-16 h-16">
                                                                <div 
                                                                    className="w-full h-full rounded-md bg-cover bg-center border border-gray-300 cursor-pointer shadow-sm hover:shadow-md transition-all"
                                                                    style={{ backgroundImage: `url(${imgSrc})` }}
                                                                    onClick={() => setPreviewImage(imgSrc)}
                                                                ></div>
                                                                {!isReadOnly && (
                                                                    <button
                                                                        type="button"
                                                                        onClick={() => handleRemoveCheckOutPhoto(item.key as any, idx)}
                                                                        className="absolute -top-1.5 -right-1.5 bg-white rounded-full text-red-500 hover:text-red-700 shadow-sm opacity-0 group-hover:opacity-100 transition-opacity"
                                                                    >
                                                                        <XCircleIcon className="w-4 h-4" />
                                                                    </button>
                                                                )}
                                                            </div>
                                                        ))
                                                    ) : (
                                                        <div className="w-full py-2 text-center text-xs text-gray-400 italic border-2 border-dashed border-gray-200 dark:border-gray-700 rounded-md">
                                                            Nenhuma foto adicionada
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                </div>

                                <div className="p-4 bg-orange-50 dark:bg-orange-900/10 rounded-lg border border-orange-200 dark:border-orange-800">
                                    <h4 className="font-bold text-orange-800 dark:text-orange-200 mb-3 flex items-center gap-2">
                                        <DocumentReportIcon className="w-5 h-5" />
                                        Validação Concessionária (ENEL)
                                    </h4>
                                    <RadioGroup 
                                        label="Vídeo de Antilhamento foi feito?" 
                                        options={['Sim', 'Não', 'Não é Enel']} 
                                        value={checkOutFormData.enelVideoAntilhamento} 
                                        onChange={(v) => handleCheckOutInputChange('enelVideoAntilhamento', v)} 
                                        disabled={isReadOnly}
                                    />
                                    <RadioGroup 
                                        label="Link do vídeo enviado para Youtube?" 
                                        options={['Sim', 'Não', 'Não é Enel']} 
                                        value={checkOutFormData.enelLinkYoutube} 
                                        onChange={(v) => handleCheckOutInputChange('enelLinkYoutube', v)} 
                                        disabled={isReadOnly}
                                    />
                                </div>

                                <div>
                                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Observações Finais</label>
                                    <textarea 
                                        rows={3} 
                                        value={checkOutFormData.observacoesFinais} 
                                        onChange={e => handleCheckOutInputChange('observacoesFinais', e.target.value)} 
                                        disabled={isReadOnly}
                                        className={`w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 text-sm focus:ring-indigo-500 focus:border-indigo-500 transition-colors ${isReadOnly ? 'opacity-60 cursor-not-allowed' : ''}`}
                                        placeholder="Comentários adicionais sobre a entrega..."
                                    />
                                </div>

                                <div className="flex justify-between pt-4 border-t border-gray-200 dark:border-gray-700">
                                    <button type="button" onClick={() => setModalOpen(false)} className="px-4 py-2 bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 transition-colors">
                                        {isReadOnly ? 'Fechar' : 'Cancelar'}
                                    </button>
                                    {!isReadOnly && (
                                        <button type="submit" className="px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors flex items-center gap-2 shadow-sm">
                                            <CheckCircleIcon className="w-5 h-5" />
                                            Salvar Check-Out
                                        </button>
                                    )}
                                </div>
                            </form>
                        </div>
                    ) : (
                        // --- MAINTENANCE FORM ---
                        <div className="max-h-[60vh] overflow-y-auto pr-2 custom-scrollbar">
                            <form onSubmit={(e) => { e.preventDefault(); handleSave(); }} className="space-y-6">
                                {/* Maintenance Fields... (Same structure, logic via State) */}
                                <div className="p-4 bg-gray-50 dark:bg-gray-700/30 rounded-lg border border-gray-200 dark:border-gray-700">
                                    <h4 className="font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                                        <UsersIcon className="w-5 h-5 text-indigo-500" />
                                        Dados da Visita
                                    </h4>
                                    <Input 
                                        label="Nome do Cliente / Obra" 
                                        value={maintenanceFormData.nomeCliente} 
                                        onChange={(v: string) => handleMaintenanceInputChange('nomeCliente', v)} 
                                        disabled={isReadOnly}
                                        placeholder="Nome completo do cliente"
                                    />
                                    <div className="grid grid-cols-2 gap-4">
                                        <Input 
                                            label="Data da Visita" 
                                            type="date"
                                            value={maintenanceFormData.dataVisita} 
                                            onChange={(v: string) => handleMaintenanceInputChange('dataVisita', v)} 
                                            disabled={isReadOnly}
                                        />
                                        <Input 
                                            label="Técnico Responsável" 
                                            value={maintenanceFormData.tecnicoResponsavel} 
                                            onChange={(v: string) => handleMaintenanceInputChange('tecnicoResponsavel', v)} 
                                            disabled={isReadOnly}
                                        />
                                    </div>
                                    <RadioGroup 
                                        label="Tipo de Manutenção" 
                                        options={['Preventiva', 'Corretiva', 'Garantia']} 
                                        value={maintenanceFormData.tipoManutencao} 
                                        onChange={(v) => handleMaintenanceInputChange('tipoManutencao', v)} 
                                        disabled={isReadOnly}
                                    />
                                </div>

                                <div className="p-4 bg-white dark:bg-gray-800 rounded-lg border border-gray-200 dark:border-gray-700 space-y-4">
                                    <h4 className="font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2">
                                        <ClipboardListIcon className="w-5 h-5 text-indigo-500" />
                                        Diagnóstico e Solução
                                    </h4>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Defeito Relatado / Motivo</label>
                                        <textarea 
                                            rows={2} 
                                            value={maintenanceFormData.defeitoRelatado} 
                                            onChange={e => handleMaintenanceInputChange('defeitoRelatado', e.target.value)} 
                                            disabled={isReadOnly}
                                            className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 text-sm focus:ring-indigo-500 focus:border-indigo-500"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Diagnóstico Técnico</label>
                                        <textarea 
                                            rows={2} 
                                            value={maintenanceFormData.diagnosticoTecnico} 
                                            onChange={e => handleMaintenanceInputChange('diagnosticoTecnico', e.target.value)} 
                                            disabled={isReadOnly}
                                            className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 text-sm focus:ring-indigo-500 focus:border-indigo-500"
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Solução Aplicada</label>
                                        <textarea 
                                            rows={2} 
                                            value={maintenanceFormData.solucaoAplicada} 
                                            onChange={e => handleMaintenanceInputChange('solucaoAplicada', e.target.value)} 
                                            disabled={isReadOnly}
                                            className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-gray-50 dark:bg-gray-700 p-2 text-sm focus:ring-indigo-500 focus:border-indigo-500"
                                        />
                                    </div>
                                    <RadioGroup 
                                        label="Houve troca de equipamento?" 
                                        options={['Sim', 'Não']} 
                                        value={maintenanceFormData.trocaEquipamento} 
                                        onChange={(v) => handleMaintenanceInputChange('trocaEquipamento', v)} 
                                        disabled={isReadOnly}
                                    />
                                </div>

                                {/* Materiais Utilizados Section (Maintenance) */}
                                <div>
                                    <h4 className="font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2 border-b border-gray-200 dark:border-gray-700 pb-2">
                                        <CubeIcon className="w-5 h-5 text-indigo-500" />
                                        Peças / Materiais Utilizados
                                    </h4>

                                    {!isReadOnly && (
                                        <div className="bg-gray-50 dark:bg-gray-700/50 p-4 rounded-lg border border-gray-200 dark:border-gray-600 mb-4">
                                            <div className="flex flex-col sm:flex-row gap-3 items-end">
                                                <div className="flex-1 w-full">
                                                    <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">Selecionar Item do Estoque</label>
                                                    <select
                                                        value={selectedMaterialId}
                                                        onChange={(e) => setSelectedMaterialId(e.target.value)}
                                                        className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 text-sm focus:ring-indigo-500 focus:border-indigo-500"
                                                    >
                                                        <option value="">Selecione...</option>
                                                        {availableStock.map(item => (
                                                            <option key={item.id} value={item.id}>
                                                                {item.name} ({item.unit})
                                                            </option>
                                                        ))}
                                                    </select>
                                                </div>
                                                <div className="w-full sm:w-24">
                                                    <label className="block text-xs font-medium text-gray-700 dark:text-gray-300 mb-1">Qtd</label>
                                                    <input 
                                                        type="number" 
                                                        min="1" 
                                                        value={selectedMaterialQty} 
                                                        onChange={(e) => setSelectedMaterialQty(Number(e.target.value))} 
                                                        className="w-full rounded-md border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 p-2 text-sm focus:ring-indigo-500 focus:border-indigo-500"
                                                    />
                                                </div>
                                                <button 
                                                    type="button" 
                                                    onClick={handleAddMaintenanceMaterial}
                                                    className="w-full sm:w-auto px-4 py-2 bg-indigo-600 text-white rounded-md hover:bg-indigo-700 transition-colors flex items-center justify-center gap-2"
                                                >
                                                    <AddIcon className="w-5 h-5" /> Adicionar
                                                </button>
                                            </div>
                                        </div>
                                    )}

                                    {maintenanceFormData.materiaisUtilizados && maintenanceFormData.materiaisUtilizados.length > 0 ? (
                                        <div className="border rounded-lg overflow-hidden border-gray-200 dark:border-gray-600">
                                            <table className="min-w-full text-sm">
                                                <thead className="bg-gray-100 dark:bg-gray-700">
                                                    <tr>
                                                        <th className="px-4 py-2 text-left">Item</th>
                                                        <th className="px-4 py-2 text-right">Qtd</th>
                                                        <th className="px-4 py-2 text-center w-10"></th>
                                                    </tr>
                                                </thead>
                                                <tbody className="divide-y divide-gray-200 dark:divide-gray-600 bg-white dark:bg-gray-800">
                                                    {maintenanceFormData.materiaisUtilizados.map((item, idx) => (
                                                        <tr key={idx}>
                                                            <td className="px-4 py-2 text-gray-800 dark:text-white">{item.name}</td>
                                                            <td className="px-4 py-2 text-right font-medium">{item.quantity} {item.unit}</td>
                                                            <td className="px-4 py-2 text-center">
                                                                {!isReadOnly && (
                                                                    <button 
                                                                        type="button" 
                                                                        onClick={() => handleRemoveMaintenanceMaterial(idx)}
                                                                        className="text-red-500 hover:text-red-700 p-1"
                                                                    >
                                                                        <TrashIcon className="w-4 h-4" />
                                                                    </button>
                                                                )}
                                                            </td>
                                                        </tr>
                                                    ))}
                                                </tbody>
                                            </table>
                                        </div>
                                    ) : (
                                        <p className="text-center text-sm text-gray-500 dark:text-gray-400 py-2 bg-gray-50 dark:bg-gray-800 rounded border border-dashed border-gray-300 dark:border-gray-600">
                                            Nenhum material registrado.
                                        </p>
                                    )}
                                </div>

                                {/* Photos Section */}
                                <div>
                                    <h4 className="font-bold text-gray-800 dark:text-white mb-3 flex items-center gap-2 border-b border-gray-200 dark:border-gray-700 pb-2">
                                        <PhotographIcon className="w-5 h-5 text-indigo-500" />
                                        Evidências Fotográficas
                                    </h4>

                                    {/* Antes */}
                                    <div className="mb-4">
                                        <div className="flex justify-between items-center mb-2">
                                            <span className="text-sm font-semibold text-gray-700 dark:text-gray-300">Antes da Manutenção</span>
                                            {!isReadOnly && (
                                                <label className="text-xs bg-indigo-50 text-indigo-600 px-3 py-1 rounded cursor-pointer hover:bg-indigo-100">
                                                    + Adicionar
                                                    <input type="file" className="hidden" accept="image/*" onChange={(e) => handleMaintenancePhotoUpload('fotosAntes', e)} />
                                                </label>
                                            )}
                                        </div>
                                        <div className="flex flex-wrap gap-2">
                                            {maintenanceFormData.fotosAntes.length > 0 ? maintenanceFormData.fotosAntes.map((img, idx) => (
                                                <div key={idx} className="relative w-16 h-16 group">
                                                    <div className="w-full h-full bg-cover bg-center rounded cursor-pointer border border-gray-300" style={{backgroundImage: `url(${img})`}} onClick={() => setPreviewImage(img)}></div>
                                                    {!isReadOnly && <button type="button" onClick={() => handleRemoveMaintenancePhoto('fotosAntes', idx)} className="absolute -top-1 -right-1 bg-white rounded-full text-red-500 opacity-0 group-hover:opacity-100"><XCircleIcon className="w-4 h-4"/></button>}
                                                </div>
                                            )) : <span className="text-xs text-gray-400 italic">Sem fotos.</span>}
                                        </div>
                                    </div>

                                    {/* Depois */}
                                    <div>
                                        <div className="flex justify-between items-center mb-2">
                                            <span className="text-sm font-semibold text-gray-700 dark:text-gray-300">Depois da Manutenção</span>
                                            {!isReadOnly && (
                                                <label className="text-xs bg-indigo-50 text-indigo-600 px-3 py-1 rounded cursor-pointer hover:bg-indigo-100">
                                                    + Adicionar
                                                    <input type="file" className="hidden" accept="image/*" onChange={(e) => handleMaintenancePhotoUpload('fotosDepois', e)} />
                                                </label>
                                            )}
                                        </div>
                                        <div className="flex flex-wrap gap-2">
                                            {maintenanceFormData.fotosDepois.length > 0 ? maintenanceFormData.fotosDepois.map((img, idx) => (
                                                <div key={idx} className="relative w-16 h-16 group">
                                                    <div className="w-full h-full bg-cover bg-center rounded cursor-pointer border border-gray-300" style={{backgroundImage: `url(${img})`}} onClick={() => setPreviewImage(img)}></div>
                                                    {!isReadOnly && <button type="button" onClick={() => handleRemoveMaintenancePhoto('fotosDepois', idx)} className="absolute -top-1 -right-1 bg-white rounded-full text-red-500 opacity-0 group-hover:opacity-100"><XCircleIcon className="w-4 h-4"/></button>}
                                                </div>
                                            )) : <span className="text-xs text-gray-400 italic">Sem fotos.</span>}
                                        </div>
                                    </div>
                                </div>

                                <div className="flex justify-between pt-4 border-t border-gray-200 dark:border-gray-700">
                                    <button type="button" onClick={() => setModalOpen(false)} className="px-4 py-2 bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 rounded-md hover:bg-gray-300 transition-colors">
                                        {isReadOnly ? 'Fechar' : 'Cancelar'}
                                    </button>
                                    {!isReadOnly && (
                                        <button type="submit" className="px-6 py-2 bg-green-600 text-white rounded-md hover:bg-green-700 transition-colors flex items-center gap-2 shadow-sm">
                                            <CheckCircleIcon className="w-5 h-5" />
                                            Salvar Manutenção
                                        </button>
                                    )}
                                </div>
                            </form>
                        </div>
                    )}
                </Modal>
            )}
        </div>
    );
};

export default CheckListPage;
